import { Controller } from "@hotwired/stimulus"

// Drives the NFL Stats Archive dataset builder: chip selection state (seasons,
// weeks, playoff rounds, playoff seasons, categories), the live build-bar
// summary, the terms-confirm flow, and the per-category schema dialog.
//
// Selection state lives in aria-pressed on the chip buttons — the server
// renders the default selection (all categories, current season, all weeks)
// and this controller only toggles attributes, so styling stays in CSS
// attribute selectors and no class names are hardcoded here.
//
// Gated mode (data-archive-builder-gated-value="true"): every selection
// action instead opens the unlock dialog. The catalog stays browsable; the
// build bar carries pricing and the unlock CTA.
export default class extends Controller {
  static targets = [
    "seasonChip", "allSeasons",
    "weekChip", "allWeeks", "weeksBox", "weeksPanel",
    "roundChip", "allRounds", "postseasonBox", "postseasonPanel",
    "pastPlayoffsChip", "currentPlayoffsChip", "allPastPlayoffs",
    "categoryToggle", "selectAll",
    "summary", "agreeToggle", "buildButton",
    "schemaDialog", "schemaLead", "schemaRest", "schemaPlus", "schemaEarliest", "schemaPlayerRow",
    "termsDialog", "unlockDialog",
    "buildDialog", "statusFrame",
  ]

  static values = {
    gated: Boolean,
    categoryCount: Number,
    currentWeek: Number,
  }

  // ── Seasons ──

  toggleSeason(event) {
    if (this.gate()) return
    this.flip(event.currentTarget)
    this.refresh()
  }

  toggleAllSeasons() {
    if (this.gate()) return
    const allOn = this.seasonChipTargets.every((chip) => this.pressed(chip))
    this.seasonChipTargets.forEach((chip) => {
      this.press(chip, allOn ? chip.dataset.current === "true" : true)
    })
    this.refresh()
  }

  // ── Current-season weeks ──

  toggleWeeks(event) {
    this.toggleDisclosure(event.currentTarget, this.weeksPanelTarget)
  }

  toggleWeek(event) {
    if (this.gate()) return
    const chip = event.currentTarget
    if (chip.dataset.noData === "true") return
    this.flip(chip)
    const available = this.availableWeekChips()
    const selected = available.filter((c) => this.pressed(c))
    // An empty or complete manual selection collapses back to "All weeks".
    if (selected.length === 0 || selected.length === available.length) this.selectAllWeeks()
    else this.press(this.allWeeksTarget, false)
    this.refresh()
  }

  toggleAllWeeks() {
    if (this.gate()) return
    this.selectAllWeeks()
    this.refresh()
  }

  // ── Current-season postseason rounds ──

  togglePostseason(event) {
    this.toggleDisclosure(event.currentTarget, this.postseasonPanelTarget)
  }

  toggleRound(event) {
    if (this.gate()) return
    const chip = event.currentTarget
    if (chip.dataset.noData === "true") return
    this.flip(chip)
    this.syncAllChip(this.allRoundsTarget, this.availableRoundChips())
    this.refresh()
  }

  toggleAllRounds() {
    if (this.gate()) return
    const available = this.availableRoundChips()
    if (available.length === 0) return
    const allOn = available.every((chip) => this.pressed(chip))
    available.forEach((chip) => this.press(chip, !allOn))
    this.press(this.allRoundsTarget, !allOn)
    this.refresh()
  }

  // ── Playoff seasons ──

  togglePastPlayoffs(event) {
    if (this.gate()) return
    this.flip(event.currentTarget)
    this.syncAllChip(this.allPastPlayoffsTarget, this.pastPlayoffsChipTargets)
    this.refresh()
  }

  toggleCurrentPlayoffs(event) {
    if (this.gate()) return
    this.flip(event.currentTarget)
    this.refresh()
  }

  toggleAllPastPlayoffs() {
    if (this.gate()) return
    const allOn = this.pastPlayoffsChipTargets.every((chip) => this.pressed(chip))
    this.pastPlayoffsChipTargets.forEach((chip) => this.press(chip, !allOn))
    this.press(this.allPastPlayoffsTarget, !allOn)
    this.refresh()
  }

  // ── Categories ──

  toggleCategory(event) {
    if (this.gate()) return
    this.flip(event.currentTarget)
    this.syncAllChip(this.selectAllTarget, this.categoryToggleTargets)
    this.refresh()
  }

  toggleAllCategories() {
    if (this.gate()) return
    const allOn = this.categoryToggleTargets.every((chip) => this.pressed(chip))
    this.categoryToggleTargets.forEach((chip) => this.press(chip, !allOn))
    this.press(this.selectAllTarget, !allOn)
    this.refresh()
  }

  // ── Terms confirm ──

  toggleAgree() {
    if (this.gate()) return
    if (this.pressed(this.agreeToggleTarget)) {
      this.press(this.agreeToggleTarget, false)
      this.refresh()
    } else {
      this.termsDialogTarget.showModal()
    }
  }

  confirmTerms() {
    this.press(this.agreeToggleTarget, true)
    this.termsDialogTarget.close()
    this.refresh()
  }

  // ── Dialogs ──

  openSchema(event) {
    const { nameLead, nameRest, namePlus, entity, earliest } = event.currentTarget.dataset
    this.schemaLeadTarget.textContent = nameLead
    this.schemaRestTarget.textContent = nameRest || ""
    this.schemaPlusTarget.textContent = namePlus === "true" ? "+" : ""
    this.schemaEarliestTarget.textContent = earliest
      ? `Available from the ${earliest} season.`
      : "No data has landed for this category yet."
    this.schemaPlayerRowTargets.forEach((row) => { row.hidden = entity !== "player" })
    this.schemaDialogTarget.showModal()
  }

  openUnlock() {
    this.unlockDialogTarget.showModal()
  }

  // ── Build ──

  // Fills the build form's hidden inputs from the current selection just
  // before Turbo serializes it, then opens the progress dialog so its
  // placeholder is visible the instant the request goes out.
  prepareBuild(event) {
    const form = event.target
    form.querySelectorAll("[data-archive-param]").forEach((input) => input.remove())

    // Bare `[]` (no index) is required here, not `[N]` — Rack's nested-query
    // parser only groups repeated field names into one array-of-hashes when
    // it sees the same key (registry) recur, starting a new hash each time;
    // explicit numeric indices parse as a hash keyed by "0"/"1"/... instead,
    // which fails the array(hash) schema check the download endpoint expects.
    this.selectedCategories().forEach(({ registry, category }) => {
      this.appendParam(form, "archive_download[categories][][registry]", registry)
      this.appendParam(form, "archive_download[categories][][category]", category)
    })
    this.selectedSeasons().forEach((season) => this.appendParam(form, "archive_download[seasons][]", season))
    this.selectedSeasonTypes().forEach((type) => this.appendParam(form, "archive_download[season_types][]", type))
    this.appendParam(form, "archive_download[terms_accepted]", this.pressed(this.agreeToggleTarget))

    this.buildDialogTarget.showModal()
  }

  // Only the frame's content (not the <turbo-frame> tag's own attributes) is
  // replaced on each load, so state/url live on the inner .archive-status
  // div the server re-renders every time, not on the frame element itself.
  statusFrameLoaded() {
    clearTimeout(this.pollTimeout)
    const frame = this.statusFrameTarget
    const status = frame.querySelector(".archive-status")
    if (!status || status.dataset.state === "completed" || status.dataset.state === "failed") return

    this.pollTimeout = setTimeout(() => { frame.src = status.dataset.url }, 1500)
  }

  stopPolling() {
    clearTimeout(this.pollTimeout)
  }

  // ── Internals ──

  gate() {
    if (!this.gatedValue) return false
    this.openUnlock()
    return true
  }

  pressed(el) {
    return el.getAttribute("aria-pressed") === "true"
  }

  press(el, on) {
    el.setAttribute("aria-pressed", String(on))
  }

  flip(el) {
    this.press(el, !this.pressed(el))
  }

  toggleDisclosure(button, panel) {
    const open = button.getAttribute("aria-expanded") === "true"
    button.setAttribute("aria-expanded", String(!open))
    panel.hidden = open
  }

  syncAllChip(allChip, chips) {
    this.press(allChip, chips.length > 0 && chips.every((chip) => this.pressed(chip)))
  }

  selectAllWeeks() {
    this.availableWeekChips().forEach((chip) => this.press(chip, true))
    this.press(this.allWeeksTarget, true)
  }

  availableWeekChips() {
    return this.weekChipTargets.filter((chip) => chip.dataset.noData !== "true")
  }

  availableRoundChips() {
    return this.roundChipTargets.filter((chip) => chip.dataset.noData !== "true")
  }

  currentSeasonSelected() {
    return this.seasonChipTargets.some((chip) => chip.dataset.current === "true" && this.pressed(chip))
  }

  appendParam(form, name, value) {
    const input = document.createElement("input")
    input.type = "hidden"
    input.name = name
    input.value = value
    input.dataset.archiveParam = "true"
    form.append(input)
  }

  selectedCategories() {
    return this.categoryToggleTargets
      .filter((chip) => this.pressed(chip))
      .map((chip) => ({ registry: chip.dataset.registry, category: chip.dataset.category }))
  }

  // Downloads are whole-season files, so a season contributes once it has
  // any regular-season or postseason selection — the week/round chips
  // within it are informational, matching how refresh()'s fileCount already
  // counts one file per selected season regardless of which weeks show.
  selectedSeasons() {
    const seasons = new Set()
    this.seasonChipTargets.filter((chip) => this.pressed(chip)).forEach((chip) => seasons.add(chip.dataset.season))
    this.pastPlayoffsChipTargets
      .filter((chip) => this.pressed(chip))
      .forEach((chip) => seasons.add(chip.dataset.season))
    if (this.hasCurrentPlayoffsChipTarget && this.pressed(this.currentPlayoffsChipTarget)) {
      const current = this.seasonChipTargets.find((chip) => chip.dataset.current === "true")
      if (current) seasons.add(current.dataset.season)
    }
    return Array.from(seasons)
  }

  selectedSeasonTypes() {
    const types = new Set()
    if (this.seasonChipTargets.some((chip) => this.pressed(chip))) types.add("REG")

    const currentRoundSelected = this.currentSeasonSelected() && this.availableRoundChips().some((chip) => this.pressed(chip))
    const pastPlayoffSelected = this.pastPlayoffsChipTargets.some((chip) => this.pressed(chip))
    const currentPlayoffSelected = this.hasCurrentPlayoffsChipTarget && this.pressed(this.currentPlayoffsChipTarget)
    if (currentRoundSelected || pastPlayoffSelected || currentPlayoffSelected) types.add("POST")

    return Array.from(types)
  }

  refresh() {
    const currentOn = this.currentSeasonSelected()
    this.weeksBoxTarget.hidden = !currentOn
    this.postseasonBoxTarget.hidden = !currentOn
    if (this.hasSummaryTarget) this.summaryTarget.textContent = this.summaryText(currentOn)
    if (this.hasBuildButtonTarget) {
      const ready = this.pressed(this.agreeToggleTarget) && this.fileCount(currentOn) > 0
      this.buildButtonTarget.disabled = !ready
    }
  }

  summaryText(currentOn) {
    const categories = this.categoryToggleTargets.filter((chip) => this.pressed(chip)).length
    const seasons = this.seasonChipTargets.filter((chip) => this.pressed(chip))
    const parts = [this.categoriesPart(categories), this.seasonsPart(seasons)]

    const availableWeeks = this.availableWeekChips()
    const selectedWeeks = availableWeeks.filter((chip) => this.pressed(chip)).length
    if (currentOn && !this.pressed(this.allWeeksTarget)) {
      parts.push(`${selectedWeeks} of ${availableWeeks.length} weeks`)
    }

    const rounds = this.availableRoundChips().filter((chip) => this.pressed(chip)).length
    if (currentOn && rounds > 0) parts.push(`${rounds} playoff ${rounds === 1 ? "round" : "rounds"}`)

    const playoffSeasons = this.playoffSeasonCount()
    if (playoffSeasons > 0) parts.push(`${playoffSeasons} playoff ${playoffSeasons === 1 ? "season" : "seasons"}`)

    const files = this.fileCount(currentOn)
    parts.push(`${files} ${files === 1 ? "file" : "files"}`)
    return parts.join(" · ")
  }

  categoriesPart(count) {
    if (count === this.categoryCountValue) return "All categories"
    return `${count} ${count === 1 ? "category" : "categories"}`
  }

  seasonsPart(selected) {
    if (selected.length === this.seasonChipTargets.length) return "All seasons"
    if (selected.length === 1) {
      return selected[0].dataset.current === "true" ? "Current season" : `${selected[0].dataset.season} season`
    }
    return `${selected.length} seasons`
  }

  playoffSeasonCount() {
    const past = this.pastPlayoffsChipTargets.filter((chip) => this.pressed(chip)).length
    const current = this.hasCurrentPlayoffsChipTarget && this.pressed(this.currentPlayoffsChipTarget) ? 1 : 0
    return past + current
  }

  // One file per category per selected season, plus one postseason file per
  // category when any current-season round is selected, plus one per category
  // per selected playoff season.
  fileCount(currentOn) {
    const categories = this.categoryToggleTargets.filter((chip) => this.pressed(chip)).length
    const seasons = this.seasonChipTargets.filter((chip) => this.pressed(chip)).length
    const rounds = this.availableRoundChips().filter((chip) => this.pressed(chip)).length
    const postseason = (currentOn && rounds > 0 ? 1 : 0) + this.playoffSeasonCount()
    return categories * (seasons + postseason)
  }
}

import { Controller } from "@hotwired/stimulus"

// Submits the nearest form as soon as this element changes -- e.g. a filter
// <select> that should re-query immediately rather than waiting for a
// separate submit button. The button stays in the DOM as a no-JS fallback.
export default class extends Controller {
  submit() {
    this.element.form?.requestSubmit()
  }
}

// Avo runs its own Stimulus application (exposed as window.Stimulus), separate
// from the main site's -- controllers pinned under app/javascript/controllers
// aren't loaded on admin pages unless registered here explicitly.
import AnalyticsPollController from "controllers/analytics_poll_controller"

window.Stimulus.register("analytics-poll", AnalyticsPollController)

import { Controller } from "@hotwired/stimulus"
import { csrfParam } from "csrf_param"

// Sportsbook column picker for the live odds board. Unlike the odds-format
// and price-filter toggles (one exclusive value, so a single CSS attribute
// selector shows/hides everything), the set of sportsbook keys is dynamic
// and effectively unbounded (up to ~82 books) -- there is no static CSS rule
// that could select "whichever keys happen to be checked right now" without
// generating a rule per key ahead of time. So this controller does the one
// thing CSS genuinely cannot: toggle a hidden class on the unchecked book's
// <col> (Components::LiveOdds::BoardTable#render_colgroup).
//
// This targets the <col> rather than every header/price cell sharing the
// book's data-book-key on purpose: the "Sportsbooks" group header spans a
// fixed colspan (the total sportsbook count), so display:none-ing individual
// cells would drop them from the table's column grid and desync every column
// after them from its header. Collapsing the <col> instead
// (visibility: collapse) hides the whole column without changing the grid's
// column count.
//
// Persistence is server-side only: toggling is a subscriber feature
// (Customize+ renders the checkboxes disabled for everyone else), so
// every toggle PUTs the full selection to the server
// (LiveOddsController#update_preferences) and then Turbo-refreshes, and
// the server renders the saved selection on every load. The old
// localStorage mode for signed-out visitors is gone with their ability
// to toggle.
//
// This controller also owns recomputing "best price" every time the checked
// selection changes -- not just column visibility. Components::LiveOdds::
// BoardTable renders each price's `best` flag against every book in the
// data, but not all books are available in every jurisdiction: a price at a
// book the visitor has hidden (can't actually use) isn't the best price
// *for them*, and the server has no way to know their selection at render
// time, since the picker never round-trips to it. So every toggle re-derives
// "best" per price cell from scratch, among only the currently-checked
// venues -- every band's, since Customize+ made prediction markets the
// visitor's choice too. The comparison itself deliberately mirrors
// Odds::ImpliedProbability and BoardGame#display_for exactly (see
// implied_probability.js), so the number the client computes here is never a
// different calculation than the one the server rendered initially.
//
// The column collapse itself is only the instant feedback: once any
// <col> is visibility:collapse, the table's rendered width locks to the
// visible columns' natural widths and nothing on the <table> wins it
// back (the old fillWidth hack fought exactly that, and lost by a couple
// hundred pixels of dead space). So after the save lands, a Turbo
// refresh re-renders the table server-side without the column at all --
// a width:100% table with no collapsed cols fills the card naturally.
const HIDDEN_CLASS = "live-odds-table__venue--hidden"
const BEST_CLASS = "live-odds-price--best"
const DIM_CLASS = "lo-fresh__card--dim"

export default class extends Controller {
  static targets = ["checkbox", "count", "row", "showing", "groupCount"]
  static values = { saveUrl: String, checked: Array }

  connect() {
    this.seedFromServer()
    this.refresh()
    // A refresh morph rewrites the <col> classes and best-price flags from
    // the server's HTML (rendered for the saved selection, or the default
    // for a signed-out visitor) while the turbo-permanent Customize+ panel
    // keeps whatever the visitor actually toggled -- the same
    // client-state-vs-morph trap the odds-format toggle hit. Re-asserting
    // the checkbox state onto the fresh DOM after every morph keeps the
    // columns and the panel in agreement.
    this._onMorph = () => this.refresh()
    document.addEventListener("turbo:morph", this._onMorph)
  }

  disconnect() {
    document.removeEventListener("turbo:morph", this._onMorph)
  }

  // On a fresh load the server's rendered selection is the truth, and the
  // boxes must start from it -- not from whatever the browser restored.
  // Browsers restore form-control state on reload (hard reloads included),
  // keyed by position for unnamed inputs, and the Customize+ boxes reorder
  // between loads (checked venues first, unchecked after), so a restored
  // state lands on the wrong box. Left alone, refresh() then collapses the
  // <col> of a venue the server DID render, and one collapsed <col> locks
  // the table to its natural width (the width: 100% fill is gone) while
  // the band header's colspan still counts the unseen column. The wrapper
  // carries the server's selection as the checked value for exactly this
  // kind of reconciliation. Only on connect: after a morph the panel is
  // turbo-permanent and holds the visitor's live toggles, which a
  // broadcast landing mid-save must not revert (see refresh()).
  seedFromServer() {
    if (!this.hasCheckedValue || !this.checkboxTargets.length) return

    const checked = new Set(this.checkedValue)
    this.checkboxTargets.forEach((checkbox) => {
      checkbox.checked = checked.has(checkbox.value)
    })
  }

  refresh() {
    this.checkboxTargets.forEach((checkbox) => this.applyColumn(checkbox))
    this.updateCount()
    this.recomputeBestPrices()
  }

  toggle(event) {
    const checkbox = event.target
    this.applyColumn(checkbox)
    this.updateCount()
    this.recomputeBestPrices()
    // If the save is rejected the toggle bounces back. Leaving the box
    // unchecked would keep its <col> collapsed while the server still
    // renders the venue -- and every feed morph re-asserts the collapse
    // from the box, so that one ghost column would lock the table to its
    // natural width (dead space) and inflate its band header's colspan
    // past the columns anyone can see.
    this.save(() => {
      checkbox.checked = !checkbox.checked
      this.applyColumn(checkbox)
      this.updateCount()
      this.recomputeBestPrices()
    })
  }

  updateCount() {
    const checked = this.selectedKeys().length
    if (this.hasCountTarget) {
      this.countTarget.textContent = `${checked} of ${this.checkboxTargets.length}`
    }
    // The Customize+ panel's live figures: every venue is toggleable, so
    // "N showing" is simply the checked count, and each band's "n/m"
    // counts its own section's boxes.
    this.showingTargets.forEach((el) => {
      el.textContent = String(checked)
    })
    this.groupCountTargets.forEach((el) => {
      const boxes = el.closest(".lo-custom__section")?.querySelectorAll('[data-book-filter-target="checkbox"]')
      if (!boxes || !boxes.length) return
      const on = Array.from(boxes).filter((box) => box.checked).length
      el.textContent = `${on}/${boxes.length}`
    })
  }

  applyColumn(checkbox) {
    const col = this.element.querySelector(`col[data-book-key="${cssEscape(checkbox.value)}"]`)
    if (col) col.classList.toggle(HIDDEN_CLASS, !checkbox.checked)
    // The book's freshness card stays listed but dims while hidden --
    // the feed reports the whole board, unlit where the visitor opted out.
    const card = this.element.querySelector(`[data-fresh-key="${cssEscape(checkbox.value)}"]`)
    if (card) card.classList.toggle(DIM_CLASS, !checkbox.checked)
  }

  // Re-derives "best" for every wager row from only the venues currently
  // visible to this visitor -- the checked set, every band included.
  recomputeBestPrices() {
    const checked = new Set(this.selectedKeys())
    this.rowTargets.forEach((row) => this.recomputeRow(row, checked))
  }

  recomputeRow(row, checkedKeys) {
    const prices = Array.from(row.querySelectorAll('[data-book-filter-target="price"]')).map((el) => ({
      el,
      price: parsePrice(el.dataset.price),
      bookKey: el.dataset.bookKey,
      // Phlex renders a true boolean data value as a present-but-empty
      // attribute (data-prediction-market="") and omits it entirely for
      // false, rather than the strings "true"/"false" -- so presence in
      // the dataset, not its value, is the signal.
      predictionMarket: "predictionMarket" in el.dataset,
    }))

    // Every venue is the visitor's choice since Customize+ -- prediction
    // markets included, so no family is exempt from the checked set.
    const visible = prices.filter((p) => checkedKeys.has(p.bookKey))
    const priced = visible.filter((p) => p.price !== null)
    const best = priced.length ? priced.reduce((a, b) => (b.price > a.price ? b : a)) : null

    prices.forEach((p) => p.el.classList.toggle(BEST_CLASS, best !== null && p === best))
    this.updateBestChip(row, best)
  }

  // Keeps the row's Best Price chip in agreement with the in-cell highlight
  // this controller just derived: same winner, same rule, one source of
  // truth. The chip's price texts are copied from the winning cell's own
  // pre-rendered format spans, so the chip follows the odds-format toggle
  // for free.
  updateBestChip(row, best) {
    const chip = row.querySelector('[data-book-filter-target="best"]')
    if (!chip) return
    const blank = row.querySelector('[data-book-filter-target="bestBlank"]')

    if (best === null) {
      chip.hidden = true
      if (blank) blank.hidden = false
      return
    }

    chip.hidden = false
    if (blank) blank.hidden = true
    chip.dataset.venue = best.bookKey
    chip.title = best.el.dataset.venueTitle || ""
    for (const part of ["point", "american", "percent", "cents"]) {
      const target = chip.querySelector(`.live-odds-price__${part}`)
      const source = best.el.querySelector(`.live-odds-price__${part}`)
      if (target) target.textContent = source ? source.textContent : ""
    }
  }

  // The follow-up Turbo refresh is what reclaims the collapsed column's
  // width: the server re-renders the table without it (see the
  // controller-level comment).
  //
  // The CSRF token rides in the body, not the X-CSRF-Token header: the
  // CDN strips that header before Rails sees it (csrf_param.js). And the
  // refresh only runs for a save the server accepted -- fetch() resolves
  // on a 4xx/5xx too, so without the ok check a rejected PUT would
  // re-render the server's OLD selection (the venue back in the table,
  // its <col> re-collapsed from the box on every morph) and the visitor
  // would see their change silently not stick. A rejected save calls
  // onFailure instead, which the toggle uses to bounce the box back.
  save(onFailure) {
    if (!this.saveUrlValue) return

    fetch(this.saveUrlValue, {
      method: "PUT",
      headers: { "Content-Type": "application/json", "Accept": "application/json" },
      body: JSON.stringify({ sportsbook_keys: this.selectedKeys(), ...csrfParam() }),
    })
      .then((response) => {
        if (!response.ok) throw new Error(`save failed (${response.status})`)
        window.Turbo?.visit(window.location.href, { action: "replace" })
      })
      .catch((error) => {
        console.warn("book-filter: preference save failed", error)
        onFailure?.()
      })
  }

  // With no picker on the page (the design parked it until Customize+ is
  // built), the server-resolved selection rides in as a value instead --
  // the same keys the server hid the <col>s by, so the best-price
  // derivation stays consistent with what's actually visible.
  selectedKeys() {
    if (!this.checkboxTargets.length) return this.checkedValue

    return this.checkboxTargets.filter((c) => c.checked).map((c) => c.value)
  }

}

function cssEscape(value) {
  return window.CSS && CSS.escape ? CSS.escape(value) : value.replace(/[^a-zA-Z0-9_-]/g, "\\$&")
}

function parsePrice(raw) {
  if (raw === undefined || raw === "") return null
  const value = Number(raw)
  return Number.isFinite(value) ? value : null
}

import { Controller } from "@hotwired/stimulus"
import { csrfParam } from "csrf_param"

// Drag-to-reorder for the Customize+ venue rows. One instance per band
// (its element is that band's row container), so a drag can never cross
// into another family.
//
// Pointer events off the grip handle, not HTML5 drag-and-drop: iOS
// Safari only starts a native drag from a long-press (a normal touch
// drag just scrolls), which read as "dragging doesn't work on mobile".
// The grip carries touch-action: none (live_odds.scss) so the browser
// hands the gesture to us instead of scrolling, and grabbing by the
// grip alone leaves the rest of the row to its label job of toggling
// the checkbox.
//
// Rows move live as the pointer passes over them; on release every
