  // already-hover-opened panel, clicking the trigger with a mouse would
  // immediately re-close what hover just opened. Closing happens via
  // mouseleave (closeOverflowPanel below) or an outside click/tap.
  openOverflowPanel(event) {
    event?.stopPropagation();
    clearTimeout(this._closeOverflowTimeout);
    if (!this.hasOverflowPanelTarget || !this.hasOverflowTriggerTarget || !this.overflowPanelTarget.hidden) return;

    const overflowPills = this.pillTargets.filter(p => p.classList.contains("active-stats-pill--overflow"));
    overflowPills.forEach(pill => this.overflowPanelTarget.appendChild(pill));
    this.overflowPanelTarget.hidden = false;
    this.overflowTriggerTarget.setAttribute("aria-expanded", "true");
  }

  // Delayed, not immediate -- the panel (up to 20rem, see
  // coverage_intelligence.scss) is wider than the "+N more" trigger that
  // opens it, so a real mouse path from the trigger to a pill deeper in the
  // panel routinely drifts outside both elements for an instant. Closing on
  // that first mouseleave made the panel unreachable; this grace period
  // gives openOverflowPanel's own mouseenter (fired the moment the pointer
  // lands back on the trigger or the panel) a chance to cancel it first.
  closeOverflowPanel() {
    clearTimeout(this._closeOverflowTimeout);
    this._closeOverflowTimeout = setTimeout(() => this._closeOverflowPanel(), 300);
  }

  // Category headers inside the "+ Add Stat" panel (StatBuilder+ only —
  // CoverageIQ's flat option list never renders these). Collapsed by
  // default in the server-rendered HTML; this just flips one group open.
  // Bound to the whole .stat-picker__category-header row (matching the
  // mock's own row-level click handler, since Select All/Reset/the caret
  // all sit inside it) -- .closest() resolves to that same element whether
  // event.currentTarget already is the header or a descendant of it.
  //
  // stopPropagation matters specifically for StatPickerPanel's tree: locked
  // (non-subscriber) users can still browse it, via a pointer-events
  // override that re-enables just .stat-picker__category-header inside an
  // otherwise-inert .ci-locked panel (see coverage_intelligence.scss).
  // Without stopping propagation here, that click would still bubble up to
  // the frame's own locked-filters#redirect listener and pop the paywall
  // even though this row itself is meant to work unlocked.
  toggleCategory(event) {
    event.stopPropagation();
    if (event.key === " ") event.preventDefault(); // avoid scrolling the page
    const header = event.currentTarget.closest(".stat-picker__category-header");
    const options = header.nextElementSibling;
    const expanded = header.getAttribute("aria-expanded") === "true";
    header.setAttribute("aria-expanded", (!expanded).toString());
    if (options) options.classList.toggle("hidden", expanded);
  }

  // Search box inside StatPickerPanel (StatBuilder+/MatchupIQ+ only).
  // Hides non-matching rows, then hides any category/tier left with no
  // visible rows -- and forces every category open while a query is
  // active, so matches aren't hidden behind a collapsed accordion the user
  // never asked to open.
  filterStats(event) {
    const query = event.target.value.trim().toLowerCase();
    const panel = event.target.closest(".stat-picker");
    if (!panel) return;

    panel.querySelectorAll(".stat-picker__row").forEach(row => {
      const matches = !query || row.dataset.coverageActiveStatsLabelParam.toLowerCase().includes(query);
      row.classList.toggle("hidden", !matches);
    });

    panel.querySelectorAll(".stat-picker__category").forEach(category => {
      const anyVisible = !!category.querySelector(".stat-picker__row:not(.hidden)");
      category.classList.toggle("hidden", !anyVisible);

      const header = category.querySelector(":scope > .stat-picker__category-header");
      const body = header?.nextElementSibling;
      if (!header || !body) return;

      if (query) {
        header.setAttribute("aria-expanded", "true");
        body.classList.remove("hidden");
      }
    });

    panel.querySelectorAll(".stat-picker__flat").forEach(flat => {
      const anyVisible = !!flat.querySelector(".stat-picker__row:not(.hidden)");
      flat.classList.toggle("hidden", !anyVisible);
    });
  }

  dragStart(event) {
    this._dragKey = event.params.key;
    event.dataTransfer.effectAllowed = "move";
    event.currentTarget.classList.add("dragging");
  }

  dragOver(event) {
    event.preventDefault();
    event.dataTransfer.dropEffect = "move";
    event.currentTarget.classList.add("drag-over");
  }

  drop(event) {
    event.preventDefault();
    event.currentTarget.classList.remove("drag-over");
    this._reorder(this._dragKey, event.params.key);
  }

  dragEnd(event) {
    this._dragKey = null;
    event.currentTarget.classList.remove("dragging");
    this.pillTargets.forEach(p => p.classList.remove("drag-over"));
  }

  // Touch has no native drag-and-drop: touchmove/touchend keep firing on
  // the pill touchstart began on (unlike dragover/drop, which the browser
  // retargets to whatever's under the pointer), so the hit-testing dragover
  // gets for free has to be done by hand here via elementFromPoint.
  touchStart(event) {
    this._dragKey = event.params.key;
    event.currentTarget.classList.add("dragging");
  }

  touchMove(event) {
    if (!this._dragKey) return;

    const touch  = event.touches[0];
    const target = this._pillAt(touch.clientX, touch.clientY);
    if (target === event.currentTarget) return;

    if (this._touchOverEl && this._touchOverEl !== target) this._touchOverEl.classList.remove("drag-over");
    this._touchOverEl = target;
    if (target) target.classList.add("drag-over");
  }

  touchEnd(event) {
    if (this._touchOverEl) this._reorder(this._dragKey, this._touchOverEl.dataset.coverageActiveStatsKeyParam);

    this._dragKey = null;
    this._touchOverEl = null;
    event.currentTarget.classList.remove("dragging");
    this.pillTargets.forEach(p => p.classList.remove("drag-over"));
  }

  // -- private --

  // Select All/Reset sit *inside* .stat-picker__category-header, which has
  // its own click->toggleCategory listener -- unlike an individual row's
  // click (nothing sits between a row and the frame's own paywall redirect,
  // so it reaches that just by bubbling), letting these bubble here would
  // also toggle the category open/closed as an unwanted side effect. So a
  // locked click opens the paywall directly instead of relying on bubbling,
  // and stops propagation so toggleCategory never fires.
  _redirectIfLocked(event) {
    if (!event.currentTarget.closest(".ci-locked")) return false;

    event.preventDefault();
    event.stopPropagation();
    document.getElementById("paywall-modal")?.showModal();
    return true;
  }

  // Shared by drop() and touchEnd() — moves fromKey to sit where toKey is.
  _reorder(fromKey, toKey) {
    if (!fromKey || fromKey === toKey) return;

    const keys = [...this.keysValue];
    const from = keys.indexOf(fromKey);
    const to   = keys.indexOf(toKey);
    if (from === -1 || to === -1) return;

    keys.splice(from, 1);
    keys.splice(to, 0, fromKey);
    this._navigate(keys);
  }

  // The pill (if any) under a touch point — touchmove/touchend only ever
  // report their original touchstart target, so hit-testing has to go
  // through the DOM directly instead.
  _pillAt(x, y) {
    const el = document.elementFromPoint(x, y);
    return el ? el.closest(".active-stats-pill") : null;
  }

  _navigate(keys) {
    const url = new URL(window.location.href);
    url.searchParams.set("stats", this._encodeStats(keys));
    url.searchParams.delete("page");
    history.replaceState(history.state, "", url.toString());
    this.keysValue = keys;
    this._syncResetVisibility();
    this._syncCounts();
    this._syncRows();

    const statsFrame = document.getElementById(this.turboFrameValue);
    if (statsFrame) statsFrame.src = url.toString();

    const pillsFrame = document.getElementById("active-stats");
    if (pillsFrame) pillsFrame.src = url.toString();
  }

  // Numeric-encodes keys for the ?stats= param when numericIds is set
  // (StatBuilder+ — keeps the URL short across a 300+ stat catalog); falls
  // back to writing keys verbatim otherwise (CoverageIQ, unchanged).
  _encodeStats(keys) {
    if (!Object.keys(this.numericIdsValue).length) return keys.join(",");
    return keys.map(k => this.numericIdsValue[k] ?? k).join(",");
  }

  // The reset-to-defaults control (StatBuilder+ only) lives in the header,
  // outside the active-stats turbo frame that add/remove/reorder refresh —
  // so it needs its own explicit sync rather than picking up the change for
  // free from a frame reload.
  _syncResetVisibility() {
    if (!this.hasResetWrapperTarget) return;
    const current = this.keysValue.toSorted();
    const defaults = this.defaultKeysValue.toSorted();
    const isDefault = current.length === defaults.length && current.every((k, i) => k === defaults[i]);
    this.resetWrapperTarget.classList.toggle("hidden", isDefault);
  }

  // Recomputes every "N of M[ selected]" count badge (main status, picker
  // header, per-category) from this.keysValue -- each `count` target carries
  // its own scope of ids as JSON (count-ids) plus an optional trailing
  // suffix (count-suffix, e.g. " selected"). These all live outside the
  // frames add/remove/reorder reload (see _navigate), so nothing else keeps
  // them in sync.
  _syncCounts() {
    this.countTargets.forEach(el => {
      const ids = JSON.parse(el.dataset.countIds);
      const selected = ids.filter(id => this.keysValue.includes(id)).length;
      el.textContent = `${selected} of ${ids.length}${el.dataset.countSuffix ?? ""}`;
    });
  }

  // Keeps the StatPicker's own checkbox rows (checked state + check/lock
  // icon) in sync with this.keysValue -- same reasoning as _syncCounts, the
  // picker panel never reloads via a frame.
  _syncRows() {
    this.rowTargets.forEach(row => {
      const active = this.keysValue.includes(row.dataset.coverageActiveStatsKeyParam);
      row.classList.toggle("stat-picker__row--active", active);
      row.setAttribute("aria-checked", active.toString());
      row.querySelector(".stat-picker__row-check")?.classList.toggle("hidden", !active);
      row.querySelector(".stat-picker__row-lock")?.classList.toggle("hidden", active);
    });
  }

  _insertPillOptimistically(key, label) {
    const pill = document.createElement("span");
    pill.className = "active-stats-pill";
    pill.draggable = true;
    pill.dataset.coverageActiveStatsTarget = "pill";
    pill.dataset.coverageActiveStatsKeyParam = key;
    pill.innerHTML =
      `<span class="active-stats-pill__label">${label}</span>` +
      `<button type="button" class="active-stats-pill__remove"` +
        ` data-action="coverage-active-stats#removeStat"` +
        ` data-coverage-active-stats-key-param="${key}"` +
        ` aria-label="Remove ${label}">×</button>`;

    const frame = document.getElementById("active-stats");
    // Anchor before the overflow wrapper (not the add-wrap) so a newly-added
    // pill lands grouped with the other pills, ahead of "+N more" / "+ Add Stat".
    const anchor = this.hasOverflowWrapTarget ? this.overflowWrapTarget
      : this.hasAddWrapTarget ? this.addWrapTarget : null;
    if (frame) {
      frame.insertBefore(pill, anchor);
    }
  }

  _handleOutsideClick(event) {
    if (this.hasAddPanelTarget && this.hasAddWrapTarget && !this.addWrapTarget.contains(event.target)) {
      this.addPanelTarget.classList.add("hidden");
      this._setAddPanelExpanded(false);
    }
    // composedPath(), not overflowWrapTarget.contains(event.target): a click
    // on a pill's remove button inside the panel (removeStat, above) deletes
    // that button from the DOM before this document-level listener runs, so
    // .contains() would see a detached node and wrongly call it an outside
    // click, closing the panel we just told removeStat to keep open.
    // composedPath() reflects the tree as it was when the click dispatched,
    // before any handler mutated it.
    if (
      this.hasOverflowPanelTarget && !this.overflowPanelTarget.hidden &&
      !event.composedPath().includes(this.overflowWrapTarget)
    ) {
      this._closeOverflowPanel();
    }
  }

  // Recomputes which pills fit within maxRowsValue full rows by comparing
  // offsetTop -- lets the browser's own flex-wrap do the layout math (font
  // metrics, gaps, rounding) instead of summing widths by hand. Always
  // starts from a clean, closed state so this is safe to call repeatedly
  // (on connect, resize, frame reload, and every add/remove).
  //
  // Counts actual rows in use rather than precomputing a fixed cutoff, so
  // it accounts for the "+N more" trigger *and* the "+ Add Stat" button
  // (rendered right after the pills in the same wrapping row, but not a
  // pillTarget itself) each potentially claiming a row of their own --
  // pills alone can fit within maxRowsValue while the button still spills
  // onto row (maxRowsValue + 1), which is exactly the case this guards.
  _collapseOverflow() {
    clearTimeout(this._closeOverflowTimeout);
    this._closeOverflowPanel();
    if (this.hasPillsRowTarget && this.hasClampedClass) {
      this.pillsRowTarget.classList.remove(this.clampedClass);
    }
    if (!this.hasOverflowWrapTarget || !this.hasOverflowTriggerTarget) return;

    this.pillTargets.forEach(pill => pill.classList.remove("active-stats-pill--overflow"));
    this.overflowWrapTarget.hidden = true;
    if (!this.pillTargets.length) return;

    const overflow = [];
    const syncTrigger = () => {
      this.overflowWrapTarget.hidden = overflow.length === 0;
      if (overflow.length) this.overflowTriggerTarget.textContent = `+${overflow.length} more`;
    };

    while (this._rowsInUse() > this.maxRowsValue) {
      const nextToHide = this.pillTargets.toReversed()
        .find(pill => !pill.classList.contains("active-stats-pill--overflow"));
      if (!nextToHide) break;

      nextToHide.classList.add("active-stats-pill--overflow");
      overflow.push(nextToHide);
      syncTrigger();
    }
  }

  // Distinct offsetTop values among everything currently visible in the
  // pill row == the number of rows actually in use right now.
  _rowsInUse() {
    const tops = new Set(
      this.pillTargets
        .filter(pill => !pill.classList.contains("active-stats-pill--overflow"))
        .map(pill => pill.offsetTop),
    );
    if (!this.overflowWrapTarget.hidden) tops.add(this.overflowWrapTarget.offsetTop);
    if (this.hasAddWrapTarget) tops.add(this.addWrapTarget.offsetTop);
    return tops.size;
  }

  _closeOverflowPanel() {
    if (!this.hasOverflowPanelTarget || !this.hasOverflowWrapTarget) return;

    const parent = this.overflowWrapTarget.parentElement;
    [...this.overflowPanelTarget.children].forEach(pill => parent.insertBefore(pill, this.overflowWrapTarget));
    this.overflowPanelTarget.hidden = true;
    if (this.hasOverflowTriggerTarget) this.overflowTriggerTarget.setAttribute("aria-expanded", "false");
  }

  _debounce(fn, waitMs) {
    let timeout;
    return (...args) => {
      clearTimeout(timeout);
      timeout = setTimeout(() => fn(...args), waitMs);
    };
  }
}

import { Controller } from "@hotwired/stimulus";

// Offense Next Opp coverage popover for the Coverage Intelligence Tool.
// On hover/focus of the Next Opp cell, lazily fetches the opponent's coverage
// distribution card HTML once and injects it into the popover element. The
// fetched markup is cached so repeated hovers don't re-request.

let openController = null;

export default class extends Controller {
  static targets = ["popover"];
  static values = { url: String };

  connect() {
    this._fetched = false;
    this._hideTimer = null;
  }

  disconnect() {
    clearTimeout(this._hideTimer);
    if (openController === this) openController = null;
  }

  show() {
    clearTimeout(this._hideTimer);

    // Only one popover open at a time.
    if (openController && openController !== this) openController._hideNow();
    openController = this;

    this.popoverTarget.classList.remove("hidden");
    this._reposition();
    this._load();
  }

  _reposition() {
    const trigger = this.element.getBoundingClientRect();
    const popover = this.popoverTarget;
    const GAP = 8;
    const WIDTH = popover.offsetWidth || 304; // 19rem fallback
    const HEIGHT = popover.offsetHeight || 500;

    const spaceAbove = trigger.top - GAP;
    const spaceBelow = window.innerHeight - trigger.bottom - GAP;
    const spaceRight = window.innerWidth - trigger.right - GAP;

    // Reset all sides before repositioning.
    popover.style.top = popover.style.bottom = popover.style.left = popover.style.right = "";

    if (spaceBelow >= HEIGHT) {
      // Preferred: open below, centered on trigger.
      popover.style.top = `${trigger.bottom + GAP}px`;
      const left = Math.max(8, Math.min(trigger.left + trigger.width / 2 - WIDTH / 2, window.innerWidth - WIDTH - 8));
      popover.style.left = `${left}px`;
    } else if (spaceAbove >= HEIGHT) {
      // Open above, centered on trigger.
      popover.style.bottom = `${window.innerHeight - trigger.top + GAP}px`;
      const left = Math.max(8, Math.min(trigger.left + trigger.width / 2 - WIDTH / 2, window.innerWidth - WIDTH - 8));
      popover.style.left = `${left}px`;
    } else if (spaceRight >= WIDTH) {
      // Neither fits vertically — open to the right, clamped vertically.
      popover.style.left = `${trigger.right + GAP}px`;
      const top = Math.max(8, Math.min(trigger.top + trigger.height / 2 - HEIGHT / 2, window.innerHeight - HEIGHT - 8));
      popover.style.top = `${top}px`;
    } else {
      // Last resort: open to the left, clamped vertically.
      popover.style.left = `${Math.max(8, trigger.left - WIDTH - GAP)}px`;
      const top = Math.max(8, Math.min(trigger.top + trigger.height / 2 - HEIGHT / 2, window.innerHeight - HEIGHT - 8));
      popover.style.top = `${top}px`;
    }
  }

  hide() {
    clearTimeout(this._hideTimer);
    this._hideTimer = setTimeout(() => this._hideNow(), 120);
  }

  _hideNow() {
    this.popoverTarget.classList.add("hidden");
    if (openController === this) openController = null;
  }

  async _load() {
    if (this._fetched || !this.urlValue) return;
    this._fetched = true;

    try {
      const resp = await fetch(this.urlValue, {
        headers: { Accept: "text/html" },
      });
      // The Turbo frame may have replaced this row mid-flight, detaching the
      // controller. Bail before touching a target that no longer exists.
      if (!this.hasPopoverTarget) return;
      if (resp.status === 204) {
        this.popoverTarget.innerHTML =
          '<div class="ci-opp-card ci-opp-card--empty">No coverage data available.</div>';
        this._reposition();
        return;
      }
      if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
      const html = await resp.text();
      if (!this.hasPopoverTarget) return;
      this.popoverTarget.innerHTML = html;
      this._reposition();
    } catch {
      this._fetched = false;
      if (!this.hasPopoverTarget) return;
      this.popoverTarget.innerHTML =
        '<div class="ci-opp-card ci-opp-card--empty">Unable to load coverage data.</div>';
      this._reposition();
    }
  }
}

import { Controller } from "@hotwired/stimulus";

// Multi-year season selector for the Coverage Intelligence Tool.
// Renders a dropdown panel of individual season checkboxes. The panel stays
// open while the user toggles multiple seasons; the URL "seasons" param is only
// updated and the turbo frame reloaded once the panel closes (so the reload
// doesn't dismiss the panel mid-selection).

export default class extends Controller {
  static targets = ["trigger", "panel", "label", "option"];
  static values = {
    active:     { type: Array, default: [] },
    turboFrame: { type: String, default: "stats-content" },
  };

  connect() {
    this._dirty = false;
    this._syncUI();
    this._handleOutsideClick = this._handleOutsideClick.bind(this);
    document.addEventListener("click", this._handleOutsideClick);
  }

  disconnect() {
    document.removeEventListener("click", this._handleOutsideClick);
  }

  toggle(event) {
    event.stopPropagation();
    const willOpen = this.panelTarget.classList.contains("hidden");
    this.panelTarget.classList.toggle("hidden");
    if (!willOpen) this._commit();
  }

  // Toggle individual season on/off. Keeps the panel open and defers the
  // turbo-frame visit until the panel closes.
  toggleSeason(event) {
    const year = parseInt(event.currentTarget.dataset.value, 10);
    const active = new Set(this.activeValue.map(Number));

    if (active.has(year)) {
      active.delete(year);
    } else {
      active.add(year);
    }

    this.activeValue = [...active].toSorted((a, b) => b - a);
    this._dirty = true;
    this._syncUI();
  }

  _syncUI() {
    const active = new Set(this.activeValue.map(Number));

    this.optionTargets.forEach(opt => {
      const year = parseInt(opt.dataset.value, 10);
      opt.classList.toggle("active", active.has(year));
    });

    if (this.hasLabelTarget) {
      this.labelTarget.textContent = this._formatLabel();
    }
  }

  _formatLabel() {
    const active = this.activeValue.map(Number).toSorted((a, b) => a - b);
    if (active.length === 0) return "Select Season";
    if (active.length === 1) return active[0].toString();
    const isConsecutive = active.every((year, i) => i === 0 || year === active[i - 1] + 1);
    return isConsecutive ? `${active[0]}-${active[active.length - 1]}` : active.join(", ");
  }

  // Apply the accumulated selection: update the URL "seasons" param and reload
  // the turbo frame. No-op unless the selection changed since the panel opened.
  _commit() {
    if (!this._dirty) return;
    this._dirty = false;

    const url = new URL(window.location.href);
    const active = this.activeValue;

    if (active.length <= 1) {
      // Single season or empty — use simple season param
      url.searchParams.delete("seasons");
      if (active.length === 1) {
        url.searchParams.set("seasons", active[0].toString());
      }
    } else {
      url.searchParams.set("seasons", active.join(","));
    }
    url.searchParams.delete("page");
    history.replaceState(history.state, "", url.toString());

    const frame = document.getElementById(this.turboFrameValue);
    if (frame) {
      frame.src = url.toString();
    }

    this._syncFilterReset();
  }

  // The FILTERS card's reset button lives on the ancestor v2-filter
  // controller, outside this element — its default check needs to react to
  // season changes too, so nudge it after every commit.
  _syncFilterReset() {
    const filterEl = this.element.closest('[data-controller~="v2-filter"]');
    if (!filterEl) return;

    const ctrl = this.application.getControllerForElementAndIdentifier(filterEl, "v2-filter");
    ctrl?.syncResetVisibility();
  }

  _handleOutsideClick(event) {
    if (!this.element.contains(event.target)) {
      if (!this.panelTarget.classList.contains("hidden")) {
        this.panelTarget.classList.add("hidden");
        this._commit();
      }
    }
  }
}

import { Controller } from "@hotwired/stimulus";

// Coverage shell multi-select controller for the Coverage Intelligence Tool.
// Manages individual coverage buttons and group toggle buttons.
// Group is active when any of its members are selected.
//
// Group button mapping:
//   Man  → ['0','1','2M']
//   Zone → ['2','3','4','6','9']

const DEBOUNCE_MS = 300;

const GROUPS = {
  man:  ["0", "1", "2M"],
  zone: ["2", "3", "4", "6", "9"],
};

const ALL_COVERAGES = ["0", "1", "2", "2M", "3", "4", "6", "9"];

export default class extends Controller {
  static targets = ["coverageBtn", "groupBtn", "groupCard", "label"];
  static values = {
    active:     { type: Array, default: [] },
    turboFrame: { type: String, default: "stats-content" },
  };

  connect() {
    this._visitTimer = null;
    this._syncUI();
  }

  disconnect() {
    clearTimeout(this._visitTimer);
  }

  // Toggle a single coverage type on/off.
  toggleCoverage(event) {
    const value = event.currentTarget.dataset.value;
    const active = new Set(this.activeValue);
    if (active.has(value)) {
      active.delete(value);
    } else {
      active.add(value);
    }
    this.activeValue = ALL_COVERAGES.filter(c => active.has(c));
    this._syncUI();
    this._scheduleVisit();
  }

  // Toggle a coverage group — if all members are active, deactivate them;
  // otherwise activate all members.
  toggleGroup(event) {
    const group = event.currentTarget.dataset.group;
    const members = GROUPS[group] || [];
    const active = new Set(this.activeValue);
    const allActive = members.every(m => active.has(m));

    members.forEach(m => {
      if (allActive) {
        active.delete(m);
      } else {
        active.add(m);
      }
    });

    this.activeValue = ALL_COVERAGES.filter(c => active.has(c));
    this._syncUI();
    this._scheduleVisit();
  }

  selectAll() {
    this.activeValue = [...ALL_COVERAGES];
    this._syncUI();
    this._scheduleVisit();
  }

  clearAll() {
    this.activeValue = [];
    this._syncUI();
    this._scheduleVisit();
  }

  clearGroup(event) {
    const group = event.currentTarget.dataset.group;
    const members = GROUPS[group] || [];
    const active = new Set(this.activeValue);
    members.forEach(m => active.delete(m));
    this.activeValue = ALL_COVERAGES.filter(c => active.has(c));
    this._syncUI();
    this._scheduleVisit();
  }

  // Sync button active states and status badge to match the current selection.
  _syncUI() {
    const active = new Set(this.activeValue);

    this.coverageBtnTargets.forEach(btn => {
      btn.classList.toggle("active", active.has(btn.dataset.value));
    });

    this.groupBtnTargets.forEach(btn => {
      const members = GROUPS[btn.dataset.group] || [];
      const allActive = members.every(m => active.has(m));
      btn.classList.toggle("active", allActive);
    });

    this.groupCardTargets.forEach(card => {
      const members = GROUPS[card.dataset.group] || [];
      card.classList.toggle("group-active", members.some(m => active.has(m)));
    });

    if (this.hasLabelTarget) {
      this.labelTarget.textContent = this._formatLabel();
    }
  }

  _formatLabel() {
    const n = this.activeValue.length;
    if (n === ALL_COVERAGES.length) return "All coverages selected";
    return `${n} of ${ALL_COVERAGES.length} selected`;
  }

  // Debounced turbo frame visit with updated URL params.
  _scheduleVisit() {
    clearTimeout(this._visitTimer);
    this._visitTimer = setTimeout(() => {
      const url = new URL(window.location.href);
      const active = this.activeValue;

      if (active.length === ALL_COVERAGES.length) {
        url.searchParams.delete("coverages");
      } else if (active.length === 0) {
        url.searchParams.set("coverages", "");
      } else {
        url.searchParams.set("coverages", active.join(","));
      }
      url.searchParams.delete("page");
      history.replaceState(history.state, "", url.toString());

      const frame = document.getElementById(this.turboFrameValue);
      if (frame) {
        frame.src = url.toString();
      }
    }, DEBOUNCE_MS);
  }
}

import { Controller } from "@hotwired/stimulus";

// Rewrites the browser address bar to a clean slug URL whenever the active
// coverage × stat combination maps to a known landing page combo.
//
// Patches history.replaceState (used by coverage-shells, coverage-active-stats,
// and v2-filter controllers) to intercept URL updates without modifying those
// controllers. Restores the original on disconnect.
//
// On connect, also seeds the current URL with default stats/coverages params so
// that subsequent Turbo-frame requests (which build from window.location.href)
// carry those params and the landing action's param-precedence logic works.

// Shell order mirrors NFL::CoverageIntelligenceQuery::ALL_COVERAGES
const ALL_SHELL_ORDER = ["0", "1", "2", "2M", "3", "4", "6", "9"];
const STAT_COV_PATH_RE = /^\/nfl\/coverage\/([^/]+)\/vs\/[^/]+$/;
const COV_ONLY_PATH_RE = /^\/nfl\/coverage\/vs\/[^/]+$/;
const OFFENSE_POSITIONS = new Set(["WR_TE", "WR", "TE", "RB", "QB", ""]);
// Params to carry over to the slug URL so filters aren't lost on navigation
const PRESERVE_PARAMS = ["seasons", "weeks", "team", "player_name", "qualifier", "sort_order", "stats"];

export default class extends Controller {
  static values = {
    offenseStatSlugByKey: { type: Object, default: {} },
    defenseStatSlugByKey: { type: Object, default: {} },
    coverageSlugByKey:    { type: Object, default: {} },
    defaultStats:         { type: String, default: "" },
    defaultCoverages:     { type: String, default: "" },
  };

  connect() {
    const original = history.replaceState.bind(history);
    this._original = original;
    history.replaceState = (state, title, url) => {
      const slugUrl = this._toSlugUrl(url);
      // A new stat/coverage combo is a different landing page — navigate so its
      // server-rendered H1, info card, and canonical actually render. Pure filter
      // changes (same path, different params) keep the in-place URL rewrite.
      if (slugUrl && new URL(slugUrl).pathname !== window.location.pathname) {
        Turbo.visit(slugUrl);
        return;
      }
      original(state, title, slugUrl ?? url);
    };

    // Seed URL with default filter params so subsequent filter-change requests
    // (which copy window.location.href) preserve the landing page preset.
    this._seedLandingParams();
  }

  disconnect() {
    if (this._original) {
      history.replaceState = this._original;
      this._original = null;
    }
  }

  // -- private --

  _seedLandingParams() {
    const path = window.location.pathname;
    if (!STAT_COV_PATH_RE.test(path) && !COV_ONLY_PATH_RE.test(path)) return;
    const url = new URL(window.location.href);
    let changed = false;

    if (this.defaultStatsValue && !url.searchParams.has("stats")) {
      url.searchParams.set("stats", this.defaultStatsValue);
      changed = true;
    }
    if (this.defaultCoveragesValue && !url.searchParams.has("coverages")) {
      url.searchParams.set("coverages", this.defaultCoveragesValue);
      changed = true;
    }

    // Use the original replaceState so we don't trigger the slug-rewrite
    // logic (which would strip the params we just added).
    if (changed) this._original(history.state, "", url.toString());
  }

  _toSlugUrl(url) {
    try {
      const u = new URL(url, window.location.origin);
      const statSlug = this._extractStatSlug(u);
      if (!statSlug) return null;

      const coveragesParam = u.searchParams.get("coverages");
      const coverageKey = this._coverageKey(coveragesParam);
      if (coverageKey === null) return null;

      const coverageSlug = this.coverageSlugByKeyValue[coverageKey];
      if (!coverageSlug) return null;

      // Skip rewrite when position doesn't match the stat's view type.
      const position = u.searchParams.get("position") ?? "";
      const statIsOffense = !statSlug.match(/-allowed$|-defended$|-coverage-snap$/);
      const posIsOffense = OFFENSE_POSITIONS.has(position);
      if (statIsOffense !== posIsOffense) return null;

      const slug = new URL(`/nfl/coverage/${statSlug}/vs/${coverageSlug}`, window.location.origin);
      for (const p of PRESERVE_PARAMS) {
        const v = u.searchParams.get(p);
        if (v) slug.searchParams.set(p, v);
      }
      return slug.toString();
    } catch {
      return null;
    }
  }

  _extractStatSlug(u) {
    const position = u.searchParams.get("position") ?? "";
    const useDefense = !OFFENSE_POSITIONS.has(position);
    const map = useDefense ? this.defenseStatSlugByKeyValue : this.offenseStatSlugByKeyValue;

    // sort_field takes precedence — reflects the user's current sort.
    const sortField = u.searchParams.get("sort_field");
    if (sortField) {
      const slug = map[sortField];
      if (slug) return slug;
    }

    // Single active stat → update the path slug to match it.
    const statsParam = u.searchParams.get("stats");
    if (statsParam && !statsParam.includes(",")) {
      const slug = map[statsParam];
      if (slug) return slug;
    }

    // Fall back to the stat+coverage landing page path slug.
    const pathMatch = u.pathname.match(STAT_COV_PATH_RE);
    if (pathMatch) return pathMatch[1];

    return null;
  }

  // Returns the canonical comma-joined shell key for a coverages param value,
  // matching the order of ALL_SHELL_ORDER so it aligns with coverageSlugByKey.
  _coverageKey(param) {
    if (param === null) {
      // Absent param = all coverages (shells controller omits it when all selected)
      return ALL_SHELL_ORDER.join(",");
    }
    if (param === "") return null; // empty = nothing selected, no slug
    const shells = param.split(",");
    const ordered = ALL_SHELL_ORDER.filter(c => shells.includes(c));
    if (ordered.length !== shells.length) return null;
    return ordered.join(",");
  }
}

import { Controller } from "@hotwired/stimulus";

// Custom weeks multi-select controller for the Coverage Intelligence Tool.
// Renders an always-visible row of week 1-18 buttons. Selection changes update
// the URL query param "weeks" and trigger a debounced turbo frame visit.

const DEBOUNCE_MS = 300;

export default class extends Controller {
  static targets = ["label", "weekBtn"];
  static values = {
    active:     { type: Array, default: [] },
    turboFrame: { type: String, default: "stats-content" },
  };

  connect() {
    this._visitTimer = null;
    this._syncUI();
  }

  disconnect() {
    clearTimeout(this._visitTimer);
  }

  // Toggle individual week on/off.
  toggleWeek(event) {
    const week = parseInt(event.currentTarget.dataset.week, 10);
    const active = new Set(this.activeValue.map(Number));

    if (active.has(week)) {
      active.delete(week);
    } else {
      active.add(week);
    }

    this.activeValue = [...active].toSorted((a, b) => a - b);
    this._syncUI();
    this._scheduleVisit();
  }

  selectAll() {
    this.activeValue = Array.from({ length: 18 }, (_, i) => i + 1);
    this._syncUI();
    this._scheduleVisit();
  }

  // Reset to the all-selected default: weeks 1-18 selected, no "weeks" param
  // (the query treats that as all weeks). Matches the all-selected initial
  // render so the pills don't appear to do nothing.
  clearAll() {
    this.activeValue = Array.from({ length: 18 }, (_, i) => i + 1);
    this._syncUI();
    this._scheduleVisit();
  }

  _syncUI() {
    const active = new Set(this.activeValue.map(Number));

    this.weekBtnTargets.forEach(btn => {
      const week = parseInt(btn.dataset.week, 10);
      btn.classList.toggle("active", active.has(week));
    });

    if (this.hasLabelTarget) {
      this.labelTarget.textContent = this._formatLabel();
    }
  }

  _formatLabel() {
    const active = this.activeValue.map(Number);
    if (active.length === 0 || active.length === 18) return "All weeks selected";
    if (active.length === 1) return `Week ${active[0]} selected`;
    return `${active.length} of 18 weeks selected`;
  }

  // Debounced turbo frame visit with updated URL params.
  _scheduleVisit() {
    clearTimeout(this._visitTimer);
    this._visitTimer = setTimeout(() => {
      const url = new URL(window.location.href);
      const active = this.activeValue;

      if (active.length === 0 || active.length === 18) {
        url.searchParams.delete("weeks");
      } else {
        url.searchParams.set("weeks", active.join(","));
      }
      url.searchParams.delete("page");
      history.replaceState(history.state, "", url.toString());

      const frame = document.getElementById(this.turboFrameValue);
      if (frame) {
        frame.src = url.toString();
      }
    }, DEBOUNCE_MS);
  }
}

// The CSRF token as a request-body param, for fetch() calls that write.
//
// CloudFront's origin-request policy forwards only an explicit header
// whitelist to Rails (ops/terraform/modules/cdn/main.tf), and X-CSRF-Token
// is not on it -- the list sits at AWS's ten-header cap. A token sent only
// as that header silently never reaches the origin, so Rails rejects the
// request with InvalidAuthenticityToken (a 422 in 0ms, before the action
// runs) on every deployed environment, while the same call passes in
// development and in request specs, where no CDN sits in between. That is
// exactly how the live odds board's preference saves shipped broken:
// every toggle and drag PUT 422'd, and the caller re-rendered the last
// state the server had actually saved.
//
// Spreading this into the JSON body sidesteps the CDN policy entirely:
// Rails' CSRF check reads params[:authenticity_token] natively, the same
// way it reads an HTML form's hidden field, and a JSON body is parsed into
// params before the check runs. Same approach as
// projection_override_controller.js's _csrfParam, where the failure was
// first confirmed live.
export function csrfParam() {
  return { authenticity_token: document.querySelector('meta[name="csrf-token"]')?.content }
}

import { Controller } from "@hotwired/stimulus"
import { dispatchAnalytics } from "dispatch_analytics"

// State-driven depth-chart controller.
//
// Depth Chart / Fantasy / Prop Betting are separate routes now (not
// client-side panels), so the client state left here is: view (roster /
// field) — which selects the roster table or the formation field — and,
// within the formation view, each unit's personnel package.
//
// The unit (offense / defense / special) is NOT panel state — all three
// units stay SSR'd together and switching is a same-page hash scroll. The
// unit-tab chrome (active class + aria-current) does reflect location.hash
// via _syncUnitTabs, so the selected tab matches the anchor. The
// roster/field view preference is written to sessionStorage whenever it
// changes and restored on connect, so Formation survives Offense ↔ Defense ↔
// Special Teams navigations in the same tab.
//
// ── ?view= / ?personnel= History API sync (non-crawlable on this page) ───
// On the Depth Chart page both are client-only convenience state, synced via
// history.replaceState (never pushState, so toggling doesn't spam the back
// stack) so a copied URL can restore the toggle. On-page view/package controls
// stay <button>s — never <a href="?..."> here — and these params are never part
// of the canonical or sitemap. Fantasy/Props mobile chrome may SSR one
// Formation deeplink (`?view=formation` + unit hash) into this page; that
// target still self-canonicalizes to the bare team URL. The formationsEnabled
// value (data-depth-chart-formations-enabled-value, set from the
// nfl_depth_chart_formations flag) gates whether that deeplink — or a
// sessionStorage preference from when the flag was on — is honored; off
// forces "roster" regardless of either.
//   - "view": the URL uses the SEO-facing term "formation"; internally the
//     panel/dataset key has always been "field" (see _urlViewParam /
//     _internalView below for the one place that mapping lives). "roster" is
//     the default, so it's omitted from the URL entirely to keep share links
//     clean; "field"/"formation" is written whenever selected.
//   - "personnel": a package key from packages.yml (e.g. "11", "nickel").
//     Because each unit (offense/defense/special) has its own package track
//     with its own default, there's no single cross-unit "default" value to
//     omit — whatever package was last clicked (in any unit) is written.
//     On connect, that value is applied to every unit whose track has a
//     matching key; units without a match keep their own SSR default.
//
// Visibility is hierarchical: hiding a parent panel hides its descendants via
// CSS. The unit-tab / view-switch / Key control row lives inside the
// depth-chart page only, so this controller is never mounted on the
// Fantasy/Prop Betting pages.
//
// On mobile the formation grid is intrinsically ~984px wide. CSS zoom/`cqw`
// proved unreliable across embedders (e.g. Responsively), so _fitFields()
// measures the panel and scales each visible .dc-field to fit.
//
// All CSS class strings come from Ruby via data-depth-chart-active-class
// (STYLE.md pattern); none are hard-coded here.
export default class extends Controller {
  static targets = [
    "viewPanel",
    "packagePanel",
    "packageButton",
    "viewButton",
    "unitTab",
  ]

  static classes = ["active", "packageActive", "unitActive"]
  static values = { formationsEnabled: Boolean }

  // sessionStorage key for the roster/field preference. Scoped to this feature
  // so it can't collide with other pages' keys.
  static VIEW_STORAGE_KEY = "nfl-depth-chart-view"

  // ── Lifecycle ────────────────────────────────────────────────────────────

  connect() {
    this._onResize = () => this._fitFields()
    window.addEventListener("resize", this._onResize)

    // Formation is gated by the nfl_depth_chart_formations flag (same on
    // every device — no mobile-specific behavior). When the flag is off,
    // DepthChartControls renders no switch to reach it, so a stored or
    // deep-linked (?view=formation) field view is ignored and roster is
    // forced regardless.
    const params = new URLSearchParams(window.location.search)
    this.view = this.formationsEnabledValue
      ? this._internalView(params.get("view")) || this._storedView() || "roster"
      : "roster"
    this.refresh()

    this._applyPersonnelParam(params.get("personnel"))

    this._onHashChange = () => this._syncUnitTabs()
    window.addEventListener("hashchange", this._onHashChange)
    this._syncUnitTabs()
  }

  disconnect() {
    window.removeEventListener("resize", this._onResize)
    window.removeEventListener("hashchange", this._onHashChange)
  }

  // ── State selectors ──────────────────────────────────────────────────────

  selectView(event) {
    this.view = event.params.view
    this._persistView()
    this.refresh()
    this._syncViewParam()
    dispatchAnalytics("depth_chart_view_select", { view: this.view })
  }

  // ── Package switch (11 Personnel / 12 Personnel / etc.) ─────────────────

  // Scoped to the clicked button's own unit (its closest .dc-field-chart
  // root — offense/defense/special each render one), not every package
  // panel/button on the page — see class comment (Task 2 review fix).
  selectPackage(event) {
    // Stimulus typecasts numeric params ("11" -> 11), but panel.dataset.package
    // and button dataset values are strings; coerce back so the comparisons in
    // the loop and _syncButtons match instead of hiding every package panel.
    const pkg = String(event.params.package)
    const root = event.currentTarget.closest(".dc-field-chart")
    if (!root) return

    this._activatePackage(root, pkg)
    this._scheduleFitFields()
    this._syncPersonnelParam(pkg)
  }

  // ── Internal ─────────────────────────────────────────────────────────────

  // Projects the current view onto every view panel and button. Safe when
  // targets are missing: each loop simply iterates an empty list.
  refresh() {
    this._showMatching(this.viewPanelTargets, "view", this.view)

    this._syncButtons(this.viewButtonTargets, "depthChartViewParam", this.view)
    this._scheduleFitFields()
  }

  // Read the last roster/field choice from sessionStorage. Returns null when
  // missing, invalid, or storage is unavailable (private mode, etc.).
  _storedView() {
    try {
      const value = sessionStorage.getItem(this.constructor.VIEW_STORAGE_KEY)
      return value === "roster" || value === "field" ? value : null
    } catch {
      return null
    }
  }

  // Persist the current roster/field choice so unit navigations restore it.
  _persistView() {
    try {
      sessionStorage.setItem(this.constructor.VIEW_STORAGE_KEY, this.view)
    } catch {
      // Ignore quota / private-mode failures — the page still works, just
      // without cross-unit view memory for this tab.
    }
  }

  // ?view= <-> internal panel/dataset key. The only mapping in either
  // direction lives here: "formation" (URL) <-> "field" (internal, unchanged
  // to avoid touching every existing data-view="field" attribute). Anything
  // else (missing param, unrecognized value) returns null so callers fall
  // back to the stored/default view.
  _internalView(urlValue) {
    if (urlValue === "formation") return "field"
    if (urlValue === "roster") return "roster"
    return null
  }

  // Inverse of _internalView. "roster" is the default and is omitted from
  // the URL entirely (see _syncViewParam), so only "field" maps to anything.
  _urlViewParam(internalValue) {
    return internalValue === "field" ? "formation" : null
  }

  // Writes the current view to ?view=, omitting the key when at the default
  // ("roster") so share links stay clean. history.replaceState (not
  // pushState) keeps the existing path + hash and avoids back-stack spam.
  _syncViewParam() {
    const url = new URL(window.location.href)
    const urlValue = this._urlViewParam(this.view)

    if (urlValue) {
      url.searchParams.set("view", urlValue)
    } else {
      url.searchParams.delete("view")
    }

    history.replaceState(history.state, "", url.toString())
  }

  // Writes the clicked package key to ?personnel=. There is no single
  // cross-unit default to omit against (each unit's package track has its
  // own default — see class comment), so any selection is written as-is.
  _syncPersonnelParam(pkg) {
    const url = new URL(window.location.href)
    url.searchParams.set("personnel", pkg)
    history.replaceState(history.state, "", url.toString())
  }

  // Applies a ?personnel= value (read on connect) to every unit whose
  // package track has a matching key; units without that key (e.g. a
  // "12"-only URL applied while :special only has "units") keep their own
  // SSR default untouched.
  _applyPersonnelParam(pkg) {
    if (!pkg) return

    for (const root of this._packageRoots()) {
      const hasMatch = this._packageButtonsIn(root).some((btn) => btn.dataset.depthChartPackageParam === pkg)
      if (hasMatch) this._activatePackage(root, pkg)
    }

    this._scheduleFitFields()
  }

  // Shows the matching package panel and syncs button active state, scoped
  // to a single unit's .dc-field-chart root — never every package
  // panel/button on the page (Task 2 review fix: this used to be global).
  _activatePackage(root, pkg) {
    for (const panel of this._packagePanelsIn(root)) {
      panel.hidden = panel.dataset.package !== pkg
    }

    this._syncButtons(this._packageButtonsIn(root), "depthChartPackageParam", pkg, this.packageActiveClass)
  }

  // Every unit's package-toolbar root (offense/defense/special each render
  // one .dc-field-chart), derived from the packageButton targets so the
  // scoping stays on the Stimulus Targets API rather than a raw querySelector
  // reaching outside it.
  _packageRoots() {
    const roots = this.packageButtonTargets.map((button) => button.closest(".dc-field-chart"))
    return new Set(roots.filter(Boolean))
  }

  _packagePanelsIn(root) {
    return this.packagePanelTargets.filter((panel) => panel.closest(".dc-field-chart") === root)
  }

  _packageButtonsIn(root) {
    return this.packageButtonTargets.filter((button) => button.closest(".dc-field-chart") === root)
  }

  // Hides every panel whose data-<key> attribute does not equal value.
  _showMatching(panels, key, value) {
    for (const panel of panels) {
      panel.hidden = panel.dataset[key] !== value
    }
  }

  // Flips the active class + aria-pressed on a button group from its param.
  // Package buttons carry a different active class than the view page
  // controls, so the class is a parameter (defaulting to the page-controls one).
  _syncButtons(buttons, paramKey, value, activeClass = this.activeClass) {
    for (const btn of buttons) {
      const active = btn.dataset[paramKey] === value
      btn.classList.toggle(activeClass, active)
      btn.setAttribute("aria-pressed", String(active))
    }
  }

  // Mirrors location.hash onto the unit-tab chrome. Unknown / leftover hashes
  // (e.g. #team-slug) fall back to #offense so a tab stays selected. Native
  // <a href="#…"> handles the hash write and scroll — this only updates class
  // + aria-current.
  _syncUnitTabs() {
    const hash = window.location.hash
    const known = this.unitTabTargets.some((tab) => tab.getAttribute("href") === hash)
    const activeHash = known ? hash : "#offense"

    for (const tab of this.unitTabTargets) {
      const active = tab.getAttribute("href") === activeHash
      tab.classList.toggle(this.unitActiveClass, active)
      if (active) {
        tab.setAttribute("aria-current", "true")
      } else {
        tab.removeAttribute("aria-current")
      }
    }
  }

  // Wait a frame so un-hidden field panels have a real layout box before we
  // measure them (hidden panels report 0 width).
  _scheduleFitFields() {
    requestAnimationFrame(() => this._fitFields())
  }

  // Scale each visible mobile formation grid so its intrinsic ~984px width fits
  // the panel. Prefer CSS zoom (affects layout); fall back to transform: scale
  // when zoom is unsupported. Zoom still reports the unscaled scrollWidth, so
  // overflow is forced to hidden after a successful fit to kill the leftover
  // scrollbar.
  _fitFields() {
    const desktop = window.matchMedia("(width >= 768px)").matches

    for (const field of this.element.querySelectorAll(".dc-field")) {
      field.style.zoom = ""
      field.style.transform = ""
      field.style.transformOrigin = ""
      field.style.marginBottom = ""
      field.style.overflowX = ""

      if (desktop || !this._isVisible(field)) continue

      const parent = field.parentElement
      if (!parent) continue

      const available = parent.clientWidth
      const natural = field.scrollWidth
      if (available <= 0 || natural <= available) continue

      const scale = available / natural

      if (typeof CSS !== "undefined" && CSS.supports("zoom", "0.5")) {
        field.style.zoom = String(scale)
      } else {
        field.style.transformOrigin = "top left"
        field.style.transform = `scale(${scale})`
        field.style.marginBottom = `${(scale - 1) * field.offsetHeight}px`
      }

      field.style.overflowX = "hidden"
    }
  }

  // True when the element and every ancestor up to this.element is shown.
  _isVisible(element) {
    let node = element

    while (node && node !== this.element) {
      if (node.hidden) return false

      const style = getComputedStyle(node)
      if (style.display === "none" || style.visibility === "hidden") return false

      node = node.parentElement
    }

    return true
  }
}

import { Controller } from "@hotwired/stimulus"

// Drives the single shared admin edit dialog rendered by
// Components::NFL::DepthCharts::OverrideDialog (one per page, not one per
// player). Each player's edit button (EditButton) fires `open` with its own
// player id/name and the field's current override + scraped values as
// Stimulus action params; this controller populates the dialog from those
// params before showing it.
//
// The dialog lives inside the "depth-chart-page" Turbo Stream replace
// target, so a successful save/revert closes it for free: the whole subtree
// (dialog included) is swapped for a fresh, closed one. No submit handling
// is needed here beyond populating fields before the browser submits.
//
// This controller is declared on the "depth-chart-page" wrapper (see
// Components::NFL::DepthCharts::ChartBody), not on the <dialog> itself —
// the per-player edit buttons that trigger `open` live elsewhere in that
// same subtree, and Stimulus resolves an action's controller by walking up
// from the clicked element, so the controller must be an ancestor of both
// the buttons and the dialog. The dialog itself is just the "dialog" target.
export default class extends Controller {
  static targets = [
    "dialog",
    "playerId",
    "title",
    "flagsOverride",
    "flagRookie",
    "flagQuestionable",
    "flagOut",
    "flagsScraped",
    "depthRank",
    "depthRankDefault",
    "depthPosition",
    "depthPositionDefault",
  ]

  open(event) {
    const p = event.params

    this.titleTarget.textContent = `Edit ${p.playerName}`
    this.playerIdTarget.value = p.playerId

    // A normal open always means "Save submits these badges as the override" —
    // reset the hidden flag in case a previous "Reset to scraped" in this same
    // dialog instance cleared it (the dialog element is reused across players).
    this.flagsOverrideTarget.value = "1"
    this._setFlags(p.flags, p.flagsScraped)
    this._setSelect(this.depthRankTarget, this.depthRankDefaultTarget, p.depthRank, p.depthRankScraped)
    this._setSelect(this.depthPositionTarget, this.depthPositionDefaultTarget, p.depthPosition, p.depthPositionScraped)

    this.dialogTarget.showModal()
  }

  close() {
    this.dialogTarget.close()
  }

  // "Reset to scraped": clear every field and blank the hidden flags_override
  // signal (the one thing that distinguishes this from a normal Save with
  // every badge unchecked) so the submit reverts the whole row at once, then
  // let this submit button's default action proceed (no preventDefault) so
  // the browser submits the now-blank form.
  resetAndSubmit() {
    this.depthRankTarget.value = ""
    this.depthPositionTarget.value = ""

    this.flagsOverrideTarget.value = ""
    this.flagRookieTarget.checked = false
    this.flagQuestionableTarget.checked = false
    this.flagOutTarget.checked = false
  }

  // effectiveValue is a comma-joined token string of the badges currently in
  // effect for this player, whether from an existing override or the
  // scraped computation ("rookie,out", or "" for none) — always a real
  // string, since Save now always submits the checked state as-is.
  _setFlags(effectiveValue, scrapedLabel) {
    const active = new Set(effectiveValue.split(",").filter(Boolean))

    this.flagRookieTarget.checked = active.has("rookie")
    this.flagQuestionableTarget.checked = active.has("questionable")
    this.flagOutTarget.checked = active.has("out")
    this.flagsScrapedTarget.textContent = scrapedLabel
  }

  _setSelect(select, defaultOption, overrideValue, scrapedValue) {
    defaultOption.textContent = `Scraped default (${scrapedValue || "none"})`
    select.value = overrideValue || ""
  }
}

import { Controller } from "@hotwired/stimulus";
import { restoreValueAfterMorph } from "restore_value_after_morph";

// Closes a native <details> dropdown when the visitor moves on: a
// pointer press anywhere outside it, or scrolling the page. A normal
// absolutely-positioned dropdown scrolls away with its trigger, but the
// freshness panel's phone layout is a position: fixed viewport sheet
// (live_odds.scss) -- without this it sits over the board through any
// amount of scrolling, until the next Turbo refresh happens to replace
// it.
//
// The open state also survives the live boards' refresh morphs: the
// server never renders `open`, so idiomorph strips the attribute and
// snapped the panel shut mid-read, every few seconds on a busy board.
// The element itself can't be data-turbo-permanent the way Customize+
// is -- a freshness panel exists to show fresh server data -- so the
// open state is snapshotted before the morph and restored after it
// instead, while the content underneath updates normally.
//
// Listeners are only attached while the panel is open, and the scroll
// listener rides the window without capture, so scrolling INSIDE the
// panel (its own overflow-y: auto) never closes it -- element scroll
// events don't bubble to the window.
//
// `close` is also an action, for the explicit collapse button each
// panel carries at its head: a visitor who has scrolled the book list
// to its end shouldn't have to hunt for the trigger (or scroll the
// page) to put the panel away.
export default class extends Controller {
  // scroll: false keeps the panel open through page scrolling (outside
  // presses still close it) -- the Customize+ editor opts out, since a
  // touch drag that the browser turns into a scroll would otherwise
  // close the panel mid-interaction.
  static values = { scroll: { type: Boolean, default: true } }

  connect() {
    this._onToggle = () => (this.element.open ? this._arm() : this._disarm());
    this.element.addEventListener("toggle", this._onToggle);
    if (this.element.open) this._arm();
    // Restoring `open` fires the native toggle event, so the dismiss
    // listeners re-arm through the same path a real click takes -- no
    // separate apply step needed.
    this._stopRestoring = restoreValueAfterMorph(
      this.element,
      () => this.element.open,
      (open) => (this.element.open = open),
      () => {},
    );
  }

  disconnect() {
    this._stopRestoring();
    this._disarm();
    this.element.removeEventListener("toggle", this._onToggle);
  }

  _arm() {
    if (this._armed) return;
    this._armed = true;
    this._onPointerDown = (event) => {
      if (!this.element.contains(event.target)) this._close();
    };
    document.addEventListener("pointerdown", this._onPointerDown);
    if (!this.scrollValue) return;
    this._onScroll = () => this._close();
    window.addEventListener("scroll", this._onScroll);
  }

  _disarm() {
    if (!this._armed) return;
    this._armed = false;
    document.removeEventListener("pointerdown", this._onPointerDown);
    if (this._onScroll) window.removeEventListener("scroll", this._onScroll);
  }

  close() {
    this._close();
  }

  _close() {
    this.element.open = false;
  }
}

