import { Controller } from "@hotwired/stimulus"

// Keeps a page heading and the document title in sync with a
// position-pill-strip toggle that lives outside the turbo frame the pill
// navigates -- originally the Fantasy Rankings Hub's platform name
// ("Fantasy Rankings | Underdog"), also reused by the Fantasy Rankings
// Show page's Half PPR / Full PPR heading. paramValue picks which
// position-pill-strip param this instance cares about, so more than one
// of these can coexist on a page listening for different toggles.
//
// The pill strip navigates the page's turbo frame, but the heading sits in
// the page header above that frame, so the frame response never repaints
// it. The <title> gets no help from Turbo either: the deferred stylesheets in
// the layout are swapped from media="print" to media="all" after load, which
// leaves the live <head> different from every response's <head>, so Turbo
// treats its tracked elements as changed and skips the head merge it would
// otherwise do on an advance frame visit.
//
// Retitling from the clicked pill rather than from the frame response also
// means the heading changes on click, in step with the pill's own active
// state, instead of a request later.
export default class extends Controller {
  static targets = ["label", "logo"]
  static values  = { template: String, param: { type: String, default: "platform" } }

  update({ detail: { param, pill } }) {
    if (param !== this.paramValue || !this.hasLabelTarget) return

    const label = pill.dataset.label ?? ""

    this.labelTarget.textContent = label
    this.#updateLogo(pill)
    this.#updateDocumentTitle(label)
    this.#refitHeading()
  }

  #updateLogo(pill) {
    if (!this.hasLogoTarget) return

    const logo = pill.querySelector("img")
    this.logoTarget.src = logo ? logo.src : ""
    this.logoTarget.hidden = !logo
  }

  // Placeholder the server leaves in templateValue, named after whichever
  // param this instance listens for -- "{platform}" or "{scoring}".
  #updateDocumentTitle(label) {
    if (!this.hasTemplateValue) return

    document.title = this.templateValue.replace(`{${this.paramValue}}`, label)
  }

  // The heading shrinks its font-size to fit on one line (fit-text), measured
  // against the text it had when it connected. Platform names differ enough in
  // width ("NFL Fantasy" vs "CBS") that a swap needs a remeasure.
  #refitHeading() {
    const heading = this.element.closest("[data-controller~='fit-text']")
    if (!heading) return

    this.application
      .getControllerForElementAndIdentifier(heading, "fit-text")
      ?.fit()
  }
}

import { Controller } from "@hotwired/stimulus"
import { dispatchAnalytics } from "dispatch_analytics"

export default class extends Controller {
  static values = { param: String, turboFrame: String }

  toggle() {
    const checked = this.element.querySelector("input[type=checkbox]").checked

    dispatchAnalytics("filter_change", {
      filter_name: this.paramValue,
      filter_value: String(checked),
    })

    const url = new URL(window.location.href)
    const turbo = window.Turbo

    if (checked) {
      url.searchParams.set(this.paramValue, "true")
    } else {
      url.searchParams.delete(this.paramValue)
    }

    if (!turbo) {
      window.location.assign(url.toString())
      return
    }

    if (this.turboFrameValue) {
      turbo.visit(url.toString(), { frame: this.turboFrameValue })
      return
    }

    turbo.visit(url.toString())
  }
}

import { Controller } from "@hotwired/stimulus"
import { dispatchAnalytics } from "dispatch_analytics"

export default class extends Controller {
  static targets = ["baseline", "trigger", "panel", "option", "selectedName", "select"]
  static classes = ["hidden", "active"]
  static values = {
    name: String,
    turboFrame: String,
    keepAllParam: Boolean,
  }

  connect() {
    // The native baseline is hidden and the styled trigger revealed via CSS
    // (html.js scoped rules in filter_combobox.scss), so no class swapping is
    // needed here. We just wire up event listeners.
    this._outsideClick = this._onOutsideClick.bind(this)
    this._closeAll = this._onCloseAll.bind(this)
    document.addEventListener("click", this._outsideClick)
    document.addEventListener("filter-combobox:close", this._closeAll)
  }

  disconnect() {
    document.removeEventListener("click", this._outsideClick)
    document.removeEventListener("filter-combobox:close", this._closeAll)
  }

  // ── Public actions ───────────────────────────────────────────────────────

  toggle(event) {
    event.preventDefault()
    event.stopPropagation()

    if (this._isOpen()) {
      this._close()
    } else {
      this._open()
    }
  }

  select(event) {
    event.preventDefault()
    this._selectOption(event.currentTarget)
  }

  // Handles native <select> change on mobile / no-JS-enhancement path.
  // Syncs the styled widget's display state then navigates.
  selectNative(event) {
    const select = event.currentTarget
    const value = select.value
    const label = select.options[select.selectedIndex]?.text ?? value

    dispatchAnalytics("filter_change", {
      filter_name: this.nameValue,
      filter_value: value,
    })

    if (this.hasSelectedNameTarget) {
      this.selectedNameTarget.textContent = label
    }

    this._visitWith(this.nameValue, value)
  }

  keydown(event) {
    if (!this._isOpen()) return

    switch (event.key) {
      case "ArrowDown":
        event.preventDefault()
        this._moveActive(1)
        break
      case "ArrowUp":
        event.preventDefault()
        this._moveActive(-1)
        break
      case "Home":
        event.preventDefault()
        this._setActiveIndex(0)
        break
      case "End":
        event.preventDefault()
        this._setActiveIndex(this._visibleOptions().length - 1)
        break
      case "Enter":
        event.preventDefault()
        this._confirmActive()
        break
      case "Escape":
        event.preventDefault()
        this._close()
        this.triggerTarget.focus()
        break
    }
  }

  // ── Private ──────────────────────────────────────────────────────────────

  _open() {
    document.dispatchEvent(
      new CustomEvent("filter-combobox:close", { detail: { except: this.element } }),
    )

    this.panelTarget.classList.remove(this.hiddenClass)
    this.triggerTarget.setAttribute("aria-expanded", "true")

    this._activeIndex = -1
    this._updateActiveDescendant()
  }

  _close() {
    this.panelTarget.classList.add(this.hiddenClass)
    this.triggerTarget.setAttribute("aria-expanded", "false")
    this._setActive(null)
  }

  _isOpen() {
    return !this.panelTarget.classList.contains(this.hiddenClass)
  }

  _visibleOptions() {
    return this.optionTargets.filter(o => !o.hidden)
  }

  _moveActive(delta) {
    const options = this._visibleOptions()
    if (!options.length) return

    const current = this._activeIndex ?? -1
    const next = (current + delta + options.length) % options.length
    this._setActiveIndex(next)
  }

  _setActiveIndex(index) {
    const options = this._visibleOptions()
    if (!options.length) return

    const clamped = Math.max(0, Math.min(index, options.length - 1))
    this._activeIndex = clamped
    this._setActive(options[clamped])
  }

  _setActive(option) {
    this.optionTargets.forEach(o => {
      o.classList.remove(this.activeClass)
      o.setAttribute("aria-selected", "false")
    })

    if (option) {
      option.classList.add(this.activeClass)
      option.setAttribute("aria-selected", "true")
      this._updateActiveDescendant(option)
    } else {
      this._updateActiveDescendant(null)
    }
  }

  _updateActiveDescendant(option = null) {
    if (option) {
      this.triggerTarget.setAttribute("aria-activedescendant", option.id)
    } else {
      this.triggerTarget.removeAttribute("aria-activedescendant")
    }
  }

  _confirmActive() {
    const options = this._visibleOptions()
    const active = this._activeIndex >= 0 ? options[this._activeIndex] : null
    if (active) {
      this._selectOption(active)
    }
  }

  _selectOption(option) {
    const value = option.dataset.value
    const label = option.dataset.triggerLabel || option.textContent.trim()

    dispatchAnalytics("filter_change", {
      filter_name: this.nameValue,
      filter_value: value,
    })

    this.selectedNameTarget.textContent = label

    // Keep the native <select> in sync
    if (this.hasSelectTarget) {
      this.selectTarget.value = value
    }

    this._close()
    this._visitWith(this.nameValue, value)
  }

  _visitWith(param, value) {
    // An option carrying a path names a page rather than a filter state, the
    // way a UI::Pills pill does: Fantasy Rankings puts position in the address,
    // so selecting one is a visit and not a param merge.
    const path = this._pathFor(value)
    if (path) {
      this._visit(path)
      return
    }

    const url = new URL(window.location.href)

    const clearsFilter = value === "" || value == null || (value === "all" && !this.keepAllParamValue)
    if (clearsFilter) {
      url.searchParams.delete(param)
    } else {
      url.searchParams.set(param, value)
    }

    this._visit(url.toString())
  }

  _pathFor(value) {
    const option = this.element.querySelector(`[data-value="${CSS.escape(String(value ?? ""))}"][data-path]`)

    return option ? option.dataset.path : null
  }

  _visit(target) {
    const turbo = window.Turbo

    if (!turbo) {
      window.location.assign(target)
      return
    }

    const frame = this.turboFrameValue
    if (frame) {
      turbo.visit(target, { frame })
    } else {
      turbo.visit(target)
    }
  }

  _onOutsideClick(event) {
    if (this.element.contains(event.target)) return
    if (this._isOpen()) this._close()
  }

  _onCloseAll(event) {
    if (event.detail?.except === this.element) return
    if (this._isOpen()) this._close()
  }
}

import { Controller } from "@hotwired/stimulus";

// Shrinks this element's own font-size, in whole pixels, until its text fits
// on one line within its current width -- for content whose length varies
// too much for a fixed/breakpoint-stepped font-size to reliably avoid
// wrapping or truncation (e.g. a player's full name). Requires the element
// to already be single-line via CSS (white-space: nowrap) with an ellipsis
// fallback below minSizeValue, in case even the floor doesn't fit.
export default class extends Controller {
  static values = { minSize: { type: Number, default: 10 } };

  connect() {
    this._handleResize = this._debounce(() => this.fit(), 100);
    window.addEventListener("resize", this._handleResize);
    this.fit();
    // Refit after the first paint settles: a fit measured mid-load (grid
    // tracks still sizing, flex containers not yet stretched) can see
    // transient overflow at every size and grind to the floor, and with
    // no resize event afterwards nothing would ever correct it. fit()
    // resets to the CSS size first, so a second pass fully recovers.
    requestAnimationFrame(() => requestAnimationFrame(() => this.fit()));
    // Refit once webfonts finish loading -- a fit measured against the
    // fallback font's metrics can be wrong in either direction once the
    // real font swaps in.
    document.fonts?.ready?.then(() => this.fit());
  }

  disconnect() {
    window.removeEventListener("resize", this._handleResize);
  }

  // Resets to the CSS-declared size first so this is safe to call
  // repeatedly (e.g. on resize, after previously shrinking) rather than
  // only ever shrinking further from whatever size it last landed on.
  fit() {
    this.element.style.fontSize = "";
    const maxSize = parseFloat(getComputedStyle(this.element).fontSize);

    let size = maxSize;
    while (this._overflows() && size > this.minSizeValue) {
      size -= 1;
      this.element.style.fontSize = `${size}px`;
    }
  }

  // An input's placeholder never contributes to scrollWidth, so briefly swap
  // it into the value and let the browser's own text layout report overflow
  // (canvas measureText reads a few px short of the real placeholder render).
  _overflows() {
    const { element } = this;
    if (element.placeholder === undefined) return this._textOverflows();
    if (element.value !== "") return element.scrollWidth > element.clientWidth;

    element.value = element.placeholder;
    const overflows = element.scrollWidth > element.clientWidth;
    element.value = "";
    return overflows;
  }

  // Fractional-width overflow check for text elements. scrollWidth and
  // clientWidth are integer-rounded CSS pixels, so a box that "fits" by
  // equal rounded values (77 == 77) can still hide sub-pixel overflow the
  // browser renders as an ellipsis. Range + getBoundingClientRect measure
  // both sides fractionally (and consistently under ancestor transforms,
  // which scale both rects by the same factor).
  _textOverflows() {
    const { element } = this;
    const range = document.createRange();
    range.selectNodeContents(element);
    const contentWidth = range.getBoundingClientRect().width;
    const style = getComputedStyle(element);
    const available =
      element.getBoundingClientRect().width -
      parseFloat(style.paddingLeft) -
      parseFloat(style.paddingRight) -
      parseFloat(style.borderLeftWidth) -
      parseFloat(style.borderRightWidth);
    return contentWidth - available > 0.1;
  }

  _debounce(fn, waitMs) {
    let timeout;
    return (...args) => {
      clearTimeout(timeout);
      timeout = setTimeout(() => fn(...args), waitMs);
    };
  }
}

// Shared by local_time_controller.js and relative_time_controller.js: the
// one absolute-date-in-the-viewer's-own-timezone format both eventually fall
// back to, so there's a single place that formatting lives rather than two
// controllers each hand-rolling their own Intl.DateTimeFormat config.
export function formatLocalDateTime(date) {
  return new Intl.DateTimeFormat(undefined, {
    month: "2-digit",
    day: "2-digit",
    year: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
  }).format(date)
}

import { Controller } from "@hotwired/stimulus"

// Admin game selector on the weekly projections board. Checkbox changes
// submit the form into the table's turbo frame; "All" and "Clear" set every
// box at once before submitting. The "n of N" count lives outside the turbo
// frame, so it is kept current here rather than by a server re-render.
export default class extends Controller {
  static targets = ["form", "checkbox", "count"]

  connect() {
    this.updateCount()
  }

  change() {
    this.updateCount()
    this.formTarget.requestSubmit()
  }

  all() {
    this.setAll(true)
  }

  clear() {
    this.setAll(false)
  }

  setAll(checked) {
    this.checkboxTargets.forEach((box) => { box.checked = checked })
    this.updateCount()
    this.formTarget.requestSubmit()
  }

  updateCount() {
    const checked = this.checkboxTargets.filter((box) => box.checked).length
    this.countTarget.textContent = `${checked} of ${this.checkboxTargets.length}`
  }
}

import { Controller } from "@hotwired/stimulus"

const SUPPRESSED_GOOGLE_MESSAGES = [
  "[GSI_LOGGER]",
  "Not signed in with the identity provider.",
]

export default class extends Controller {
  static targets = ["credentialForm", "credentialInput"]
  static values = { clientId: String }

  connect() {
    if (!this.hasClientIdValue || this.clientIdValue.length === 0) {
      return
    }

    this.loadGoogleScript()
      .then(() => this.initializeGoogleOneTap())
      .catch(() => {})
  }

  disconnect() {
    window.google?.accounts.id.cancel()
  }

  loadGoogleScript() {
    if (window.google?.accounts?.id) {
      return Promise.resolve()
    }

    if (!window.googleOneTapScriptPromise) {
      window.googleOneTapScriptPromise = new Promise((resolve, reject) => {
        const existing = document.querySelector('script[src="https://accounts.google.com/gsi/client"]')

        if (existing) {
          existing.addEventListener("load", resolve, { once: true })
          existing.addEventListener("error", reject, { once: true })
          return
        }

        const script = document.createElement("script")
        script.src = "https://accounts.google.com/gsi/client"
        script.async = true
        script.defer = true
        script.addEventListener("load", resolve, { once: true })
        script.addEventListener("error", reject, { once: true })
        document.head.appendChild(script)
      })
    }

    return window.googleOneTapScriptPromise
  }

  initializeGoogleOneTap() {
    this.installGoogleConsoleFilter()

    window.google.accounts.id.initialize({
      client_id: this.clientIdValue,
      callback: ({ credential }) => this.submitCredential(credential),
      auto_select: false,
      cancel_on_tap_outside: false,
      context: "signin",
    })

    window.google.accounts.id.prompt()
  }

  submitCredential(credential) {
    if (!credential || !this.hasCredentialInputTarget || !this.hasCredentialFormTarget) {
      return
    }

    this.credentialInputTarget.value = credential
    this.credentialFormTarget.requestSubmit()
  }

  installGoogleConsoleFilter() {
    if (window.googleOneTapConsoleFilterInstalled) {
      return
    }

    ;["error", "info", "log", "warn"].forEach((method) => {
      const originalMethod = console[method]

      console[method] = (...args) => {
        if (this.shouldSuppressGoogleMessage(args)) {
          return
        }

        originalMethod.apply(console, args)
      }
    })

    window.googleOneTapConsoleFilterInstalled = true
  }

  shouldSuppressGoogleMessage(args) {
    const message = args.map((arg) => String(arg)).join(" ")

    return SUPPRESSED_GOOGLE_MESSAGES.some((suppressedMessage) => message.includes(suppressedMessage))
  }
}

