import { Controller } from "@hotwired/stimulus"
import { restoreValueAfterMorph } from "restore_value_after_morph"

// Odds/%/Cents display toggle for the live odds board. Stimulus only ever
// manages one thing here: the format value reflected as
// data-odds-format-format-value on this controller's root element.
// live_odds.scss reads that attribute to show exactly one of BoardTable's
// three pre-rendered price formats per cell -- no DOM manipulation of the
// board itself, so a Turbo morph refreshing the board's prices never fights
// with the toggle's state.
//
// The one thing that DOES fight it: the server renders this value attribute
// as its default (cents on both boards -- it has no memory of a visitor's
// client-only choice), so a broadcast refresh's morph resets it and the
// buttons' aria-pressed with it -- see restore_value_after_morph.js for why
// this needs both the value put back AND formatValueChanged re-run.
export default class extends Controller {
  static values = { format: { type: String, default: "american" } }
  static targets = ["button"]

  connect() {
    this.stopRestoring = restoreValueAfterMorph(
      this.element,
      () => this.formatValue,
      (value) => { this.formatValue = value },
      () => this.formatValueChanged(),
    )
  }

  disconnect() {
    this.stopRestoring?.()
  }

  select(event) {
    this.formatValue = event.params.format
  }

  formatValueChanged() {
    this.buttonTargets.forEach((button) => {
      const pressed = button.dataset.oddsFormatFormatParam === this.formatValue
      button.setAttribute("aria-pressed", pressed ? "true" : "false")
    })
  }
}

import { Controller } from "@hotwired/stimulus";

// Pagination links render with a plain href carrying only `?page=N` (see
// UI::Pagination#page_url) so a crawler following static HTML never
// discovers a URL combining page with sort_field/sort_order/split/position
// (see RDM-03 — that combinatorial explosion is exactly why Pagination
// stopped forwarding the rest of the query string in the first place). That
// fix broke real users, though: paginating away from a sorted/filtered view
// reset it back to the default. This controller intercepts the click and
// merges the *current* window location's query params with the new page
// number before navigating, so sort/filter state survives pagination
// without ever appearing in the server-rendered href.
//
// A plain click (no modifier keys, primary mouse button) is the only case
// intercepted -- middle-click/ctrl-click/cmd-click to open in a new tab
// still follows the plain href, just without carrying that extra state
// forward. With JS unavailable entirely, the href still works the same way.
export default class extends Controller {
  static values = { frame: String };

  visit(event) {
    if (event.metaKey || event.ctrlKey || event.shiftKey || event.altKey || event.button !== 0) return;

    event.preventDefault();

    const target = new URL(this.element.href, window.location.href);
    const params = new URLSearchParams(window.location.search);
    params.set("page", target.searchParams.get("page"));
    target.search = params.toString();

    Turbo.visit(target.toString(), this.hasFrameValue ? { frame: this.frameValue } : {});
  }
}

import { Controller } from "@hotwired/stimulus";

// Cognito's password policy (min 8, upper, lower, number, symbol -- see
// ops/terraform/modules/cognito/main.tf) is otherwise only enforced after a
// full round trip to AWS. This mirrors it client-side and names exactly
// what's missing, instead of the browser's generic "please match the
// requested format".
//
// Keys must match Components::UI::PasswordRequirements::REQUIREMENTS, whose
// items register as `requirement` targets; each flips to metClass when its
// rule passes, so the checklist goes fully green exactly when the password
// is policy-valid.
const RULES = [
  { key: "length", test: (value) => value.length >= 8, message: "8+ characters" },
  { key: "lower", test: (value) => /[a-z]/.test(value), message: "a lowercase letter" },
  { key: "upper", test: (value) => /[A-Z]/.test(value), message: "an uppercase letter" },
  { key: "number", test: (value) => /\d/.test(value), message: "a number" },
  { key: "special", test: (value) => /[^A-Za-z0-9]/.test(value), message: "a special character" },
];

export default class extends Controller {
  static targets = ["password", "confirmation", "requirement"];
  static classes = ["met"];

  checkPassword() {
    const value = this.passwordTarget.value;
    const missing = RULES.filter((rule) => !rule.test(value)).map((rule) => rule.message);

    this.updateRequirements(value);
    this.passwordTarget.setCustomValidity(missing.length ? `Password needs ${missing.join(", ")}` : "");
    this.checkConfirmation();
  }

  checkConfirmation() {
    const matches = this.confirmationTarget.value === this.passwordTarget.value;
    this.confirmationTarget.setCustomValidity(matches ? "" : "Passwords do not match");
  }

  updateRequirements(value) {
    if (!this.hasMetClass) return;

    this.requirementTargets.forEach((item) => {
      const rule = RULES.find((candidate) => candidate.key === item.dataset.rule);
      item.classList.toggle(this.metClass, Boolean(rule && rule.test(value)));
    });
  }
}

