import { Controller } from "@hotwired/stimulus";

// Opens the printable rankings sheet and hands it to the browser's own print
// dialog, where "Save as PDF" produces the file. The sheet is a real server
// rendered URL, so the document that prints is built from the same rows the
// CSV exports rather than anything reassembled here.
//
// The sheet loads in an offscreen iframe so the visitor never leaves the
// board. If printing the frame throws -- iOS Safari does not reliably expose
// print() on a frame's contentWindow -- it falls back to opening the sheet in
// a new tab for the visitor to print themselves. Where the call neither works
// nor throws, that fallback cannot fire and the dialog simply does not open.
//
// The trigger is a <button> carrying the URL as a Stimulus value rather than
// an <a href>: the sheet is an HTML page, and a followed link to one opens
// crawl space the board does not own (SEO.md, RDM-02).
export default class extends Controller {
  static values = { url: String };

  disconnect() {
    this.#removeFrame();
  }

  open(event) {
    event.preventDefault();
    this.#removeFrame();

    const frame = document.createElement("iframe");
    frame.setAttribute("aria-hidden", "true");
    frame.style.position = "fixed";
    frame.style.width = "0";
    frame.style.height = "0";
    frame.style.border = "0";
    frame.style.visibility = "hidden";
    frame.src = this.urlValue;

    frame.addEventListener("load", () => {
      try {
        frame.contentWindow.focus();
        frame.contentWindow.print();
      } catch {
        this.#removeFrame();
        window.open(this.urlValue, "_blank", "noopener");
      }
    });

    this.frame = frame;
    document.body.appendChild(frame);
  }

  #removeFrame() {
    this.frame?.remove();
    this.frame = null;
  }
}

import { Controller } from "@hotwired/stimulus"

const DEBOUNCE_MS = 300

/**
 * Generic admin player-linking controller shared by ADP Links and Futures Links.
 * For each unlinked row, provides a debounced search input that queries a player
 * search endpoint, displays matching results in a dropdown, and populates a
 * hidden player_id field when a result is selected.
 */
export default class extends Controller {
  static targets = ["input", "results", "playerId", "playerDisplay", "selectionRow", "teamLogo"]
  static classes = ["noResults", "result"]
  static values = { url: String }

  connect() {
    this.searchTimeout = null
  }

  disconnect() {
    if (this.searchTimeout) clearTimeout(this.searchTimeout)
  }

  search() {
    const query = this.inputTarget.value.trim()
    if (query.length < 2) {
      this.resultsTarget.innerHTML = ""
      this.resultsTarget.hidden = true
      return
    }

    if (this.searchTimeout) clearTimeout(this.searchTimeout)

    this.searchTimeout = setTimeout(async () => {
      const response = await fetch(`${this.urlValue}?q=${encodeURIComponent(query)}`)
      const players = await response.json()
      this.renderResults(players)
    }, DEBOUNCE_MS)
  }

  renderResults(players) {
    if (players.length === 0) {
      this.resultsTarget.innerHTML = `<div class="${this.noResultsClass}">No players found</div>`
      this.resultsTarget.hidden = false
      return
    }

    this.resultsTarget.innerHTML = players
      .map(
        (p) =>
          `<button type="button" class="${this.resultClass}" data-action="player-link#select" data-id="${this.escapeHtml(String(p.id))}" data-name="${this.escapeHtml(p.name)}" data-position="${this.escapeHtml(p.position || "")}" data-team="${this.escapeHtml(p.team || "")}">${this.escapeHtml(p.name)} — ${this.escapeHtml(p.position || "?")} — ${this.escapeHtml(p.team || "FA")}</button>`,
      )
      .join("")
    this.resultsTarget.hidden = false
  }

  select(event) {
    const btn = event.currentTarget
    this.playerIdTarget.value = btn.dataset.id
    this.playerDisplayTarget.textContent = `${btn.dataset.name} · ${btn.dataset.position || "?"} · ${btn.dataset.team || "FA"}`
    this.inputTarget.value = ""
    this.resultsTarget.innerHTML = ""
    this.resultsTarget.hidden = true

    if (this.hasTeamLogoTarget) {
      const team = (btn.dataset.team || "FA").toUpperCase()
      this.teamLogoTarget.textContent = team
    }

    if (this.hasSelectionRowTarget) {
      this.selectionRowTarget.hidden = false
    }
  }

  escapeHtml(text) {
    const div = document.createElement("div")
    div.textContent = text
    return div.innerHTML.replace(/"/g, "&quot;").replace(/'/g, "&#39;")
  }
}

import { Controller } from "@hotwired/stimulus"
import { dispatchAnalytics } from "dispatch_analytics"

const DEBOUNCE_MS = 400

let pendingRefocus = null

export default class extends Controller {
  static targets = ["input"]
  static values = {
    param: { type: String, default: "q" },
    // Numeric "Min ___" qualifier inputs need 0 to survive as an explicit,
    // unfiltered value distinct from the param never being submitted at all
    // (which falls back to a computed default). Plain search inputs (e.g.
    // Search Player) should still just drop the param when cleared.
    zeroOnClear: { type: Boolean, default: false },
  }

  connect() {
    this.searchTimeout = null

    if (pendingRefocus === this.paramValue) {
      pendingRefocus = null
      this.restoreCaret()
    }
  }

  restoreCaret() {
    const el = this.inputTarget

    // Defer to the next frame so we run after Turbo finishes swapping the
    // frame DOM — otherwise our focus/caret can be overwritten by Turbo's
    // own focus restoration.
    requestAnimationFrame(() => {
      el.focus()
      const length = el.value.length

      // setSelectionRange throws on type="number". Temporarily swap to
      // "text", position the caret at the end, then swap back.
      const originalType = el.type
      const needsSwap = originalType === "number"
      if (needsSwap) el.type = "text"

      try {
        el.setSelectionRange(length, length)
      } catch {
        // Ignore — input type doesn't support selection.
      }

      if (needsSwap) el.type = originalType
    })
  }

  disconnect() {
    if (this.searchTimeout) {
      clearTimeout(this.searchTimeout)
    }
  }

  search() {
    const query = this.sanitizedQuery()

    if (this.searchTimeout) {
      clearTimeout(this.searchTimeout)
    }

    this.searchTimeout = setTimeout(() => {
      const url = new URL(window.location.href)
      const paramName = this.paramValue

      if (query.length > 0) {
        url.searchParams.set(paramName, query)
      } else if (this.zeroOnClearValue) {
        url.searchParams.set(paramName, "0")
      } else {
        url.searchParams.delete(paramName)
      }

      const destination = `${url.pathname}${url.searchParams.toString() ? `?${url.searchParams.toString()}` : ""}`
      const turboFrame = this.inputTarget.dataset.turboFrame
      const options = turboFrame ? { action: "replace", frame: turboFrame } : { action: "replace" }
      const turbo = window.Turbo

      if (!turbo) {
        window.location.assign(destination)
        return
      }

      dispatchAnalytics("player_search", { search_term: query })
      pendingRefocus = paramName
      turbo.visit(destination, options)
    }, DEBOUNCE_MS)
  }

  sanitizedQuery() {
    if (this.inputTarget.type !== "number") {
      return this.inputTarget.value.trim()
    }

    const digitsOnly = this.inputTarget.value.replace(/\D/g, "")

    if (this.inputTarget.value !== digitsOnly) {
      this.inputTarget.value = digitsOnly
    }

    return digitsOnly
  }
}

import { Controller } from "@hotwired/stimulus"
import { dispatchAnalytics } from "dispatch_analytics"

export default class extends Controller {
  static targets = ["pill"]
  // `default` names the value this param carries when the URL says nothing at
  // all -- so selecting it has to remove the param rather than write it. A page
  // whose bare URL already loads that value would otherwise gain a second
  // address for the state it is already showing, and the server would redirect
  // straight back off it. Optional: a strip that configures no default keeps
  // the previous behaviour of always writing the value it was given.
  static values  = { param: String, frame: String, default: String }

  select(event) {
    event.preventDefault()

    const pill  = event.currentTarget
    const value = pill.dataset.value

    dispatchAnalytics("filter_change", {
      filter_name: this.paramValue,
      filter_value: value,
    })

    this.pillTargets.forEach(p => {
      p.classList.remove("active")
      if (p.hasAttribute("aria-pressed")) p.setAttribute("aria-pressed", "false")
    })
    pill.classList.add("active")
    if (pill.hasAttribute("aria-pressed")) pill.setAttribute("aria-pressed", "true")

    // Lets anything outside the navigated frame react to the new selection --
    // the pill itself rides along so listeners can read its data attributes
    // (e.g. the Fantasy Rankings heading, which shows the selected platform but
    // lives outside the frame the visit below replaces).
    this.dispatch("select", { detail: { param: this.paramValue, value, pill } })

    // A pill carrying a path names a page rather than a filter state: Fantasy
    // Rankings puts position and scoring in the address, so the click is a
    // visit and not a param merge. Still a button rather than a link, because
    // some of those addresses are toggle states no crawler should be handed.
    if (pill.dataset.path) {
      this.#visit(pill.dataset.path)
      return
    }

    const url = new URL(window.location.href)

    // "all"/""/null are the absence of a selection, and a configured default is
    // the selection the bare URL already makes -- both are spelled by leaving
    // the param off entirely.
    if (value === "all" || value === "" || value == null || value === this.defaultValue) {
      url.searchParams.delete(this.paramValue)
    } else {
      url.searchParams.set(this.paramValue, value)
    }

    // Reset to page 1 when filtering
    url.searchParams.delete("page")

    this.#visit(url.toString())
  }

  #visit(target) {
    const turbo = window.Turbo
    if (!turbo) {
      window.location.assign(target)
      return
    }

    if (this.frameValue) {
      turbo.visit(target, { frame: this.frameValue })
    } else {
      turbo.visit(target)
    }
  }
}

import { Controller } from "@hotwired/stimulus"

// Applies a FIXED preset query string to an otherwise crawl-clean menu link
// at click time.
//
// Some stat-menu entries are really a pointer at another stat's page with
// one filter always preselected -- e.g. the Quarterback+ menu's "QB Rushing
// Yds Per Attempt" row always means the base rushing leaderboard filtered to
// QB. Rendering that as `<a href="...?position=QB">` would make it a real,
// crawlable `?position=` anchor, which is exactly what the crawl-space rule
// in SEO.md forbids (RDM-05/06) -- one clean URL per stat page, not a spray
// of filter-state variants.
//
// carry_filters_controller solved the sibling problem -- carrying a
// visitor's OWN current filters across a clean link -- the same way: keep
// the href clean for crawlers, apply the query client-side on click. This
// controller is the fixed-preset counterpart: the query comes from the menu
// entry itself (a Stimulus value), not from the current URL.
export default class extends Controller {
  static values = { query: String }

  visit(event) {
    // Modified and non-primary clicks are the browser's to handle -- cmd/ctrl
    // to open a new tab, shift for a new window, middle-click likewise.
    // Calling preventDefault on those would navigate the current tab instead,
    // the one thing the visitor didn't ask for. They follow the plain href,
    // so they land on the destination page without the preset applied -- the
    // same trade carry_filters_controller#navigate makes.
    if (event.metaKey || event.ctrlKey || event.shiftKey || event.altKey || event.button !== 0) return

    const link = event.currentTarget
    const target = new URL(link.href, window.location.origin)
    target.search = this.queryValue

    event.preventDefault()
    const turbo = window.Turbo
    if (turbo) {
      turbo.visit(target.toString())
    } else {
      window.location.assign(target.toString())
    }
  }
}

