import { Controller } from "@hotwired/stimulus"
import { impliedProbability } from "implied_probability"

// Flashes a soft background on every sportsbook/prediction-market price cell
// when the live-odds board's Postgres-triggered broadcast changes its value:
// green if the price improved for the bettor, red if it worsened, no flash
// for a move under CHANGE_THRESHOLD (noise, not a signal worth calling out).
//
// Must hook turbo:before-morph-element / turbo:morph-element, not
// turbo:render: idiomorph overwrites each price cell's own data-price
// attribute in place as it walks the tree, so by the time turbo:render fires
// (once, after the whole page has already morphed) every cell's "before"
// value is already gone. before-morph-element fires once per element right
// before that element's own mutation -- the one synchronous window where
// both the old (event.target.dataset.price) and soon-to-be-new value exist
// -- so the old value is stashed per-element and read back in
// morph-element, which fires immediately after for that same element, once
// idiomorph has applied the new value.
const CHANGE_THRESHOLD = 0.05 // relative move in implied probability

export default class extends Controller {
  static classes = ["better", "worse"]
  static values = { holdMs: { type: Number, default: 1400 } }

  connect() {
    this._previous = new WeakMap()
    this._onBeforeMorph = (event) => this.captureBefore(event)
    this._onMorph = (event) => this.compareAfter(event)
    document.addEventListener("turbo:before-morph-element", this._onBeforeMorph)
    document.addEventListener("turbo:morph-element", this._onMorph)
  }

  disconnect() {
    document.removeEventListener("turbo:before-morph-element", this._onBeforeMorph)
    document.removeEventListener("turbo:morph-element", this._onMorph)
  }

  captureBefore(event) {
    const el = event.target
    if (!isPriceCell(el)) return

    this._previous.set(el, el.dataset.price)
  }

  compareAfter(event) {
    const el = event.target
    if (!isPriceCell(el)) return

    const before = this._previous.get(el)
    this._previous.delete(el)
    if (before === undefined) return

    const beforePrice = parsePrice(before)
    const afterPrice = parsePrice(el.dataset.price)
    if (beforePrice === null || afterPrice === null || beforePrice === afterPrice) return

    const beforeProbability = impliedProbability(beforePrice)
    const afterProbability = impliedProbability(afterPrice)
    const relativeChange = Math.abs(afterProbability - beforeProbability) / beforeProbability
    if (relativeChange < CHANGE_THRESHOLD) return

    // Higher American odds are always the better price for the bettor,
    // across the whole range (-140 beats -150, +105 beats -105, etc.) --
    // no sign-case-by-case logic needed.
    const flashClass = afterPrice > beforePrice ? this.betterClass : this.worseClass
    el.classList.remove(this.betterClass, this.worseClass)
    // Force a reflow so re-adding the same class restarts its CSS animation
    // if this cell already flashed once and is flashing again.
    void el.offsetWidth
    el.classList.add(flashClass)
    setTimeout(() => el.classList.remove(flashClass), this.holdMsValue)
  }
}

function isPriceCell(el) {
  return el instanceof Element && el.matches('[data-book-filter-target="price"]')
}

function parsePrice(raw) {
  if (raw === undefined || raw === "") return null
  const value = Number(raw)
  return Number.isFinite(value) ? value : null
}

import { Controller } from "@hotwired/stimulus";

// Opens the browser's own print dialog for the current page. Used by the
// Fantasy Rankings export cluster, whose Print button is a plain button rather
// than a link -- there is nothing to navigate to, the page prints itself.
export default class extends Controller {
  print() {
    window.print();
  }
}

import { Controller } from "@hotwired/stimulus"

// Inline override editing for the admin NFL projection review spreadsheet.
//
// Declared once on the page wrapper (Views::Admin::NFL::ProjectionReviews::Show).
// Every override <input> and admin_injured <select> fires `stage` on
// change/Enter with its field name and player identity as action params.
//
// EDITING WRITES NOTHING. `stage` records the edit in an in-memory dirty map
// and previews it (styling, totals, market tints, sidebar rank); the Submit
// button PATCHes every staged edit to
// Admin::NFL::ProjectionOverridesController#batch in ONE request, which
// applies them in one transaction and recomputes each affected team exactly
// once. Escape reverts one cell to its last saved value (tracked in
// data-last-value, which only ever holds server-known state); Revert all
// drops every staged edit. A beforeunload guard — plus a confirm on any Turbo
// visit away from this URL — keeps staged edits from disappearing silently.
//
// Semantics mirror the server: a blank value clears the override (the cell
// then shows the model value the server returns as `effective`), while "0"
// is a real override — only the server's `value: null` marks a cell as not
// overridden. Marking a player OUT toggles the row's zeroed class so every
// cell in the row previews the pipeline's zeroing.
//
// Staging the Projection field (pprFieldValue) directly edits the pipeline's
// outcome, so every other numeric input in the row locks live — mirroring
// the server-side lock in ::NFL::ProjectionOverrideEdit#ppr_locks_other_inputs?
// — until the override is cleared. Sibling edits already staged still submit,
// and the server still takes them: they ride in the same fields hash as the
// Projection edit, which is exactly the case that rule exempts.
//
// After every staged edit the affected column sums are recomputed from
// the current effective cell values: each position <tbody>'s subtotal row and
// the <tfoot> team total row carry data-total-column cells matched against
// the body cells' data-column. OUT rows contribute 0.
//
// A staged clear is the one place the DOM alone is not enough: the input goes
// blank before any write, and a blank cell contributes 0 to a sum. The server
// stamps the post-clear fallback on the input as data-model-value, so the
// totals preview a cleared cell as the model value it is about to revert to.
//
// Clearing an OUT status does NOT restore the row's values: EffectiveRow
// zeroes every attribute server-side, so an already-OUT row renders every
// input at "0.0", and this controller only toggles the zeroed class. Totals,
// market tints, the props count and the sidebar rank all stay at 0 until the
// page is reloaded. Pre-existing for the totals; the market surfaces inherit
// it. Fixing it means the upsert endpoint returning the row's effective
// values on an admin_injured change. A team total cell stamped with data-model-value (the team-level
// model volume) is tinted when the sum deviates >10% from it, mirroring the
// server's NumberFormat.discrepancy? rule. The caption's team-total summary
// stats mirror the same tfoot totals for the six passing/rushing/receiving
// yards+TD columns, and its passing/receiving reconciliation warning
// re-evaluates whenever an edit touches one of those columns.
//
// The market rows (MarketRow) beneath each player carry the book's line for
// every column. They are a disclosure: `togglePropsVisible` flips the wrapper
// class and remembers the choice in localStorage, because the Turbo refresh
// morph re-renders from server HTML that never knows the toggle happened. A
// cell's over/under tint is relative to the player's CURRENT projection, so an
// edit — or an OUT toggle, which zeroes the whole row and therefore reads as a
// genuine "under" against a real line — re-decides the affected cells and the
// caption's "Props +/- 20%" count.
//
// Every staged edit (and every reconciled one) dispatches
// `projection-override:saved` with the player's now-effective PPR value,
// which the sidebar listens for to re-rank. The name predates staging and is
// kept because it is the sidebar's DOM contract; it means "this player's
// projection changed", whether or not it is committed yet.
//
// Editable-cell CSS class names arrive via the Stimulus classes API from Ruby
// (PlayerRow::OVERRIDDEN_CLASS etc.). The few literals below are class names on
// server HTML this controller does not own (the page wrapper, MarketRow's
// cells, the caption warning) — they are the page's DOM contract rather than
// this controller's own state classes.

// Columns behind the caption's passing/receiving reconciliation warning
// (TeamTable::SUMMARY_COLUMNS' yards/TD pairs) — every passing yard or
// touchdown is also a receiving yard or touchdown for the same team, so
// these two independently modeled totals should roughly agree.
const RECONCILIATION_ATTRS = new Set([
  "model_value_passing_yards",
  "model_value_receiving_yards",
  "pred_passing_tds",
  "pred_receiving_tds",
])

const RECONCILIATION_WARNING_CLASS = "proj-grid__summary-warning--visible"
const SUMMARY_VALUE_SELECTOR = ".proj-grid__summary-value"

// Props disclosure (Show's wrapper class + the toggle's own checkbox) and the
// market-cell edge classes (MarketRow::EDGE_CLASSES).
const PROPS_VISIBLE_CLASS = "proj-review--props-visible"
const PROPS_STORAGE_KEY = "projReviewShowProps"
const PROPS_TOGGLE_SELECTOR = '[data-action*="projection-override#togglePropsVisible"]'
const MARKET_EDGE_CLASSES = { over: "proj-grid__market-cell--over", under: "proj-grid__market-cell--under" }

// Columns::PPR_ATTR — the data-column of the final Projection cell, whose
// value rides along on the saved event for the sidebar's ranking.
const PPR_COLUMN = "model_ppr_projection"

// The two relative-difference rules on this page: >10% off a baseline/model
// volume tints a cell, >20% off a market line is an edge. Same arithmetic,
// different thresholds — see _relativeDiff.
const DISCREPANCY_THRESHOLD = 0.1
const EDGE_THRESHOLD = 0.2

export default class extends Controller {
  static targets = ["status", "teamTable", "submitButton", "revertButton", "pendingCount"]
  static classes = ["overridden", "zeroed", "saving", "deviation", "pprLocked", "refreshing", "pending", "rejected"]
  static values = { batchUrl: String, rerunUrl: String, season: Number, week: Number, pprField: String }

  connect() {
    // Staged, unsubmitted edits, keyed playerId|field. Entries hold the
    // input's id rather than the element: a Turbo refresh morph can replace
    // the node, and getElementById always resolves the live one.
    this._pending = new Map()

    this._applyPropsVisible(this._storedPropsVisible())
    this._syncPending()

    // A refresh morph preserves the wrapper element, so connect() does not
    // fire again — but idiomorph still syncs its class attribute back to the
    // server's, which drops the disclosure class and makes the market rows
    // vanish under an admin who never touched the toggle. Re-apply after the
    // morph lands, the same way the sidebar re-applies its position filter.
    // The morph also re-renders every input from server HTML that knows
    // nothing about staged edits, so those get re-applied in the same pass
    // rather than silently reverting.
    this._onTurboRender = () => {
      this._applyPropsVisible(this._storedPropsVisible())
      this._reapplyPending()
    }
    document.addEventListener("turbo:render", this._onTurboRender)

    // beforeunload covers real navigation (closing the tab, typing a URL).
    this._onBeforeUnload = (event) => {
      if (this._pending.size > 0) event.preventDefault()
    }
    window.addEventListener("beforeunload", this._onBeforeUnload)

    // Turbo visits never fire beforeunload, and the game filter auto-submits
    // one on change. A refresh morph is also a visit, but always to the
    // current URL — those are the broadcast recomputes, whose staged edits
    // _reapplyPending restores, so they must not prompt.
    this._onBeforeVisit = (event) => {
      if (this._pending.size === 0 || event.detail?.url === window.location.href) return
      if (!window.confirm(`${this._editLabel(this._pending.size)} not submitted. Leave and lose them?`)) {
        event.preventDefault()
      }
    }
    document.addEventListener("turbo:before-visit", this._onBeforeVisit)
  }

  disconnect() {
    document.removeEventListener("turbo:render", this._onTurboRender)
    document.removeEventListener("turbo:before-visit", this._onBeforeVisit)
    window.removeEventListener("beforeunload", this._onBeforeUnload)
  }

  // Disclosure for the market rows. Deliberately changes the table's height —
  // the one sanctioned exception to the page's no-layout-shift rule — and is
  // remembered across the Turbo refresh morph, which re-renders the whole page
  // from server HTML that never carries the class.
  togglePropsVisible(event) {
    const visible = event.target.checked
    this._applyPropsVisible(visible)
    // Injects or removes a couple of hundred cells, so it gets the same polite
    // announcement any other dynamic region on this page gets.
    const rows = this.element.querySelectorAll(".proj-grid__market-row").length
    this._announce(visible ? `Player props shown — ${rows} market rows` : "Player props hidden")
    try {
      window.localStorage.setItem(PROPS_STORAGE_KEY, String(visible))
    } catch {
      // Storage denied (private mode, blocked cookies): the toggle still works
      // for this page view, it just won't survive the next morph.
    }
  }

  _storedPropsVisible() {
    try {
      return window.localStorage.getItem(PROPS_STORAGE_KEY) === "true"
    } catch {
      return false
    }
  }

  // Keeps the checkbox in step with the class it drives, so a restored state
  // never renders an unchecked box over visible props.
  _applyPropsVisible(visible) {
    this.element.classList.toggle(PROPS_VISIBLE_CLASS, visible)
    const toggle = this.element.querySelector(PROPS_TOGGLE_SELECTOR)
    if (toggle) toggle.checked = visible
  }

  // Records an edit without writing it. data-last-value stays the server's
  // value throughout, so Escape can still put the cell back and a cell edited
  // back to its saved value unstages itself instead of submitting a no-op.
  stage(event) {
    const input = event.target
    const { field, label, playerId, playerName } = event.params
    const key = this._key(playerId, field)
    const staged = this._pending.get(key)

    if (input.value === input.dataset.lastValue) {
      if (!staged) return
      this._pending.delete(key)
    } else if (staged && staged.value === input.value) {
      // Enter fires keydown.enter AND (on blur) change for the same edit.
      // Nothing is in flight to race any more, but the second pass would
      // still re-announce and re-run every recalculation for no change.
      return
    } else {
      this._pending.set(key, { key, id: input.id, field, label, playerId, playerName, value: input.value })
    }

    this._applyStaged(input, field, this._pending.get(key))
    this._refreshDerived(input, field, playerId)
    this._syncPending()
    this._announce(this._stagedMessage(playerName, label, input, this._pending.has(key)))
  }

  // Sends every staged edit in one PATCH. The response reports each edit
  // separately: `applied` entries carry the server's effective value to
  // reconcile the cell against, `rejected` entries stay staged and flagged so
  // an edit the server refused is never silently dropped.
  async submit(event) {
    event?.preventDefault()
    if (this._pending.size === 0) return

    const count = this._pending.size
    // Captured up front: reconciling deletes the applied entries from the
    // dirty map, and those inputs still have to be handed back at the end.
    const inputs = Array.from(this._pending.values(), (entry) => this._inputFor(entry)).filter(Boolean)
    this._setSubmitting(inputs, true)
    this._announce(`Submitting ${this._editLabel(count)}…`)

    try {
      const data = await this._patch(this.batchUrlValue, { edits: this._groupedEdits() })
      this._reconcile(data)
    } catch (error) {
      this._announce(`Error submitting edits: ${error.message} — nothing was saved, your edits are still staged`)
    } finally {
      this._setSubmitting(inputs, false)
      this._syncPending()
    }
  }

  // Drops every staged edit, putting each cell back to its saved value.
  revertAll() {
    const count = this._pending.size
    if (count === 0) return

    for (const entry of Array.from(this._pending.values())) this._unstage(entry)
    this._syncPending()
    this._announce(`Reverted ${this._editLabel(count)}`)
  }

  // One player per entry: a player's staged cells go up as a single fields
  // hash, which is also what lets a Projection edit and a sibling input edit
  // submit together (see the header note on the PPR lock).
  _groupedEdits() {
    const byPlayer = new Map()
    for (const entry of this._pending.values()) {
      let fields = byPlayer.get(entry.playerId)
      if (!fields) {
        fields = {}
        byPlayer.set(entry.playerId, fields)
      }
      fields[entry.field] = entry.value
    }
    return Array.from(byPlayer, ([playerId, fields]) => ({ player_id: playerId, fields }))
  }

  _reconcile(data) {
    for (const row of data.applied ?? []) this._reconcileApplied(row)
    for (const row of data.rejected ?? []) this._reconcileRejected(row)

    const teams = data.refresh_teams ?? []
    if (teams.length > 0) this._markRefreshing((table) => teams.includes(table.dataset.team))
    this._announce(this._submittedMessage(data))
  }

  _reconcileApplied(row) {
    const key = this._key(row.player_id, row.field)
    const entry = this._pending.get(key)
    this._pending.delete(key)

    const input = this._inputFor(entry)
    if (!input) return

    input.classList.remove(this.pendingClass, this.rejectedClass)
    // The rejection reason is the only thing that ever puts a title on an
    // input (the baseline tooltip lives on the cell), so clearing it is safe.
    input.removeAttribute("title")
    this._applySaved(input, row.field, row)
    this._refreshDerived(input, row.field, row.player_id)
  }

  // A refused edit keeps its staged value and its place in the dirty map —
  // the admin decides whether to fix it or revert it — and is flagged so the
  // cell says which one it was.
  _reconcileRejected(row) {
    const input = this._inputFor(this._pending.get(this._key(row.player_id, row.field)))
    if (!input) return

    input.classList.add(this.rejectedClass)
    input.title = row.errors.join(" ")
  }

  _submittedMessage({ applied = [], rejected = [], refresh_teams: teams = [] }) {
    const saved = `Saved ${this._editLabel(applied.length)}`
    const recalculating = teams.length > 0 ? ` — ${teams.join(", ")} projections recalculating` : ""
    if (rejected.length === 0) return `${saved}${recalculating}`

    return `${saved}${recalculating}. ${this._editLabel(rejected.length)} rejected and still staged: ` +
      `${this._rejectionSummary(rejected)}`
  }

  // Distinct reasons rather than one line per cell: a whole team rejecting on
  // kickoff would otherwise read out the same sentence forty times.
  _rejectionSummary(rejected) {
    return Array.from(new Set(rejected.flatMap((row) => row.errors))).join(" ")
  }

  _stagedMessage(playerName, label, input, staged) {
    if (!staged) return `Reverted ${playerName} ${label}`
    return `Staged ${playerName} ${label}: ${this._display(input.value)} — submit to save`
  }

  _key(playerId, field) {
    return `${playerId}|${field}`
  }

  _inputFor(entry) {
    return entry ? document.getElementById(entry.id) : null
  }

  // Puts one cell back to its saved value and forgets the staged edit.
  _unstage(entry) {
    this._pending.delete(entry.key)
    const input = this._inputFor(entry)
    if (!input) return

    input.value = input.dataset.lastValue
    this._applyStaged(input, entry.field, null)
    this._refreshDerived(input, entry.field, entry.playerId)
  }

  // Re-applies staged edits over server HTML a refresh morph just rendered.
  // An input that no longer exists (the player left the filtered game) takes
  // its staged edit with it — there is nothing left to submit it against.
  _reapplyPending() {
    for (const entry of Array.from(this._pending.values())) {
      const input = this._inputFor(entry)
      if (!input) {
        this._pending.delete(entry.key)
        continue
      }
      input.value = entry.value
      this._applyStaged(input, entry.field, entry)
      this._refreshDerived(input, entry.field, entry.playerId)
    }
    this._syncPending()
  }

  // Optimistic styling for a cell: the same overridden/zeroed/lock treatment
  // a saved edit gets, plus the pending marker. `staged` null restores the
  // server truth the input still carries in its data attributes.
  _applyStaged(input, field, staged) {
    input.classList.toggle(this.pendingClass, Boolean(staged))
    input.classList.remove(this.rejectedClass)
    input.removeAttribute("title")
    const value = staged ? staged.value : input.dataset.lastValue

    if (field === "admin_injured") {
      input.closest("tr").classList.toggle(this.zeroedClass, value === "OUT")
      return
    }

    // Blank stages a CLEAR, which is not an override — only a value is.
    const overridden = staged ? value.trim() !== "" : input.dataset.override === "true"
    input.classList.toggle(this.overriddenClass, overridden)
    if (field === this.pprFieldValue) this._toggleInputLock(input, overridden)
  }

  // Everything a value change invalidates, in one call: the column sums, the
  // market tints against them, and the sidebar's rank.
  _refreshDerived(input, field, playerId) {
    this._refreshTotals(input, field)
    this._refreshMarket(input, field, playerId)
    this._notifySaved(input, field, playerId)
  }

  // The Submit button's own label is the pending count, so it is min-width'd
  // in CSS and the polite count line under it has its height pre-allocated —
  // neither may move the spreadsheet as the count changes.
  _syncPending() {
    const count = this._pending.size
    // Two copies of this button exist -- the page-level one and one per
    // team's caption, so an admin editing a team never has to scroll up to
    // submit. Stimulus's plural accessor keeps every copy in lockstep; each
    // element carries its own data-idle-label since dataset reads are
    // per-element.
    for (const button of this.submitButtonTargets) {
      button.disabled = count === 0
      button.textContent = count === 0 ? button.dataset.idleLabel : `Submit ${this._editLabel(count)}`
    }
    if (this.hasRevertButtonTarget) this.revertButtonTarget.disabled = count === 0
    if (this.hasPendingCountTarget) {
      this.pendingCountTarget.textContent = count === 0 ? "" : `${this._editLabel(count)} not submitted`
    }
  }

  _editLabel(count) {
    return `${count} ${count === 1 ? "edit" : "edits"}`
  }

  // Both buttons go down for the round trip either way; _syncPending brings
  // them back afterwards from the count that is left.
  _setSubmitting(inputs, submitting) {
    for (const button of this.submitButtonTargets) button.disabled = true
    if (this.hasRevertButtonTarget) this.revertButtonTarget.disabled = true
    for (const input of inputs) this._setSaving(input, submitting)
  }

  // Full-week recompute from the review page: fires the ECS batch run and
  // puts every team table into the recalculating state. The completion signal
  // is the same Turbo refresh broadcast as the per-team path.
  //
  // The button gets pending feedback the instant it's clicked, before the
  // fetch even starts — the ECS run_task call is a real AWS round trip (can
  // take a few seconds), and without this the button sits inert that whole
  // time, which reads as "did nothing." Success leaves it disabled: the
  // eventual Turbo refresh morph replaces this button with fresh server HTML
  // (never carrying the pending state), the same way REFRESHING_CLASS is
  // cleared on the team tables. Only the error path restores it manually,
  // since a failed kickoff means no morph is ever coming.
  async rerunAll(event) {
    event.preventDefault()
    await this._rerun({ button: event.submitter, team: null })
  }

  // Same run, scoped to one team via the ProjectionRunnerService FILTER_TEAM
  // override -- no navigation, no form, matching rerunAll's in-place UX
  // instead of the old new_nfl_projection_path form-and-redirect flow.
  async rerunTeam(event) {
    await this._rerun({ button: event.currentTarget, team: event.params.team })
  }

  async _rerun({ button, team }) {
    this._setRerunPending(button, true)
    this._announce(team ? `Starting projections run for ${team}…` : "Starting full projections run…")

    try {
      const response = await fetch(this.rerunUrlValue, {
        method: "POST",
        headers: { "Content-Type": "application/json", "Accept": "application/json" },
        body: JSON.stringify({ season: this.seasonValue, week: this.weekValue, team, ...this._csrfParam() }),
      })
      const data = await response.json().catch(() => ({}))
      if (!response.ok || !data.ok) throw new Error(data.errors?.join(", ") || `rerun failed (${response.status})`)
      this._markRefreshing(team ? (table) => table.dataset.team === team : () => true)
      this._announce(
        team
          ? `Projections run started for ${team} — values will update when it finishes`
          : "Full projections run started — all values will update when it finishes",
      )
    } catch (error) {
      this._setRerunPending(button, false)
      this._announce(`Error starting projections run: ${error.message}`)
    }
  }

  _setRerunPending(button, pending) {
    if (!button) return
    button.disabled = pending
    if (pending) {
      button.dataset.originalText ??= button.textContent
      button.textContent = "Starting run…"
    } else if (button.dataset.originalText) {
      button.textContent = button.dataset.originalText
    }
  }

  // Disables the matching team tables until recomputed projections arrive.
  // The Turbo refresh broadcast morphs the page from fresh server HTML, which
  // never carries the refreshing class — that morph IS the unlock.
  _markRefreshing(matches) {
    for (const table of this.teamTableTargets) {
      if (!matches(table)) continue
      table.classList.add(this.refreshingClass)
      for (const control of table.querySelectorAll(".proj-input, .proj-select")) {
        control.disabled = true
      }
    }
  }

  // Escape on a cell: back to the saved value, and the staged edit (if any)
  // goes with it.
  revert(event) {
    const { field, playerId } = event.params
    const key = this._key(playerId, field)
    this._unstage(this._pending.get(key) ?? { key, id: event.target.id, field, playerId })
    this._syncPending()
  }

  async _patch(url, fields) {
    const response = await fetch(url, {
      method: "PATCH",
      headers: { "Content-Type": "application/json", "Accept": "application/json" },
      body: JSON.stringify({ season: this.seasonValue, week: this.weekValue, ...fields, ...this._csrfParam() }),
    })
    const data = await response.json().catch(() => ({}))
    if (!response.ok || !data.ok) {
      throw new Error(data.errors?.join(", ") || `submit failed (${response.status})`)
    }
    return data
  }

  // CloudFront's origin-request policy only forwards an explicit header
  // whitelist to Rails (ops/terraform/modules/cdn/main.tf) -- X-CSRF-Token
  // isn't on it, so a header-only token silently never arrives at the
  // origin and every request here 422s with InvalidAuthenticityToken
  // (confirmed live via a temporary diagnostic: origin/host/scheme all
  // matched, only the header was missing). Sending it as a body param
  // instead sidesteps the CDN policy entirely -- Rails' CSRF check reads
  // params[:authenticity_token] natively, same as any HTML form post.
  _csrfParam() {
    return { authenticity_token: document.querySelector('meta[name="csrf-token"]')?.content }
  }

  _applySaved(input, field, data) {
    if (field === "admin_injured") {
      input.closest("tr").classList.toggle(this.zeroedClass, data.value === "OUT")
    } else if (data.value === null) {
      // Override cleared — show the model value again.
      input.classList.remove(this.overriddenClass)
      delete input.dataset.override
      input.value = data.effective === null ? "" : this._display(data.effective)
    } else {
      input.classList.add(this.overriddenClass)
      input.dataset.override = "true"
    }
    input.dataset.lastValue = input.value

    if (field === this.pprFieldValue) this._toggleInputLock(input, data.value !== null)
  }

  // Every other numeric input in the row locks while Projection carries a
  // stored override — editing an input that no longer affects the displayed
  // outcome would be misleading.
  _toggleInputLock(pprInput, locked) {
    for (const sibling of pprInput.closest("tr").querySelectorAll(".proj-input")) {
      if (sibling === pprInput) continue
      sibling.disabled = locked
      sibling.closest("[data-column]")?.classList.toggle(this.pprLockedClass, locked)
    }
  }

  // Recompute the column sums an edit affects: one column for a numeric edit,
  // every column when the injury status changes (OUT zeroes the whole row).
  _refreshTotals(input, field) {
    const table = input.closest("table")
    if (!table) return

    for (const attr of this._affectedAttrs(table, input, field)) this._recalcColumn(table, attr)
  }

  // Columns an edit invalidates: the edited one for a numeric edit, every column
  // when the injury status changes (OUT zeroes the whole row).
  _affectedAttrs(table, input, field) {
    return field === "admin_injured"
      ? Array.from(table.querySelectorAll("tfoot [data-total-column]"), (cell) => cell.dataset.totalColumn)
      : [input.closest("[data-column]")?.dataset.column].filter(Boolean)
  }

  // A market cell compares the book's line against the player's projection, so
  // the same columns an edit invalidates for the totals it also re-decides here.
  _refreshMarket(input, field, playerId) {
    const table = input.closest("table")
    const marketRow = table?.querySelector(`[data-market-row="${playerId}"]`)
    if (!marketRow) return

    const playerRow = input.closest("tr")
    for (const attr of this._affectedAttrs(table, input, field)) {
      // [data-market-line] is what makes this safe with no special case: the
      // server omits that attribute on a line it refused to compare (a yes/no
      // threshold rather than a total), so those cells are simply not selected
      // and the client can never tint or count one the server would not.
      const cell = marketRow.querySelector(`[data-market-column="${attr}"][data-market-line]`)
      if (cell) this._markMarketEdge(cell, playerRow, attr)
    }
    this._refreshMarketCount(table)
  }

  _markMarketEdge(cell, playerRow, attr) {
    const projection = this._cellProjection(playerRow.querySelector(`[data-column="${attr}"]`))
    const line = Number.parseFloat(cell.dataset.marketLine)
    const edge = this._marketEdge(projection, line)

    for (const [name, className] of Object.entries(MARKET_EDGE_CLASSES)) {
      cell.classList.toggle(className, edge === name)
    }
    cell.title = this._marketTitle(cell, projection, line)
  }

  // Mirrors MarketRow#cell_title: the book/market/line half is stamped on the
  // cell, only our number and the gap change as the projection is edited.
  _marketTitle(cell, projection, line) {
    const summary = cell.dataset.marketTitle
    const gap = this._differenceLabel(projection, line)
    return gap ? `${summary} · proj ${this._display(projection)} (${gap})` : summary
  }

  _differenceLabel(projection, line) {
    const diff = this._relativeDiff(projection, line)
    if (diff === null) return null
    return `${diff >= 0 ? "+" : ""}${(diff * 100).toFixed(1)}%`
  }

  // The count is read back off the rendered edge classes rather than recomputed
  // from the lines, so it can only ever agree with what the tints show — and
  // with the server's count, which is the same set.
  _refreshMarketCount(table) {
    const value = table.querySelector(`[data-market-count] ${SUMMARY_VALUE_SELECTOR}`)
    if (!value) return

    const selector = Object.values(MARKET_EDGE_CLASSES).map((name) => `.${name}`).join(", ")
    value.textContent = String(table.querySelectorAll(selector).length)
  }

  // The sidebar re-ranks off this; `projection` is the row's effective PPR
  // value, read the same way the totals read any other cell.
  _notifySaved(input, field, playerId) {
    const projection = this._cellValue(input.closest("tr").querySelector(`[data-column="${PPR_COLUMN}"]`))
    this.dispatch("saved", { detail: { playerId, field, projection } })
  }

  _recalcColumn(table, attr) {
    let teamTotal = 0
    for (const tbody of table.tBodies) {
      const subtotal = this._columnSum(tbody, attr)
      teamTotal += subtotal
      this._setTotal(tbody.querySelector(`[data-total-column="${attr}"]`), subtotal)
    }
    const teamCell = table.querySelector(`tfoot [data-total-column="${attr}"]`)
    this._setTotal(teamCell, teamTotal)
    this._markDeviation(teamCell, teamTotal)

    const summaryCell = table.querySelector(`[data-summary-column="${attr}"] ${SUMMARY_VALUE_SELECTOR}`)
    if (summaryCell) summaryCell.textContent = String(Math.round(teamTotal * 100) / 100)
    if (RECONCILIATION_ATTRS.has(attr)) this._updateReconciliationWarning(table)
  }

  // Reads the just-updated tfoot team totals for the four reconciliation
  // columns (already authoritative — _recalcColumn wrote them above) and
  // toggles the caption warning. Mirrors NumberFormat.reconciles?/discrepancy?
  // server-side: symmetric >10% relative deviation, no signal when either
  // side is exactly 0.
  _updateReconciliationWarning(table) {
    const passYds = this._teamTotalFor(table, "model_value_passing_yards")
    const recYds = this._teamTotalFor(table, "model_value_receiving_yards")
    const passTd = this._teamTotalFor(table, "pred_passing_tds")
    const recTd = this._teamTotalFor(table, "pred_receiving_tds")
    const mismatched = !this._reconciles(passYds, recYds) || !this._reconciles(passTd, recTd)

    table.querySelector(".proj-grid__summary-warning")
      ?.classList.toggle(RECONCILIATION_WARNING_CLASS, mismatched)
  }

  _teamTotalFor(table, attr) {
    const value = Number.parseFloat(table.querySelector(`tfoot [data-total-column="${attr}"]`)?.textContent)
    return Number.isNaN(value) ? 0 : value
  }

  _reconciles(left, right) {
    return !this._discrepancy(left, right) && !this._discrepancy(right, left)
  }

  // Both server rules this file mirrors — NumberFormat.discrepancy? (>10% off a
  // reference) and NumberFormat.market_edge (>20% off a line) — are the same
  // relative comparison at different thresholds, so they share one ratio here
  // and cannot drift apart. A missing, zero or unknown reference gives no
  // signal, and neither does a blank projection.
  _relativeDiff(value, reference) {
    if (!reference || value === null || value === undefined || Number.isNaN(value)) return null
    return value / reference - 1
  }

  _discrepancy(value, reference) {
    const diff = this._relativeDiff(value, reference)
    return diff !== null && Math.abs(diff) > DISCREPANCY_THRESHOLD
  }

  _marketEdge(projection, line) {
    const diff = this._relativeDiff(projection, line)
    if (diff === null) return null
    if (diff > EDGE_THRESHOLD) return "over"
    return diff < -EDGE_THRESHOLD ? "under" : null
  }

  _columnSum(tbody, attr) {
    let sum = 0
    for (const cell of tbody.querySelectorAll(`[data-column="${attr}"]`)) {
      sum += this._cellValue(cell)
    }
    return sum
  }

  // Effective value a cell contributes to sums: 0 for a row previewing the
  // pipeline's OUT zeroing, otherwise the input's current value (every
  // numeric cell, including a locked one, hosts an input). Blank counts as 0.
  _cellValue(cell) {
    return this._cellProjection(cell) ?? 0
  }

  // Same value as a projection rather than as a summand: a blank cell is "no
  // projection at all" (null), not zero, so it is compared against no market
  // line — matching the server, where effective() is nil and market_edge nil.
  // An OUT row is different: its zeroes are a real prediction, so a book line
  // against them is a genuine "under".
  _cellProjection(cell) {
    if (!cell) return null
    if (cell.parentElement.classList.contains(this.zeroedClass)) return 0
    const input = cell.querySelector("input")
    // A blank input with a model value behind it can only be a staged CLEAR:
    // the server always renders a model value into the cell, so a blank one
    // it rendered has no model value at all. Preview the value the clear is
    // about to restore rather than reading the blank as "no projection".
    const raw = input?.value?.trim() === "" ? input.dataset.modelValue : input?.value
    if (!raw || raw.trim() === "") return null
    const value = Number.parseFloat(raw)
    return Number.isNaN(value) ? null : value
  }

  _setTotal(cell, sum) {
    if (cell) cell.textContent = String(Math.round(sum * 100) / 100)
  }

  // >10% off the team-level model volume — same rule as the server-rendered
  // deviation tint (NumberFormat.discrepancy?).
  _markDeviation(cell, total) {
    if (!cell || cell.dataset.modelValue === undefined) return
    const model = Number.parseFloat(cell.dataset.modelValue)
    if (Number.isNaN(model) || model === 0) return
    cell.classList.toggle(this.deviationClass, this._discrepancy(total, model))
  }

  _setSaving(input, saving) {
    // Stay disabled when the whole table just entered the recalculating
    // state — the submit's finally block must not re-enable the edited cell.
    const refreshing = input.closest("table")?.classList.contains(this.refreshingClass)
    input.disabled = saving || Boolean(refreshing)
    input.classList.toggle(this.savingClass, saving)
  }

  _announce(message) {
    this.statusTarget.textContent = message
  }

  _display(value) {
    if (value === null || value === undefined || value === "") return "none"
    return typeof value === "number" ? Math.round(value * 100) / 100 : value
  }
}

import { Controller } from "@hotwired/stimulus"

// Week-wide projection leaderboard beside the admin projection spreadsheet
// (Views::Admin::NFL::ProjectionReviews::Sidebar).
//
// Two jobs, both purely client-side:
//
// 1. Position filter (Overall / QB / RB / WR / TE). Filtering hides rows
//    rather than re-fetching, renumbers the visible ranks 1..N, and hides the
//    Pos column while a single position is selected — the column would carry
//    the same value on every row. The selection persists to localStorage and
//    is restored on connect, the same way projection_override_controller
//    restores the "Show player props" toggle: the Turbo refresh morph that
//    delivers recomputed projections re-renders this list from the server,
//    unfiltered and in server rank order.
//
// 2. Live re-ranking. projection_override_controller dispatches
//    `projection-override:saved` after every successful save, carrying the
//    player's now-effective PPR projection; this rewrites that row's value,
//    re-sorts the whole list by projection descending, and renumbers.
//
// Sorting touches ~500 rows on a full week, so it reads every row's value
// once into an array, sorts that, and re-appends the nodes through a single
// DocumentFragment — one reflow per save rather than one per row.
//
// CSS class names all arrive from Ruby via the Stimulus classes API.

const STORAGE_KEY = "projReviewSidebarPosition"
const OVERALL = ""

export default class extends Controller {
  static targets = ["body", "status", "filterButton"]
  static classes = ["active", "hiddenRow", "evenRow", "positionFiltered"]

  // A plain field rather than a Stimulus value: a value's changed callback
  // fires off the data-attribute MutationObserver, so it runs a microtask
  // after the click and the announcement could not name the row count the
  // same interaction just produced.
  position = OVERALL

  connect() {
    this.position = this._storedPosition()
    this._apply({ announce: false })

    // A refresh morph replaces these rows with fresh server HTML, which never
    // carries the filter — reapply it once the new list is in place.
    this._onTurboRender = () => this._apply({ announce: false })
    document.addEventListener("turbo:render", this._onTurboRender)

    // Listened for on window rather than the shared .proj-review wrapper: the
    // event bubbles from whichever input was edited, and window is the one
    // node guaranteed to still be there after a morph swaps the wrapper.
    this._onSaved = (event) => this._applySavedProjection(event.detail)
    window.addEventListener("projection-override:saved", this._onSaved)
  }

  disconnect() {
    document.removeEventListener("turbo:render", this._onTurboRender)
    window.removeEventListener("projection-override:saved", this._onSaved)
  }

  filter(event) {
    this.position = event.params.position ?? OVERALL
    this._store(this.position)
    this._apply({ announce: true })
  }

  // Rank renumbering is what makes the filter readable: an admin who picks WR
  // wants the WR board, not the overall ranks with gaps in them.
  _apply({ announce }) {
    if (!this.hasBodyTarget) return

    const position = this.position
    this.element.classList.toggle(this.positionFilteredClass, position !== OVERALL)
    this._syncButtons(position)

    let rank = 0
    for (const row of this._rows()) {
      const visible = position === OVERALL || row.dataset.position === position
      row.classList.toggle(this.hiddenRowClass, !visible)
      if (!visible) continue
      this._setRank(row, ++rank)
      // Striping has to follow the visible sequence, not DOM position: CSS
      // :nth-child(even) counts the filtered-out rows too and turns the
      // stripes into arbitrary bands.
      row.classList.toggle(this.evenRowClass, rank % 2 === 0)
    }
    if (announce) this._announce(position, rank)
  }

  _syncButtons(position) {
    for (const button of this.filterButtonTargets) {
      const active = (button.dataset.projectionSidebarPositionParam ?? OVERALL) === position
      button.classList.toggle(this.activeClass, active)
      button.setAttribute("aria-pressed", String(active))
    }
  }

  _applySavedProjection({ playerId, projection } = {}) {
    const row = this._rows().find((candidate) => candidate.dataset.playerId === playerId)
    if (!row) return

    const value = Number.parseFloat(projection)
    row.dataset.projection = Number.isNaN(value) ? "0" : String(value)
    const cell = row.querySelector("[data-sidebar-value]")
    if (cell) cell.textContent = Number.isNaN(value) ? "" : String(Math.round(value * 100) / 100)

    this._sort()
    this._apply({ announce: false })
  }

  _sort() {
    const ordered = this._rows().toSorted((left, right) =>
      this._projection(right) - this._projection(left) || this._name(left).localeCompare(this._name(right)))
    const fragment = document.createDocumentFragment()
    for (const row of ordered) fragment.append(row)
    this.bodyTarget.append(fragment)
  }

  _rows() {
    return Array.from(this.bodyTarget.querySelectorAll("[data-sidebar-row]"))
  }

  // Mirrors EffectiveRow.ranked's tie break, so a row edited into a tie sorts
  // where a reload would put it instead of at the end of the tie group.
  _name(row) {
    return row.querySelector("[data-sidebar-name]")?.textContent.trim() ?? ""
  }

  _projection(row) {
    const value = Number.parseFloat(row.dataset.projection)
    return Number.isNaN(value) ? 0 : value
  }

  _setRank(row, rank) {
    const cell = row.querySelector("[data-sidebar-rank]")
    if (cell) cell.textContent = String(rank)
  }

  _announce(position, count) {
    if (!this.hasStatusTarget) return
    const label = position === OVERALL ? "All positions" : position
    this.statusTarget.textContent = `${label} — ${count} ${count === 1 ? "player" : "players"}`
  }

  // localStorage throws outright in a browser configured to block site data,
  // and this is a convenience, not state the page depends on — a failure here
  // must not take the whole controller (and with it the filter) down.
  _storedPosition() {
    let stored
    try {
      stored = window.localStorage.getItem(STORAGE_KEY)
    } catch {
      return OVERALL
    }
    // Validated against the pills actually on the page: a stored position that
    // has since left the list would hide every row, with no pill active and no
    // way back except guessing "Overall".
    return this._offeredPositions().includes(stored) ? stored : OVERALL
  }

  _offeredPositions() {
    return this.filterButtonTargets.map((button) => button.dataset.projectionSidebarPositionParam ?? OVERALL)
  }

  _store(position) {
    try {
      window.localStorage.setItem(STORAGE_KEY, position)
    } catch {
      // Selection still applies for this page view; it just won't survive.
    }
  }
}

import { Controller } from "@hotwired/stimulus"

// Lets the ask-section prompt chips drive the chat demo, and keeps the
// chips' "live" styling synced to it in both directions:
//
// - Tapping a chip that carries a scene index restarts the demo phone at
//   that scene, per the design's "Tap a prompt above to change the
//   conversation."
// - The ai-chat-demo controller (the centre phone) dispatches
//   `ai-chat-demo:scene` whenever its scene changes -- on auto-advance and
//   on a chip-triggered jump alike -- and `sync` toggles the active class
//   on every chip (the marquee duplicates the list) whose scene index
//   matches. The two static-phone chips are marked always-active and never
//   get toggled off.
export default class extends Controller {
  static targets = ["chip"]
  static classes = ["active"]

  pick(event) {
    const index = Number(event.currentTarget.dataset.sceneIndex)
    if (Number.isNaN(index)) return

    const demoElement = this.element.querySelector('[data-controller~="ai-chat-demo"]')
    if (!demoElement) return

    const demo = this.application.getControllerForElementAndIdentifier(demoElement, "ai-chat-demo")
    if (demo) demo.showScene(index)
  }

  sync(event) {
    const index = event.detail.index

    this.chipTargets.forEach((chip) => {
      if (chip.dataset.alwaysActive === "true") return

      chip.classList.toggle(this.activeClass, Number(chip.dataset.sceneIndex) === index)
    })
  }
}

import { Controller } from "@hotwired/stimulus"
import { formatLocalDateTime } from "format_local_time"

// Replaces a <time datetime="..."> element's text with a relative label
// ("just now", "5 seconds ago", "30 minutes ago") that keeps ticking on its
// own, without any new data from the server -- the live odds board's
// "Updated" stamp exists specifically to prove a live stream is behind it
// (BoardTable's own docstring), and an absolute timestamp alone doesn't
// visibly move between updates the way a ticking relative label does.
//
// Falls back to an absolute local date/time (same format
// local_time_controller.js renders) once the gap passes HOUR_THRESHOLD_MS --
// "3 hours ago" is less useful than just seeing when it actually was.
//
// Watches the datetime attribute itself (a MutationObserver, same pattern as
// sync_status_controller.js) rather than only formatting once on connect:
// Turbo::StreamsChannel.broadcast_refresh_to morphs this element in place
// when fresh data lands, so connect() only ever fires once per page load --
// every subsequent update is an attribute mutation, not a new controller
// instance, and each one needs to reset which moment "ago" is measured from.
const SECOND_MS = 1_000
const MINUTE_MS = 60 * SECOND_MS
const HOUR_MS = 60 * MINUTE_MS
const HOUR_THRESHOLD_MS = HOUR_MS
const JUST_NOW_THRESHOLD_MS = 5 * SECOND_MS

export default class extends Controller {
  // Opt-in compact vocabulary ("20s ago") for callers whose layout has no
  // room for "20 seconds ago" -- the PredictionMarkets+ feed-freshness
  // dropdown. Off by default, so the live odds board's "Updated" stamp keeps
  // rendering exactly as it did.
  static values = { compact: Boolean }

  connect() {
    this.observer = new MutationObserver(() => this.reset())
    this.observer.observe(this.element, { attributes: true, attributeFilter: ["datetime"] })
    this.reset()
  }

  disconnect() {
    this.observer?.disconnect()
    this._clearTimer()
  }

  reset() {
    const raw = this.element.getAttribute("datetime")
    this._date = raw ? new Date(raw) : null
    if (this._date && isNaN(this._date)) this._date = null
    this._clearTimer()
    this._tick()
  }

  _tick() {
    if (!this._date) return

    const elapsedMs = Date.now() - this._date.getTime()
    // Compact mode never falls back to an absolute stamp: this dropdown's
    // whole job is saying how long ago a feed wrote, and an hours-old feed
    // there is an alarm state that stays most legible as an age.
    if (this.compactValue) {
      this.element.textContent = compactLabel(Math.max(elapsedMs, 0))
      this._timer = setTimeout(() => this._tick(), SECOND_MS)
      return
    }

    if (elapsedMs < 0 || elapsedMs >= HOUR_THRESHOLD_MS) {
      this.element.textContent = formatLocalDateTime(this._date)
      return
    }

    this.element.textContent = relativeLabel(elapsedMs)
    this._timer = setTimeout(() => this._tick(), SECOND_MS)
  }

  _clearTimer() {
    if (this._timer) clearTimeout(this._timer)
    this._timer = null
  }
}

function relativeLabel(elapsedMs) {
  if (elapsedMs < JUST_NOW_THRESHOLD_MS) return "just now"

  const seconds = Math.floor(elapsedMs / SECOND_MS)
  if (seconds < 60) return `${seconds} second${seconds === 1 ? "" : "s"} ago`

  const minutes = Math.floor(elapsedMs / MINUTE_MS)
  return `${minutes} minute${minutes === 1 ? "" : "s"} ago`
}

// Mirrors Polymarket::VenueFreshness#ago_label -- same thresholds, same
// rounding -- so the server's first paint and the ticking client label speak
// one vocabulary instead of disagreeing on the same instant.
function compactLabel(elapsedMs) {
  // Each threshold tests the raw age and only the displayed number is rounded,
  // exactly as the Ruby does. Rounding first and then comparing moves the
  // boundaries: a 59.6s age reads "60s ago" server-side but would fall into
  // the minutes bucket here and flip to "1m ago" the moment Stimulus connects.
  const seconds = elapsedMs / SECOND_MS
  if (seconds < 60) return `${Math.round(seconds)}s ago`
  if (seconds < 3600) return `${Math.round(elapsedMs / MINUTE_MS)}m ago`

  return `${Math.round(elapsedMs / HOUR_MS)}h ago`
}

// Keeps a Stimulus value attribute intact across Turbo's page-refresh morph.
//
// data-turbo-permanent only protects an element's own subtree from being
// touched by idiomorph's diffing -- it does nothing for a controller value
// that lives on a DIFFERENT (non-permanent) ancestor, which is exactly the
// odds-format/price-filter shape: the toggle buttons could be marked
// permanent, but the value driving them (data-odds-format-format-value /
// data-price-filter-sign-value) lives on the wrapper that also contains the
// board table, which can never be made permanent since it needs fresh
// server data on every refresh.
//
// Whether the server renders the value attribute or not, a broadcast morph
// resets it to the server's idea (strips it when absent from the incoming
// HTML, rewrites it when the server renders a default -- which the odds
// boards now do, so first paint can show the right pressed button). Either
// way the visitor's client-only choice is gone after the morph.
//
// This restores the value after the morph instead: snapshot it right before
// the wrapper element morphs, and if it came back different (i.e. got reset),
// write the snapshot back.
//
// Restoring the attribute is NOT enough to fix the buttons, though -- that's
// what `apply` is for. Stimulus's value observer batches DOM mutations and
// compares the attribute's final value against the last one it recorded, so
// the morph's server-value write and this restore cancel out inside one
// batch: net change nothing, valueChanged never fires. Meanwhile idiomorph
// has separately rewritten the toggle BUTTONS' aria-pressed from the
// server's HTML (the server presses its default), leaving the control
// claiming a format the board is not in. Confirmed live on the deployed
// OddsBoard: board showing American prices under a pressed Cents button
// after every refresh morph. So after every morph -- restored or not, since
// the buttons get clobbered even when the value never drifted -- `apply`
// re-syncs the dependent UI from the (correct) current value, exactly what
// the controller's own valueChanged callback would have done.
//
// The restore listens on the DOCUMENT for turbo:morph, not on the element for
// turbo:morph-element, and the difference is the whole bug this used to have.
// The per-element event fires before the element's own descendants are morphed
// (the same fact market_search_controller.js documents). So restoring there
// put the value back, Stimulus queued its valueChanged callback -- and then
// idiomorph reached the toggle buttons inside and reset their aria-pressed
// from the server's HTML. The board's numbers followed the restored value
// while the buttons showed the server default, so the control claimed a format
// the page was not in. Worse, Stimulus's value callback is asynchronous, so it
// sometimes landed after the buttons were morphed and sometimes before --
// which is why the same board would sometimes reset only the buttons and
// sometimes reset everything. turbo:morph fires once, after the entire page
// has morphed, so nothing can overwrite the restore afterwards.
//
// The snapshot stays on the element's own before-event: that fires while the
// value is still the visitor's, which is exactly what needs capturing.
export function restoreValueAfterMorph(element, get, set, apply) {
  let snapshot

  function onBeforeMorph(event) {
    if (event.target === element) snapshot = get()
  }

  function onMorph() {
    if (snapshot === undefined) return
    if (get() !== snapshot) set(snapshot)
    apply()
  }

  element.addEventListener("turbo:before-morph-element", onBeforeMorph)
  document.addEventListener("turbo:morph", onMorph)

  return () => {
    element.removeEventListener("turbo:before-morph-element", onBeforeMorph)
    document.removeEventListener("turbo:morph", onMorph)
  }
}

import { Controller } from "@hotwired/stimulus";

// Preserves "return to where I was" behavior for login/signup CTAs without
// ever rendering a destination-specific `?return_to=` query param in a
// static, crawlable <a href> (see RDM-01/03 — that param alone accounted for
// tens of thousands of junk URLs discovered by crawlers).
//
// Capture side: a login/signup link uses a plain href (e.g. "/login") and
// calls #capture on click, stashing the current location in sessionStorage.
//
// Restore side: the destination page's form wraps this same controller and
// tags its hidden "return_to" field as the `field` target. On connect, if the
// field is still blank (no server-echoed value from a failed-submission
// retry), it's filled in from sessionStorage so the normal POST body -> Rails
// session[:return_to] flow (ApplicationController#store_return_location)
// works exactly as it did when the value arrived via query string.
export const STORAGE_KEY = "sr-return-to";

export default class extends Controller {
  static targets = ["field"];

  connect() {
    if (!this.hasFieldTarget || this.fieldTarget.value) return;

    const stored = sessionStorage.getItem(STORAGE_KEY);
    if (stored) this.fieldTarget.value = stored;
  }

  capture() {
    sessionStorage.setItem(STORAGE_KEY, window.location.pathname + window.location.search);
  }
}

import { Controller } from "@hotwired/stimulus";

// Copies Rewardful's referral id into the plan form's hidden field, so
// CheckoutController#create can forward it as the Checkout Session's
// client_reference_id -- which is how Rewardful attributes the sale.
//
// The value exists only client-side: Rewardful's script resolves it from the
// `?via=` token stored when the visitor hit the co-branded landing page, so the
// server cannot know it at render time. Structurally the same as
// return_to_controller.js, which fills its hidden field from sessionStorage.
//
// `rewardful("ready", ...)` is the provider's own callback for "the async
// script has resolved a referral"; reading Rewardful.referral directly on
// connect would race it and usually read undefined.
//
// Silent no-op when window.rewardful is absent. The script is not gated on the
// affiliate_program flag, so this is not the flag-off path -- with the flag off
// this controller is never attached in the first place (see
// Views::Checkout::Form#form_controllers). It is the no-API-key path
// (RewardfulConfig.enabled?) and the not-yet-loaded path, and in both there is
// nothing to attribute.
export default class extends Controller {
  static targets = ["field"];

  connect() {
    if (!this.hasFieldTarget || typeof window.rewardful !== "function") return;

    window.rewardful("ready", () => {
      const referral = window.Rewardful && window.Rewardful.referral;
      if (referral) this.fieldTarget.value = referral;
    });
  }
}

import { Controller } from "@hotwired/stimulus"

// Keeps the URL hash in sync with the child section currently in view, so a
// copied or reloaded URL restores the reader's place. The "current" section is
// the one whose top has crossed the line just below the sticky navigator
// (read from the --dc-hub-nav-clearance property the sticky-clearance
// controller publishes) — the same line anchor jumps land on, so the hash
// never flips to the previous section right after a jump. On connect it
// re-scrolls to the hash target: the browser's native anchor scroll runs
// before the clearance is measured, so the landing would otherwise sit under
// the expanded panel.
export default class extends Controller {
  connect() {
    this.sections = Array.from(this.element.querySelectorAll(":scope > [id]"))
    this.onScroll = () => this.#queueSpy()
    addEventListener("scroll", this.onScroll, { passive: true })
    this.#restoreAnchor()
  }

  disconnect() {
    removeEventListener("scroll", this.onScroll)
  }

  #queueSpy() {
    if (this.ticking) return

    this.ticking = true
    requestAnimationFrame(() => {
      this.ticking = false
      this.#spy()
    })
  }

  #restoreAnchor() {
    const slug = decodeURIComponent(window.location.hash.slice(1))
    const target = slug && this.sections.find((section) => section.id === slug)
    if (!target) return

    requestAnimationFrame(() => target.scrollIntoView())
  }

  #spy() {
    const clearance = parseFloat(getComputedStyle(this.element).getPropertyValue("--dc-hub-nav-clearance")) || 0
    const line = clearance + 13
    const current = this.sections.findLast((section) => section.getBoundingClientRect().top <= line)
    const hash = current ? `#${current.id}` : ""
    if (window.location.hash === hash) return

    history.replaceState(history.state, "", `${window.location.pathname}${window.location.search}${hash}`)
  }
}

import { Controller } from "@hotwired/stimulus"

// Toggles a set of "overflow" rows that are present in the DOM but hidden
// until the visitor opts in — the "Show all N / Show fewer" affordance in the
// stat accordion's Base Stats tier. No server round-trip; the rows ship with
// the page and are revealed client-side.
export default class extends Controller {
  static targets = ["overflow", "label"]
  static classes = ["hidden"]
  static values = { collapsedLabel: String, expandedLabel: String }

  toggle() {
    const willExpand = this.#collapsed

    for (const overflow of this.overflowTargets) {
      overflow.classList.toggle(this.hiddenClass, !willExpand)
    }

    if (this.hasLabelTarget) {
      this.labelTarget.textContent = willExpand
        ? this.expandedLabelValue
        : this.collapsedLabelValue
      this.labelTarget.setAttribute("aria-expanded", willExpand ? "true" : "false")
    }
  }

  get #collapsed() {
    return this.overflowTargets.some((overflow) =>
      overflow.classList.contains(this.hiddenClass),
    )
  }
}

import { Controller } from "@hotwired/stimulus"

// Scrolls the sidebar on load so the selected category's header sits at the
// sidebar's top edge (clamped to the max scroll when there isn't enough
// content below to fill the sidebar, e.g. the last category in the list).
// Pinning the category header, rather than centering the active stat row,
// keeps the whole expanded category visible instead of cutting off sibling
// rows above it (STAT-1142 condensed sections open to the current category).
export default class extends Controller {
  connect() {
    const category = this.element.querySelector(
      ".stat-accordion-list__trigger[aria-expanded='true']:not(.stat-accordion-list__trigger--nested)",
    )
    if (!category) return

    const sidebar = this.element
    const maxScroll = sidebar.scrollHeight - sidebar.clientHeight
    const scrollTarget = Math.min(category.offsetTop - sidebar.offsetTop, maxScroll)

    sidebar.scrollTo({ top: Math.max(scrollTarget, 0), behavior: "smooth" })
  }
}

import { Controller } from "@hotwired/stimulus";

// DataTable sort headers render as buttons rather than real <a href> anchors
// so `?sort_field=`/`?sort_order=` variants are never discoverable via static
// HTML (see RDM-02 — crawlers found 32,852 of these). Clicking still performs
// the same Turbo Frame navigation a link would have, just driven by JS.
export default class extends Controller {
  static values = {
    url: String,
    frame: String,
  };

  visit() {
    Turbo.visit(this.urlValue, { frame: this.frameValue });
  }
}

import { Controller } from "@hotwired/stimulus";
import { dispatchAnalytics } from "dispatch_analytics";

// Live, client-side player search shared by StatBuilder+ and MatchupIQ+ (see
// Components::Stats::PlayerPicker/ActivePlayersDataIsland -- this controller
// name is kept as-is on both pages, a purely internal detail not worth
// renaming). On connect, reads the active-player list preloaded by each
// page's own view (a JSON data island rendered once, outside the turbo frame
// this controller's root element lives inside -- so it survives every
// in-frame swap without ever being re-fetched) and filters it in memory on
// every keystroke -- no network round-trip, no debounce needed.
//
// Team logos are shipped once per team (not per player) as <template>s built
// server-side from the real UI::TeamLogo component; rows are built here by
// cloning the matching template rather than re-implementing icon
// resolution/fallback logic in JS.
//
// The dropdown/trending markup PlayerPicker renders server-side is only the
// SSR fallback for the first paint and ?q= deep-links -- every keystroke
// after that replaces the "results" target's contents directly. Selecting a
// result is still a plain `turbo_frame: "_top"` link (a full Turbo Drive
// visit, unchanged) -- only the search-as-you-type path skips the server.
const DATA_ISLAND_ID = "stat-builder-active-players";
const TEAM_LOGOS_ID = "stat-builder-team-logos";

export default class extends Controller {
  static targets = ["input", "results"];
  static values = {
    resultLimit: { type: Number, default: 8 },
    // Each tool's own player-scoped route ("/nfl/advanced/players/stat-builder",
    // "/nfl/advanced/players/matchup-iq") -- mirrors PlayerPicker#player_path
    // on the Ruby side, which the SSR fallback rows already use.
    searchPath: { type: String, default: "/nfl/advanced/players/stat-builder" },
    // The four values below are all opt-in -- the primary PlayerPicker sets
    // none of them, so its behavior is unchanged. They exist for the "add a
    // player to compare" search (Components::StatBuilder::ComparePicker):
    //   position     -- restrict matches to one position (compare is same-position only)
    //   excludeIds   -- CSV of custom_ids to hide (the primary + already-added players)
    //   hrefTemplate -- a full URL carrying "__ID__" where the picked player's
    //                   id goes; when set, result rows link here instead of
    //                   "?player=" so the pick is *appended* to ?compare= (the
    //                   URL, with the current stats/weeks preserved, is built
    //                   server-side -- JS just fills the id)
    //   syncQuery    -- write ?q= into the URL on each keystroke; off for the
    //                   compare search so it doesn't fight the primary picker's own q
    position: { type: String, default: "" },
    excludeIds: { type: String, default: "" },
    hrefTemplate: { type: String, default: "" },
    syncQuery: { type: Boolean, default: true },
  };

  connect() {
    this.players = this.#loadPlayers();
    this.teamLogoTemplates = this.#loadTeamLogoTemplates();
    this.initialResultsHTML = this.hasResultsTarget ? this.resultsTarget.innerHTML : "";
  }

  search(event) {
    const query = event.target.value.trim();

    if (this.syncQueryValue) {
      const url = new URL(window.location.href);
      if (query === "") {
        url.searchParams.delete("q");
      } else {
        url.searchParams.set("q", query);
      }
      history.replaceState(history.state, "", url.toString());
    }

    this.#render(query);
  }

  #render(query) {
    if (!this.hasResultsTarget) return;

    if (query === "") {
      this.resultsTarget.innerHTML = this.initialResultsHTML;
      return;
    }

    this.resultsTarget.replaceChildren(this.#buildDropdown(query));
  }

  #buildDropdown(query) {
    const matches = this.#matches(query);

    const ul = document.createElement("ul");
    ul.className = "player-picker__dropdown";
    ul.setAttribute("role", "listbox");
    ul.setAttribute("aria-label", "Player search results");
    ul.setAttribute("aria-live", "polite");

    if (matches.length === 0) {
      const li = document.createElement("li");
      li.className = "player-picker__empty";
      li.textContent = "No players found";
      ul.appendChild(li);
      return ul;
    }

    for (const player of matches) ul.appendChild(this.#buildResultRow(query, player));
    return ul;
  }

  #matches(query) {
    const lower = query.toLowerCase();
    const position = this.positionValue;
    const excluded = this.#excludedIds();
    const matches = [];
    for (const player of this.players) {
      if (position && player.position !== position) continue;
      if (excluded.has(player.custom_id)) continue;
      if (player.full_name.toLowerCase().includes(lower)) {
        matches.push(player);
        if (matches.length === this.resultLimitValue) break;
      }
    }
    return matches;
  }

  #excludedIds() {
    return new Set(
      this.excludeIdsValue
        .split(",")
        .map(id => id.trim())
        .filter(Boolean),
    );
  }

  #buildResultRow(query, player) {
    const li = document.createElement("li");
    li.setAttribute("role", "option");

    const a = document.createElement("a");
    a.href = this.hrefTemplateValue
      ? this.hrefTemplateValue.replace("__ID__", encodeURIComponent(player.custom_id))
      : `${this.searchPathValue}?player=${encodeURIComponent(player.custom_id)}`;
    a.className = "player-picker__result";
    a.dataset.turboFrame = "_top";

    // A hrefTemplate is only set for the "add a player to compare" search
    // (see ComparePicker), where picking a result appends them to ?compare= --
    // so that pick is a comparison add. The primary picker (no template) is a
    // plain player selection.
    a.addEventListener("click", () => {
      const name = this.hrefTemplateValue ? "comparison_add_player" : "player_search_select";
      dispatchAnalytics(name, { player: player.custom_id });
    });

    const logo = this.teamLogoTemplates.get(player.team_abbreviation);
    if (logo) a.appendChild(logo.content.cloneNode(true));

    const name = document.createElement("span");
    name.className = "player-picker__result-name";
    this.#appendHighlightedName(name, player.full_name, query);
    a.appendChild(name);

    const position = document.createElement("span");
    position.className = "player-picker__result-pos";
    position.textContent = player.position;
    a.appendChild(position);

    li.appendChild(a);
    return li;
  }

  // Mirrors PlayerPicker#highlighted_name: splits the name around the first
  // case-insensitive match and wraps it in an accent span.
  #appendHighlightedName(parent, name, query) {
    const index = name.toLowerCase().indexOf(query.toLowerCase());
    if (index === -1) {
      parent.appendChild(document.createTextNode(name));
      return;
    }

    const finish = index + query.length;
    if (index > 0) parent.appendChild(document.createTextNode(name.slice(0, index)));

    const match = document.createElement("span");
    match.className = "player-picker__match";
    match.textContent = name.slice(index, finish);
    parent.appendChild(match);

    if (finish < name.length) parent.appendChild(document.createTextNode(name.slice(finish)));
  }

  #loadPlayers() {
    const element = document.getElementById(DATA_ISLAND_ID);
    if (!element) return [];

    try {
      return JSON.parse(element.textContent);
    } catch {
      return [];
    }
  }

  #loadTeamLogoTemplates() {
    const map = new Map();
    const container = document.getElementById(TEAM_LOGOS_ID);
    if (!container) return map;

    container.querySelectorAll("template[data-team]").forEach(template => {
      map.set(template.dataset.team, template);
    });
    return map;
  }
}

import { Controller } from "@hotwired/stimulus"
import { dispatchAnalytics } from "dispatch_analytics"

const MIN_QUERY_LENGTH = 3
const REMOTE_MIN_QUERY_LENGTH = 2
const MAX_PER_SPORT = 6
// Short debounce: the endpoint answers from an in-memory cache in ~20ms, so
// this only coalesces rapid keystrokes rather than protecting a slow query.
const DEBOUNCE_MS = 150
const DEFAULT_SPORT = "NFL"

// Fixed, ordered list of overlay result sections. Each section is rendered only
// when it has matching entries, but the order here is always preserved:
//   NFL stat-player, NFL stat-team, NFL players,
//   NBA stat-player, NBA stat-team, NBA players,
//   CFB stat-player, CFB stat-team.
// The "kind" selects which bucket a section draws from (stat items filtered by
// stat_type, or remotely fetched players). CFB has no player section: there are
// no CFB player pages yet, so /search/players never returns CFB players.
const SECTIONS = [
  { sport: "NFL", kind: "stats-player" },
  { sport: "NFL", kind: "stats-team" },
  { sport: "NFL", kind: "player" },
  { sport: "NBA", kind: "stats-player" },
  { sport: "NBA", kind: "stats-team" },
  { sport: "NBA", kind: "player" },
  { sport: "CFB", kind: "stats-player" },
  { sport: "CFB", kind: "stats-team" },
]

// Every `UI::StatSearchBar` instance on a page (mobile navbar, desktop navbar,
// sidebar) shares this one JSON data island instead of each carrying its own
// copy of the (large) stat list -- see `Stats::StatSearchIndex`.
const ITEMS_ELEMENT_ID = "stat-search-items"

export default class extends Controller {
  static targets = ["input", "results", "statIcon", "loading"]
  static values = { playersUrl: String, searchStats: { type: Boolean, default: true } }
  static classes = ["sport", "empty", "open", "bodyLock"]

  connect() {
    // With stat search off (navbar player-only mode), an empty item list makes
    // every stat/menu section come up empty, so only player sections render.
    this.items = this.searchStatsValue ? this.parseItems() : []
    this.statMatches = []
    this.fetchedPlayers = []
    this.searchTimeout = null
    this.abortController = null
    this.highlightQuery = ""
  }

  disconnect() {
    if (this.searchTimeout) clearTimeout(this.searchTimeout)
    if (this.abortController) this.abortController.abort()
    if (this.hasBodyLockClass) document.body.classList.remove(this.bodyLockClass)
  }

  // ── Overlay (mobile command palette) ──

  open() {
    if (this.hasOpenClass) this.element.classList.add(this.openClass)
    if (this.hasBodyLockClass) document.body.classList.add(this.bodyLockClass)
    requestAnimationFrame(() => this.inputTarget.focus())
  }

  closeOverlay() {
    if (this.hasOpenClass) this.element.classList.remove(this.openClass)
    if (this.hasBodyLockClass) document.body.classList.remove(this.bodyLockClass)
    this.inputTarget.value = ""
    this.resetRemote()
    this.hideResults()
    this.inputTarget.blur()
  }

  // ── Search entry point ──

  search() {
    if (this.hasPlayersUrlValue) {
      this.unifiedSearch()
    } else {
      this.statOnlySearch()
    }
  }

  close() {
    this.hideResults()
  }

  closeOnBlur() {
    setTimeout(() => {
      if (!this.element.contains(document.activeElement)) {
        this.hideResults()
      }
    }, 0)
  }

  // ── Stat-pages-only search (sidebar inline) ──

  statOnlySearch() {
    const query = this.inputTarget.value.trim().toLowerCase()

    if (query.length < MIN_QUERY_LENGTH) {
      this.hideResults()
      return
    }

    const matches = this.matchStats(query)
    const grouped = this.groupBySport(matches)
    const total = matches.length

    dispatchAnalytics("stat_search", {
      search_term: this.inputTarget.value.trim(),
      results_count: total,
    })

    this.resultsTarget.replaceChildren()

    if (total === 0) {
      this.resultsTarget.append(this.emptyStateItem())
      this.resultsTarget.hidden = false
      return
    }

    this.appendStatGroups(grouped)
    this.resultsTarget.hidden = false
  }

  // ── Unified search (overlay: stat pages + players + teams) ──

  unifiedSearch() {
    if (this.searchTimeout) clearTimeout(this.searchTimeout)

    const query = this.inputTarget.value.trim()

    if (query.length < REMOTE_MIN_QUERY_LENGTH) {
      this.resetRemote()
      this.hideResults()
      return
    }

    // Stat-page filtering stays client-side and instant. The previous fetch's
    // players are narrowed to the new query rather than cleared, so matching
    // rows stay on screen (no blink) while the authoritative fetch is in
    // flight — every row shown always matches the current query text.
    const term = query.toLowerCase()
    this.statMatches = this.matchStats(term)
    this.fetchedPlayers = this.fetchedPlayers.filter((player) =>
      (player.name || "").toLowerCase().includes(term)
    )

    this.renderUnified(query, { final: false })

    this.searchTimeout = setTimeout(() => this.fetchRemote(query), DEBOUNCE_MS)
  }

  async fetchRemote(query) {
    if (this.abortController) this.abortController.abort()
    this.abortController = new AbortController()

    // The spinner reflects only the remote /search/players request, never the
    // instant client-side stat filter.
    this.showLoading()

    try {
      const response = await fetch(
        `${this.playersUrlValue}?q=${encodeURIComponent(query)}`,
        { signal: this.abortController.signal }
      )
      const data = await response.json()
      this.fetchedPlayers = data.players || []
      this.renderUnified(query, { final: true })
      this.hideLoading()
    } catch (error) {
      // An AbortError means a newer request is already in flight (rapid typing),
      // so leave the spinner alone — that fetch owns it and will clear it.
      if (error.name !== "AbortError") {
        this.fetchedPlayers = []
        this.renderUnified(query, { final: true })
        this.hideLoading()
      }
    }
  }

  showLoading() {
    if (this.hasLoadingTarget) this.loadingTarget.hidden = false
  }

  hideLoading() {
    if (this.hasLoadingTarget) this.loadingTarget.hidden = true
  }

  renderUnified(query, { final }) {
    this.resultsTarget.replaceChildren()
    this.highlightQuery = query.trim()

    // Sections render in the fixed SECTIONS order. Each is only appended when it
    // has matching entries, so empty sections (and empty section headers) never
    // appear. Real team-name search results are not part of SECTIONS and are
    // never surfaced.
    let total = 0
    for (const section of SECTIONS) {
      total += this.appendSection(section)
    }
    total += this.appendMenuSection()

    if (final) {
      dispatchAnalytics("stat_search", { search_term: query, results_count: total })
    }

    if (total === 0) {
      // The empty state only appears once the remote fetch has resolved, so
      // it reflects both stat-page matches and fetched players/teams.
      if (final) {
        this.resultsTarget.append(this.emptyStateItem())
        this.resultsTarget.hidden = false
      } else {
        this.hideResults()
      }
      return
    }

    this.resultsTarget.hidden = false
  }

  // ── Rendering helpers ──

  matchStats(query) {
    if (query.length < MIN_QUERY_LENGTH) return []

    return this.items.filter((item) => this.searchText(item).includes(query))
  }

  appendStatGroups(grouped) {
    let count = 0

    for (const [sport, items] of grouped) {
      if (sport) this.resultsTarget.append(this.labelItem(sport))
      for (const item of items.slice(0, MAX_PER_SPORT)) {
        this.resultsTarget.append(this.resultItem(item))
      }
      count += items.length
    }

    return count
  }

  // Renders a single fixed section and returns the number of matched entries.
  // Empty sections render nothing (no header), preserving the "omit empty
  // sections" behaviour.
  appendSection({ sport, kind }) {
    const { entries, label, buildItem } = this.sectionData(sport, kind)

    if (entries.length === 0) return 0

    this.resultsTarget.append(this.labelItem(label))
    for (const entry of entries.slice(0, MAX_PER_SPORT)) {
      this.resultsTarget.append(buildItem(entry))
    }

    return entries.length
  }

  // General navigation items (Nav::Menus: StatBuilder+, Fantasy Rankings,
  // CoverageIQ, CFB, DFS, etc.) carry no sport or stat_type, so they fall
  // outside the fixed SECTIONS grid. They render — without a header — after the
  // stat/player sections, preserving the pre-STAT-1076 overlay behaviour where
  // sport-less menu matches appeared at the end of the results. Returns the
  // number of menu entries rendered.
  appendMenuSection() {
    const entries = this.statMatches.filter((item) => !item.stat_type)

    if (entries.length === 0) return 0

    for (const entry of entries.slice(0, MAX_PER_SPORT)) {
      this.resultsTarget.append(this.statItem(entry))
    }

    return entries.length
  }

  // Resolves the entries, header label, and row builder for a section. Stat
  // sections read "SPORT stats | player" / "SPORT stats | team"; fetched-player
  // sections read "SPORT | Player".
  sectionData(sport, kind) {
    switch (kind) {
      case "stats-player":
        return {
          entries: this.statEntries(sport, "player"),
          label: `${sport} stats | player`,
          buildItem: (entry) => this.statItem(entry),
        }
      case "stats-team":
        return {
          entries: this.statEntries(sport, "team"),
          label: `${sport} stats | team`,
          buildItem: (entry) => this.statItem(entry),
        }
      default:
        return {
          entries: this.entriesBySport(this.fetchedPlayers, sport),
          label: `${sport} | Player`,
          buildItem: (entry) => this.playerItem(entry),
        }
    }
  }

  statEntries(sport, statType) {
    return this.statMatches.filter(
      (item) => (item.sport || DEFAULT_SPORT) === sport && item.stat_type === statType
    )
  }

  entriesBySport(entries, sport) {
    return entries.filter((entry) => (entry.sport || DEFAULT_SPORT) === sport)
  }

  parseItems() {
    const source = document.getElementById(ITEMS_ELEMENT_ID)

    try {
      return JSON.parse(source?.textContent || "[]")
    } catch {
      return []
    }
  }

  // Match against the stat name only. Including the category or sport here
  // surfaced results with no visible (highlighted) match — e.g. "sco" matching
  // "Field Goals" via its "Scoring" category — which read as noise.
  searchText(item) {
    return (item.name || "").toLowerCase()
  }

  groupBySport(matches, defaultSport = "") {
    const map = new Map()

    for (const item of matches) {
      const key = item.sport || defaultSport
      if (!map.has(key)) map.set(key, [])
      map.get(key).push(item)
    }

    return map
  }

  labelItem(text) {
    const li = document.createElement("li")
    li.className = this.sportClass
    li.textContent = text
    return li
  }

  emptyStateItem() {
    const li = document.createElement("li")
    li.className = this.emptyClass
    li.textContent = `No results found matching '${this.inputTarget.value.trim()}'`
    return li
  }

  resultItem(item) {
    const li = document.createElement("li")
    const link = document.createElement("a")

    link.href = item.path
    link.textContent = item.name

    if (item.item_class) {
      li.classList.add(item.item_class)
      link.classList.add(item.item_class)
    }

    li.append(link)
    return li
  }

  // Stat result: chart icon + name (single line).
  statItem(item) {
    const li = document.createElement("li")
    const link = this.resultLink(item.path)

    if (item.item_class) {
      li.classList.add(item.item_class)
      link.classList.add(item.item_class)
    }

    link.append(this.statIconBox(), this.resultBody(item.name))
    li.append(link)
    return li
  }

  // Player result: team logo (avatar placeholder fallback) + name with the
  // team as a subtitle.
  playerItem(player) {
    const li = document.createElement("li")
    const link = this.resultLink(player.path)

    link.append(this.playerLeading(player), this.resultBody(player.name, player.team))
    li.append(link)
    return li
  }

  // Leading icon for a player row: the server-rendered team logo when present,
  // otherwise the first-letter avatar placeholder.
  playerLeading(player) {
    return player.team_logo_html ? this.logoBox(player.team_logo_html) : this.avatarBox(player.name)
  }

  // player.team_logo_html is server-rendered, trusted markup (an inline SVG or
  // fallback span). It is injected raw; no user-derived field is involved.
  logoBox(logoHtml) {
    const box = document.createElement("span")
    box.className = "stat-search-result__icon stat-search-result__logo"
    box.innerHTML = logoHtml
    return box
  }

  resultLink(href) {
    const link = document.createElement("a")
    link.href = href
    link.className = "stat-search-result"
    return link
  }

  resultBody(name, meta) {
    const body = document.createElement("span")
    body.className = "stat-search-result__body"

    const nameEl = document.createElement("span")
    nameEl.className = "stat-search-result__name"
    this.appendHighlighted(nameEl, name)
    body.append(nameEl)

    if (meta) {
      const metaEl = document.createElement("span")
      metaEl.className = "stat-search-result__meta"
      metaEl.textContent = meta
      body.append(metaEl)
    }

    return body
  }

  // Appends the name to the element, wrapping every case-insensitive match of
  // the current query in a highlight span. Built from text nodes (never
  // innerHTML) so result names can't inject markup.
  appendHighlighted(el, text) {
    const query = this.highlightQuery || ""
    const lowerText = text.toLowerCase()
    const lowerQuery = query.toLowerCase()

    if (!query || !lowerText.includes(lowerQuery)) {
      el.append(document.createTextNode(text))
      return
    }

    let index = 0
    let match = lowerText.indexOf(lowerQuery)

    while (match !== -1) {
      if (match > index) el.append(document.createTextNode(text.slice(index, match)))

      const mark = document.createElement("span")
      mark.className = "stat-search-highlight"
      mark.textContent = text.slice(match, match + query.length)
      el.append(mark)

      index = match + query.length
      match = lowerText.indexOf(lowerQuery, index)
    }

    if (index < text.length) el.append(document.createTextNode(text.slice(index)))
  }

  statIconBox() {
    const box = document.createElement("span")
    box.className = "stat-search-result__icon"
    if (this.hasStatIconTarget) box.innerHTML = this.statIconTarget.innerHTML
    return box
  }

  avatarBox(name) {
    const box = document.createElement("span")
    box.className = "stat-search-result__icon stat-search-result__avatar"
    box.textContent = (name || "").trim().charAt(0).toUpperCase()
    return box
  }

  resetRemote() {
    if (this.searchTimeout) clearTimeout(this.searchTimeout)
    if (this.abortController) this.abortController.abort()
    this.statMatches = []
    this.fetchedPlayers = []
    this.hideLoading()
  }

  hideResults() {
    this.resultsTarget.hidden = true
    this.resultsTarget.replaceChildren()
  }
}

import { Controller } from "@hotwired/stimulus";

// Toggles StatBuilder+'s "Custom Split" column between its Total (sum) and
// Avg/Game values for every row at once. Both values are already rendered in
// the DOM by Components::StatBuilder::ResultsTable (no network request on
// toggle) — this just flips which span is hidden and which segment button
// looks active.
export default class extends Controller {
  static targets = ["sum", "avg", "sumButton", "avgButton"];
  static classes = ["hidden", "activeButton"];

  showSum() {
    this._setMode(true);
  }

  showAvg() {
    this._setMode(false);
  }

  _setMode(showSum) {
    this.sumTargets.forEach((el) => el.classList.toggle(this.hiddenClass, !showSum));
    this.avgTargets.forEach((el) => el.classList.toggle(this.hiddenClass, showSum));

    // Plural targets: MatchupIQ+ renders the toggle twice (Offense header on
    // desktop, the STAT header on mobile) against this one controller, so
    // every copy's buttons must stay in sync.
    this.sumButtonTargets.forEach((btn) => {
      btn.classList.toggle(this.activeButtonClass, showSum);
      btn.setAttribute("aria-pressed", String(showSum));
    });

    this.avgButtonTargets.forEach((btn) => {
      btn.classList.toggle(this.activeButtonClass, !showSum);
      btn.setAttribute("aria-pressed", String(!showSum));
    });
  }
}

import { Controller } from "@hotwired/stimulus"

// Keeps a sticky element nested beneath the site chrome that is actually on
// screen, and publishes the total vertical clearance it occupies — chrome
// offset plus its own rendered height — as a CSS custom property on its
// parent, so sibling anchor targets can size scroll-margin-top to land just
// below it.
//
// Everything is measured live because none of it is static: the chrome
// selector may match a fixed navbar, a banner that is fixed on desktop but
// scrolls away on mobile, or nothing at all once the banner is retired; and
// the element's own height changes with its collapse state and viewport
// width. Without a chrome selector the element's CSS `top` is left alone and
// only the clearance property is published.
export default class extends Controller {
  static values = { property: String, chrome: String }

  connect() {
    this.observer = new ResizeObserver(() => this.update())
    this.observer.observe(this.element)
    this.onScroll = () => this.#queueUpdate()
    addEventListener("scroll", this.onScroll, { passive: true })
    addEventListener("resize", this.onScroll, { passive: true })
    this.update()
  }

  disconnect() {
    this.observer.disconnect()
    removeEventListener("scroll", this.onScroll)
    removeEventListener("resize", this.onScroll)
  }

  // The element's own `top` nests under everything currently visible, but
  // the published clearance counts only fixed chrome: sticky chrome (the
  // mobile navbar) scrolls away with the page, so it is gone by the time an
  // anchor jump lands — sizing scroll margins against it would leave a gap
  // and misplace the current-section line.
  update() {
    const visible = this.#chromeClearance(false)
    const pinned = this.#chromeClearance(true)
    const applied = `${visible}:${pinned}:${this.element.offsetHeight}`
    if (applied === this.lastApplied) return

    this.lastApplied = applied
    if (this.hasChromeValue) this.element.style.top = `${visible}px`
    this.element.parentElement.style.setProperty(
      this.propertyValue,
      `${pinned + this.element.offsetHeight}px`,
    )
  }

  #queueUpdate() {
    if (this.ticking) return

    this.ticking = true
    requestAnimationFrame(() => {
      this.ticking = false
      this.update()
    })
  }

  // The bottom edge of the lowest qualifying chrome element — the line the
  // sticky element must sit below.
  #chromeClearance(pinnedOnly) {
    if (!this.hasChromeValue) return parseFloat(getComputedStyle(this.element).top) || 0

    let clearance = 0
    for (const chrome of document.querySelectorAll(this.chromeValue)) {
      const { position } = getComputedStyle(chrome)
      if (position !== "fixed" && (pinnedOnly || position !== "sticky")) continue

      clearance = Math.max(clearance, chrome.getBoundingClientRect().bottom)
    }
    return clearance
  }
}

// FIXME: es-module-shim won't shim the dynamic import without this explicit import
import "@hotwired/stimulus"

const controllerAttribute = "data-controller"

// Eager load all controllers registered beneath the `under` path in the import map to the passed application instance.
export function eagerLoadControllersFrom(under, application) {
  const paths = Object.keys(parseImportmapJson()).filter(path => path.match(new RegExp(`^${under}/.*_controller$`)))
  paths.forEach(path => registerControllerFromPath(path, under, application))
}

function parseImportmapJson() {
  return JSON.parse(document.querySelector("script[type=importmap]").text).imports
}

function registerControllerFromPath(path, under, application) {
  const name = path
    .replace(new RegExp(`^${under}/`), "")
    .replace("_controller", "")
    .replace(/\//g, "--")
    .replace(/_/g, "-")

  if (canRegisterController(name, application)) {
    import(path)
      .then(module => registerController(name, module, application))
      .catch(error => console.error(`Failed to register controller: ${name} (${path})`, error))
  }
}


// Lazy load controllers registered beneath the `under` path in the import map to the passed application instance.
export function lazyLoadControllersFrom(under, application, element = document) {
  lazyLoadExistingControllers(under, application, element)
  lazyLoadNewControllers(under, application, element)
}

function lazyLoadExistingControllers(under, application, element) {
  queryControllerNamesWithin(element).forEach(controllerName => loadController(controllerName, under, application))
}

function lazyLoadNewControllers(under, application, element) {
  new MutationObserver((mutationsList) => {
    for (const { attributeName, target, type } of mutationsList) {
      switch (type) {
        case "attributes": {
          if (attributeName == controllerAttribute && target.getAttribute(controllerAttribute)) {
            extractControllerNamesFrom(target).forEach(controllerName => loadController(controllerName, under, application))
          }
        }

        case "childList": {
          lazyLoadExistingControllers(under, application, target)
        }
      }
    }
  }).observe(element, { attributeFilter: [controllerAttribute], subtree: true, childList: true })
}

function queryControllerNamesWithin(element) {
  return Array.from(element.querySelectorAll(`[${controllerAttribute}]`)).map(extractControllerNamesFrom).flat()
}

function extractControllerNamesFrom(element) {
  return element.getAttribute(controllerAttribute).split(/\s+/).filter(content => content.length)
}

function loadController(name, under, application) {
  if (canRegisterController(name, application)) {
    import(controllerFilename(name, under))
      .then(module => registerController(name, module, application))
      .catch(error => console.error(`Failed to autoload controller: ${name}`, error))
  }
}

function controllerFilename(name, under) {
  return `${under}/${name.replace(/--/g, "/").replace(/-/g, "_")}_controller`
}

function registerController(name, module, application) {
  if (canRegisterController(name, application)) {
    application.register(name, module.default)
  }
}

function canRegisterController(name, application){
  return !application.router.modulesByIdentifier.has(name)
}

