// Survivor Map client-side persistence -- the store backing the grid's USED
// badges. Everything here is device-local localStorage; nothing is
// server-persisted.
//
// Also home to the Splash entries CSV importer: parsing, validation, and
// the team-name matching it needs. All pure functions (Node-testable, see
// spec/javascript/survivor_splash_csv_spec.mjs).

const USED_KEY = "sr.survivor.used.v1";
const CSV_KEY = "sr.survivor.csv.v1";
const NAMES_KEY = "sr.survivor.names.v1";
const SPLASH_KEY = "sr.survivor.splash.v1";

function read(key, fallback) {
  try {
    return JSON.parse(localStorage.getItem(key) || "null") ?? fallback;
  } catch {
    return fallback;
  }
}

function write(key, value) {
  try {
    localStorage.setItem(key, JSON.stringify(value));
  } catch {
    // Private mode / blocked storage: the page still works, state just
    // doesn't survive a reload.
  }
}

// { ABBR: true, ... } -- manually marked used teams.
export function loadUsed() {
  return read(USED_KEY, {});
}
export function persistUsed(next) {
  write(USED_KEY, next);
}

// { order: [handle, ...], entries: { handle: [usedAbbr, ...] } } -- the
// subscriber's parsed Splash entries CSV. null until they upload one.
export function loadCsvEntries() {
  const v = read(CSV_KEY, null);
  return v && Array.isArray(v.order) && v.entries ? v : null;
}
export function persistCsvEntries(next) {
  write(CSV_KEY, next);
}

// { handle: displayName, ... } -- subscriber renames for entry pills.
export function loadEntryNames() {
  return read(NAMES_KEY, {});
}
export function persistEntryNames(next) {
  write(NAMES_KEY, next);
}

// Per-device Splash presentation toggle -- whale marks + 2x double-week
// badges. Defaults to off: the page reads as a generic single-pick survivor
// grid until a visitor opts in.
export function loadSplashMode() {
  return read(SPLASH_KEY, false);
}
export function persistSplashMode(next) {
  write(SPLASH_KEY, next);
}

export const STORAGE_KEYS = {
  used: USED_KEY, csv: CSV_KEY, names: NAMES_KEY, splash: SPLASH_KEY,
};

/* =========================================================================
 * Contest entries CSV import.
 *
 * Generic export format (one row per entry, works for any pool site):
 *
 *   Contest Name,Handle,Week 1,Week 2,...
 *   ,your-entry-1,San Francisco,Baltimore,"Cincinnati, Miami",...
 *
 * - "Handle" identifies the entry; "Contest Name" may be blank.
 * - Week cells hold full team names or cities; a double week's cell holds
 *   two teams separated by a comma (so the cell arrives quoted).
 * ========================================================================= */

// Minimal RFC-4180-ish CSV parser: quoted cells (with embedded commas and
// "" escapes), \r\n or \n line endings. Returns an array of rows, each an
// array of cell strings.
export function parseCsvRows(text) {
  const rows = [];
  let row = [];
  let cell = "";
  let inQuotes = false;
  const src = String(text || "");
  for (let i = 0; i < src.length; i++) {
    const ch = src[i];
    if (inQuotes) {
      if (ch === '"') {
        if (src[i + 1] === '"') { cell += '"'; i++; } else { inQuotes = false; }
      } else {
        cell += ch;
      }
    } else if (ch === '"') {
      inQuotes = true;
    } else if (ch === ",") {
      row.push(cell); cell = "";
    } else if (ch === "\n" || ch === "\r") {
      if (ch === "\r" && src[i + 1] === "\n") i++;
      row.push(cell); cell = "";
      rows.push(row); row = [];
    } else {
      cell += ch;
    }
  }
  if (cell !== "" || row.length > 0) { row.push(cell); rows.push(row); }
  return rows;
}

// Builds every alias a Splash cell might use for each team from the odds
// payload's teams list: full name ("San Francisco 49ers"), city ("San
// Francisco"), nickname ("49ers"), and abbreviation ("SF"). An alias shared
// by two teams (e.g. "New York") maps to null so the importer can report it
// as ambiguous instead of guessing.
export function buildTeamNameIndex(teams) {
  const index = {};
  const put = (alias, abbr) => {
    const key = alias.toLowerCase().trim();
    if (!key) return;
    if (Object.prototype.hasOwnProperty.call(index, key) && index[key] !== abbr) index[key] = null;
    else index[key] = abbr;
  };
  teams.forEach((t) => {
    const name = String(t.name || "").trim();
    const words = name.split(/\s+/);
    put(name, t.abbr);
    put(words.slice(0, -1).join(" "), t.abbr); // city ("San Francisco", "LA")
    put(words[words.length - 1], t.abbr);      // nickname ("49ers")
    put(t.abbr, t.abbr);
  });
  return index;
}

function headerError(headerRow) {
  const cells = headerRow.map((c) => c.trim().toLowerCase());
  if (!cells.includes("handle")) {
    return 'Missing the "Handle" column — the first row must be a header like "Contest Name,Handle,Week 1,Week 2,…". Download the sample CSV to see the expected format.';
  }
  if (!cells.some((c) => /^week\s*\d+$/.test(c))) {
    return 'No "Week" columns found — each pick belongs in a "Week 1", "Week 2", … column. Download the sample CSV to see the expected format.';
  }
  return null;
}

function matchTeams(cellValue, teamIndex, rowNum, weekNum, errors) {
  return cellValue.split(",").map((raw) => raw.trim()).filter((raw) => raw !== "").map((raw) => {
    const abbr = teamIndex[raw.toLowerCase()];
    if (abbr === null) {
      errors.push(`Row ${rowNum}, Week ${weekNum}: "${raw}" matches more than one NFL team — use the team's nickname (e.g. "Giants" or "Jets") instead.`);
      return null;
    }
    if (!abbr) {
      errors.push(`Row ${rowNum}, Week ${weekNum}: "${raw}" doesn't match any NFL team. Check the spelling, or use the team's full name.`);
      return null;
    }
    return abbr;
  }).filter(Boolean);
}

// Parses + validates a Splash entries CSV against the page's team list.
// Returns { entries: { order, entries } } on success, or { errors: [...] }
// with every problem found (so the user can fix the file in one pass).
// A file with any error imports nothing -- never a silently partial import.
export function parseSplashCsv(text, teams) {
  const rows = parseCsvRows(text).filter((row) => row.some((cell) => cell.trim() !== ""));
  if (rows.length === 0) return { errors: ["The file is empty. Download the sample CSV to see the expected format."] };

  const headerProblem = headerError(rows[0]);
  if (headerProblem) return { errors: [headerProblem] };

  const header = rows[0].map((c) => c.trim().toLowerCase());
  const handleCol = header.indexOf("handle");
  const weekCols = [];
  header.forEach((cell, i) => {
    const m = cell.match(/^week\s*(\d+)$/);
    if (m) weekCols.push({ col: i, week: parseInt(m[1], 10) });
  });

  const teamIndex = buildTeamNameIndex(teams);
  const errors = [];
  const order = [];
  const entries = {};
  const handleRows = {};

  rows.slice(1).forEach((row, i) => {
    const rowNum = i + 2; // 1-based, after the header row
    const handle = (row[handleCol] || "").trim();
    if (!handle) {
      errors.push(`Row ${rowNum} has no Handle — every entry row needs one so its picks can be told apart.`);
      return;
    }
    if (Object.prototype.hasOwnProperty.call(entries, handle)) {
      errors.push(`Rows ${handleRows[handle]} and ${rowNum} both use the handle "${handle}" — handles must be unique.`);
      return;
    }
    const picks = [];
    const seenWeeks = {};
    weekCols.forEach(({ col, week }) => {
      matchTeams(row[col] || "", teamIndex, rowNum, week, errors).forEach((abbr) => {
        if (Object.prototype.hasOwnProperty.call(seenWeeks, abbr)) {
          errors.push(`Row ${rowNum}: ${abbr} appears twice (Week ${seenWeeks[abbr]} and Week ${week}) — a survivor entry can only use a team once.`);
        } else {
          seenWeeks[abbr] = week;
          picks.push(abbr);
        }
      });
    });
    handleRows[handle] = rowNum;
    order.push(handle);
    entries[handle] = picks;
  });

  if (errors.length > 0) return { errors };
  if (order.length === 0) return { errors: ["No entry rows found below the header. Download the sample CSV to see the expected format."] };
  return { entries: { order, entries } };
}

import { Controller } from "@hotwired/stimulus"

// Visual feedback for the two manual odds-engine triggers ("Sync odds now"
// and "Full sweep"), replacing a text status line with the sync icon
// itself: spins from the moment either form submits (before any server
// response -- see startSpinning, bound to each form's submit event) until
// the sync's effects are observed, then stops -- flashing the "Last
// updated" timestamp green only when THIS view's own data changed.
//
// Both buttons' icons spin and stop together, even though only one was
// clicked: there is no way to distinguish "the fast lane finished" from
// "the full sweep finished" from the client's side (both push the same
// timestamp-change / turbo:render signals below, and both share one
// server-side lock -- see odds-engine's api_server.py), so tracking them
// separately would be false precision. Both icons showing "something is
// happening" together is honest about what's actually observable.
//
// Two independent stop signals, because one sync can legitimately produce
// either outcome depending on which league happens to be on screen:
//
// 1. The timestamp's own datetime attribute changing -- guaranteed to
//    change when, and only when, the currently-viewed league's own data
//    advanced. Stops the spin AND flashes green.
// 2. A document-level `turbo:render` event -- dispatched whenever Turbo
//    finishes rendering a page, including the full-page morph a
//    Turbo::StreamsChannel.broadcast_refresh_to triggers (see
//    WatermarkBroadcast), regardless of whether the morph diff actually
//    changed anything. A full sweep touches ~50 leagues; the one currently
//    on screen (e.g. NFL in the off-season) can legitimately get zero new
//    rows while the sweep as a whole completes successfully in well under a
//    minute -- signal 1 alone would never fire, and the spinner would spin
//    for its full 90-second timeout looking hung. Stops the spin, no flash
//    (nothing new for *this* view).
//
// LiveOddsController#sync / #poll render real text into their own status
// target only for genuine failures (not configured, connection error) --
// "started" and "already running" render nothing, since the spinner already
// says "something is happening". A MutationObserver on each status target's
// text stops the spin immediately when an error appears, since nothing is
// coming. Each button gets its own status line (SyncButton::FAST_STATUS_DOM_ID
// / SLOW_STATUS_DOM_ID), so an error from one never displaces the other's.
export default class extends Controller {
  static targets = ["icon", "status", "timestamp"]
  static classes = ["spinning", "flash"]

  // Backstop so a lost response (odds-engine down, network drop after the
  // initial ack) doesn't spin forever with no explanation -- comfortably
  // longer than a full sweep takes end to end (see RAILS_TRIGGER.md).
  static values = {
    timeoutMs: { type: Number, default: 90_000 },
    // How long the flash class stays on before it's removed -- matches the
    // live-odds-updated-flash keyframe animation's own duration
    // (live_odds.scss) so the class comes off right as the two-pulse
    // animation finishes, not mid-pulse.
    flashHoldMs: { type: Number, default: 1400 },
  }

  // Class field, not connect()-initialized: Stimulus invokes *TargetConnected
  // callbacks (statusTargetConnected below, for any target already present
  // when this controller starts) BEFORE calling connect() itself, not
  // after -- confirmed live via the browser console, where initializing
  // this Map in connect() instead produced "Cannot read properties of
  // undefined (reading 'set')" inside statusTargetConnected on every single
  // page load. Stimulus caught that exception by silently abandoning this
  // controller's entire connection (logged once as "Failed to autoload
  // controller: sync-status", easy to miss) -- meaning connect() itself,
  // and both MutationObservers this whole spinner/flash mechanism depends
  // on, never ran at all. A class field is set during construction, before
  // Stimulus touches any lifecycle method, so it's guaranteed to exist no
  // matter which callback fires first.
  _statusObservers = new Map()

  connect() {
    this._onTurboRender = () => this.stopSpinning({ flash: false })
    document.addEventListener("turbo:render", this._onTurboRender)
  }

  disconnect() {
    this.timestampObserver?.disconnect()
    this._statusObservers.forEach((observer) => observer.disconnect())
    document.removeEventListener("turbo:render", this._onTurboRender)
    this._clearTimeout()
  }

  // Stimulus target lifecycle callback -- self-contained (builds its own
  // observer fresh, touches no connect()-initialized state), so it isn't
  // vulnerable to the *TargetConnected-before-connect() ordering that broke
  // statusTargetConnected (see the _statusObservers field comment). Kept as
  // a *Connected callback rather than folded into connect() anyway: it
  // fires again correctly if this target is ever removed and re-added,
  // which a one-time connect()-only setup would not survive.
  timestampTargetConnected(element) {
    this.timestampObserver = new MutationObserver(() => this.stopSpinning({ flash: true }))
    this.timestampObserver.observe(element, { attributes: true, attributeFilter: ["datetime"] })
  }

  timestampTargetDisconnected() {
    this.timestampObserver?.disconnect()
  }

  // Stimulus target lifecycle callback, called once per "status" target as
  // it connects -- there are two (one per button), each needing its own
  // observer since either one gaining text should stop the spin.
  statusTargetConnected(element) {
    const observer = new MutationObserver(() => {
      if (element.textContent.trim()) this.stopSpinning({ flash: false })
    })
    observer.observe(element, { childList: true, characterData: true, subtree: true })
    this._statusObservers.set(element, observer)
  }

  statusTargetDisconnected(element) {
    this._statusObservers.get(element)?.disconnect()
    this._statusObservers.delete(element)
  }

  // Disabled while spinning, on both buttons (they share one spinning state
  // -- see the class comment on why there's no separate per-button state to
  // disable independently): stops a second click from firing a request the
  // server will just 409 while the first is still in flight, which was
  // silently swallowing the reason the spinner looked stuck -- "already
  // running" renders no status text at all (STATUS_MESSAGES has no entry
  // for it, the spinner already says "something is happening"), so a
  // rejected second click gave no sign anything was wrong.
  //
  // Deliberately aria-disabled + pointer-events: none, not the native
  // disabled attribute: Turbo Drive automatically disables and then
  // re-enables a form's own submitter around its own request/response
  // cycle, and since that turbo_stream response typically lands in well
  // under 100ms (long before the real sync actually finishes), it was
  // fighting this and re-enabling the very button someone just clicked
  // almost immediately -- confirmed live. aria-disabled is inert to Turbo's
  // own button management, so nothing re-enables it out from under this
  // until stopSpinning says so. Screen readers still announce it as
  // disabled; sighted users get the same visual + click-blocking via CSS
  // (live_odds.scss's :disabled rule, which also targets aria-disabled).
  // One iconTarget (AdminSyncControls' summary icon) isn't inside a
  // <button> at all -- optional chaining skips it rather than throwing.
  //
  // Also closes the admin panel immediately on submit: the summary icon
  // above keeps showing "something is happening" even once it's closed, so
  // there's no need to keep the panel open just to see the spin, and
  // closing it gets the admin-only chrome back out of the way of the board
  // they actually clicked to refresh.
  startSpinning(event) {
    this.iconTargets.forEach((icon) => {
      icon.classList.add(this.spinningClass)
      icon.closest("button")?.setAttribute("aria-disabled", "true")
    })
    event.target.closest(".live-odds-admin-controls")?.removeAttribute("open")
    this._clearTimeout()
    this._timeout = setTimeout(() => this.stopSpinning({ flash: false }), this.timeoutMsValue)
  }

  stopSpinning({ flash }) {
    this.iconTargets.forEach((icon) => {
      icon.classList.remove(this.spinningClass)
      icon.closest("button")?.removeAttribute("aria-disabled")
    })
    this._clearTimeout()

    if (flash && this.hasTimestampTarget) {
      // The flash class lives in live_odds.scss on .live-odds-updated, the
      // <span> wrapping "Updated " + this <time> element -- flash the whole
      // line, not just the timestamp inside it.
      const line = this.timestampTarget.closest(".live-odds-updated") || this.timestampTarget
      line.classList.remove(this.flashClass)
      // Force a reflow so re-adding the class restarts its animation if
      // this line is still mid-flash from a broadcast moments ago.
      void line.offsetWidth
      line.classList.add(this.flashClass)
      setTimeout(() => line.classList.remove(this.flashClass), this.flashHoldMsValue)
    }
  }

  _clearTimeout() {
    if (this._timeout) clearTimeout(this._timeout)
    this._timeout = null
  }
}

import { Controller } from "@hotwired/stimulus"
import { dispatchAnalytics } from "dispatch_analytics"

export default class extends Controller {
  static targets = ["tab", "panel"]
  static classes = ["active", "hidden"]

  connect() {
    const hash = window.location.hash.replace("#", "")
    const urlTab = new URLSearchParams(window.location.search).get("tab")
    const initial = hash || urlTab || this.tabTargets[0]?.dataset.tab
    if (initial) this.show(initial)
  }

  select(event) {
    event.preventDefault()
    const tab = event.currentTarget.dataset.tab
    dispatchAnalytics("tab_select", { tab_name: tab })
    this.show(tab)
    window.history.replaceState(null, "", `#${tab}`)
  }

  show(name) {
    for (const tab of this.tabTargets) {
      tab.classList.toggle(this.activeClass, tab.dataset.tab === name)
    }
    for (const panel of this.panelTargets) {
      panel.classList.toggle(this.hiddenClass, panel.dataset.tab !== name)
    }
  }
}

import { Controller } from "@hotwired/stimulus"
import { dispatchAnalytics } from "dispatch_analytics"

export default class extends Controller {
  static classes = ["dark"]

  connect() {
    const saved = localStorage.getItem("theme")
    // Default to dark if no preference saved. The inline <head> script already
    // applied the correct class before first paint; this keeps it correct on
    // Turbo navigations where the inline script does not re-run.
    if (saved === "light") {
      document.documentElement.classList.remove(this.darkClass)
    } else {
      document.documentElement.classList.add(this.darkClass)
    }
  }

  toggle() {
    const html = document.documentElement
    html.classList.toggle(this.darkClass)
    const theme = html.classList.contains(this.darkClass) ? "dark" : "light"
    localStorage.setItem("theme", theme)
    dispatchAnalytics("theme_toggle", { theme })
  }
}

import { Controller } from "@hotwired/stimulus"

// Auto-dismisses a UI::Toast banner after dismissAfterValue ms, or
// immediately on manual dismiss. Fades out via CSS transition (skipped for
// prefers-reduced-motion) before removing the element.
export default class extends Controller {
  static values = { dismissAfter: Number }

  connect() {
    this.timeout = setTimeout(() => this.dismiss(), this.dismissAfterValue)
  }

  disconnect() {
    clearTimeout(this.timeout)
  }

  dismiss() {
    clearTimeout(this.timeout)
    this.element.classList.add("toast--dismissing")
    this.element.addEventListener("transitionend", () => this.element.remove(), { once: true })
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) this.element.remove()
  }
}

import { Controller } from "@hotwired/stimulus";
import { dispatchAnalytics } from "dispatch_analytics";

// Navigation for every shape of the sibling-tool switcher (segmented pills,
// single-button, and the mobile <select> fallback -- see
// Components::Stats::ToolSwitcher) for StatBuilder+/PlayerComparison+/
// MatchupIQ+.
//
// Every href/option value is rendered once, server-side, from whatever
// ?stats=/?weeks= the current *full page load* had -- but toggling a stat or
// week only replaces the turbo_frame_tag each tool's own controls live
// inside. That in-frame "advance" navigation still updates window.location
// (Turbo pushes history for frame navigations too), but nothing outside the
// frame re-renders -- this switcher, sitting in the page header, included.
// So a switcher link's baked-in ?stats=/?weeks= silently goes stale the
// moment the user changes either after the initial load.
//
// Rewriting them here, at the moment of navigation, is the only point
// guaranteed correct: window.location itself is always current regardless
// of how it got there, and connect() only fires once (this element is
// outside the frame, so it never reconnects when the frame updates).
const CARRY_PARAMS = ["stats", "weeks"];

export default class extends Controller {
  visitLink(event) {
    event.preventDefault();
    const href = event.currentTarget.href;
    dispatchAnalytics("tool_switch", { tool: this.#toolName(href) });
    Turbo.visit(this.#withCurrentParams(href));
  }

  // The current tool's <option> carries an empty value, so re-selecting it
  // (or a stray change event) is a no-op rather than navigating to the root
  // URL.
  visitSelect(event) {
    const url = event.target.value;
    if (!url) return;

    dispatchAnalytics("tool_switch", { tool: this.#toolName(url) });
    Turbo.visit(this.#withCurrentParams(url));
  }

  // The destination tool's identifier is the last path segment of its route
  // (e.g. "/nfl/advanced/matchup-iq" -> "matchup-iq") -- a stable, readable
  // param without threading the display name through a data attribute.
  #toolName(href) {
    const segments = new URL(href, window.location.origin).pathname.split("/").filter(Boolean);
    return segments[segments.length - 1] || "";
  }

  #withCurrentParams(href) {
    const url = new URL(href, window.location.origin);
    const current = new URLSearchParams(window.location.search);
    CARRY_PARAMS.forEach(param => {
      if (current.has(param)) url.searchParams.set(param, current.get(param));
    });
    return url.toString();
  }
}

import { Controller } from "@hotwired/stimulus"

// Keeps an absolutely-positioned tooltip within the viewport regardless of
// where its trigger sits. The tooltip's base position is centered on the trigger
// (CSS applies translateX(-50%)); this controller measures the tooltip on
// open and sets the `--tooltip-shift` custom property, which CSS adds to that
// transform so the body slides back on-screen while the arrow stays on the icon.
export default class extends Controller {
  static targets = ["tooltip"]
  static values = { margin: { type: Number, default: 8 } }

  connect() {
    this.reposition = this.reposition.bind(this)
    this.element.addEventListener("pointerenter", this.reposition)
    this.element.addEventListener("focusin", this.reposition)
    this.element.addEventListener("touchstart", this.reposition, { passive: true })
  }

  disconnect() {
    this.element.removeEventListener("pointerenter", this.reposition)
    this.element.removeEventListener("focusin", this.reposition)
    this.element.removeEventListener("touchstart", this.reposition)
  }

  reposition() {
    if (!this.hasTooltipTarget) return

    const tip = this.tooltipTarget
    const margin = this.marginValue
    const rect = this.element.getBoundingClientRect()
    const center = rect.left + rect.width / 2
    const half = tip.offsetWidth / 2
    const viewport = document.documentElement.clientWidth

    // Clamp within the nearest ancestor that actually clips overflow — a
    // .content-container card (overflow: hidden) or a table's overflow-x: auto
    // scroll wrapper — otherwise the viewport. Keep the tooltip centered on
    // the trigger, nudging only as far as needed to clear each edge; the
    // right-edge fit is applied last so it wins when both can't be satisfied.
    const clip = this.clippingAncestor()
    const clipRect = clip ? clip.getBoundingClientRect() : null
    const leftBound = Math.max(margin, clipRect ? clipRect.left + margin : margin)
    const rightBound = clipRect
      ? Math.min(viewport - margin, clipRect.right - margin)
      : viewport - margin

    let shift = 0
    if (center - half < leftBound) {
      shift = leftBound - (center - half)
    }
    if (center + half + shift > rightBound) {
      shift = rightBound - (center + half)
    }

    tip.style.setProperty("--tooltip-shift", `${Math.round(shift)}px`)
  }

  // Nearest ancestor whose horizontal overflow clips (hidden/auto/scroll/clip).
  // Generalizes the old hardcoded .content-container lookup so tooltips inside
  // any scrollable table wrapper shift back into view instead of being cut off.
  clippingAncestor() {
    let el = this.element.parentElement
    while (el && el !== document.body) {
      if (getComputedStyle(el).overflowX !== "visible") return el
      el = el.parentElement
    }
    return null
  }
}

// Shared "refresh a single Turbo Frame in place" primitives, used by any
// Stimulus controller that debounces a user interaction into a scoped
// re-fetch of the current page (customize-weeks, StatBuilder+ stat picker,
// StatBuilder+ player search) instead of a full Turbo visit.
//
// Split into two steps — network fetch and DOM swap — rather than one
// combined function, so a caller that needs to gate the swap on extra state
// (e.g. a staleness/generation check) can inspect the fetched html before
// applying it, without re-implementing the fetch/parse mechanics itself.

export const DEBOUNCE_MS = 300;

// Fetches the current page scoped to a single Turbo Frame and returns the
// raw response HTML. Rejects with an AbortError if `signal` is aborted, and
// now also rejects on a non-2xx response (a 503/504 body has no
// turbo-frame#<id> in it, so applyFrameSwap silently no-ops on it -- the
// caller never learns the request failed, and the stale table sits there
// with no indication it stopped reflecting the selected filters). Throwing
// here is what lets a caller's .catch() show an error state instead.
export async function fetchFrameHtml(frameId, { signal } = {}) {
  const response = await fetch(window.location.href, {
    signal,
    headers: {
      "Turbo-Frame": frameId,
      "Accept": "text/html, application/xhtml+xml",
    },
  });
  if (!response.ok) throw new Error(`Turbo Frame fetch failed: ${response.status}`);
  return response.text();
}

// Parses fetched html and swaps the matching frame's content into the live
// DOM in place. Returns the live frame element, or null if either side is
// missing (nothing to swap).
export function applyFrameSwap(html, frameId) {
  const doc = new DOMParser().parseFromString(html, "text/html");
  const newFrame = doc.querySelector(`turbo-frame#${frameId}`);
  const currentFrame = document.getElementById(frameId);
  if (newFrame && currentFrame) {
    currentFrame.innerHTML = newFrame.innerHTML;
    return currentFrame;
  }
  return null;
}

// Loading/error state for the frame while a refresh is in flight, toggled on
// the <turbo-frame> element itself rather than anything inside it -- the
// frame element survives applyFrameSwap's innerHTML replacement (only its
// children are torn down), so a class/attribute set here is still present
// the instant the fetch resolves, even though every Stimulus controller and
// DOM node the swap touches gets rebuilt from scratch. CSS reads
// LOADING_CLASS/ERROR_CLASS off the frame to dim the (stale, still-visible)
// table and reveal a status badge without any layout shift -- see
// week_splits_filter.scss.
export const LOADING_CLASS = "turbo-frame-refresh-loading";
export const ERROR_CLASS = "turbo-frame-refresh-error";
const STATUS_SELECTOR = "[data-turbo-frame-refresh-status]";

export function beginFrameLoading(frameId) {
  const frame = document.getElementById(frameId);
  if (!frame) return;
  frame.classList.remove(ERROR_CLASS);
  frame.classList.add(LOADING_CLASS);
  frame.setAttribute("aria-busy", "true");
  const status = frame.querySelector(STATUS_SELECTOR);
  if (status) status.textContent = "Updating results…";
}

export function endFrameLoading(frameId, { error = false } = {}) {
  const frame = document.getElementById(frameId);
  if (!frame) return;
  frame.classList.remove(LOADING_CLASS);
  frame.removeAttribute("aria-busy");
  frame.classList.toggle(ERROR_CLASS, error);
  // On success the freshly-swapped-in status node already replaced this one;
  // setting text on the (about to be discarded) old node would announce
  // nothing. On error nothing swapped, so this is still the live node.
  if (error) {
    const status = frame.querySelector(STATUS_SELECTOR);
    if (status) status.textContent = "Couldn't update — showing the last loaded results.";
  }
}

import { Controller } from "@hotwired/stimulus";

export default class extends Controller {
  static values = { openOnConnect: Boolean };

  connect() {
    if (this.element.tagName === "DIALOG") {
      this.element.addEventListener("click", this.#backdropClose);
      // A dialog holding a form that came back rejected (a bad promo code on
      // the archive add-on card) has to reopen itself: the server replies with
      // a fresh page, and the error inside a closed dialog is invisible.
      if (this.openOnConnectValue) this.element.showModal();
    }
  }

  disconnect() {
    if (this.element.tagName === "DIALOG") {
      this.element.removeEventListener("click", this.#backdropClose);
    }
  }

  open(event) {
    this.#closeOpen();
    document.getElementById(event.params.id)?.showModal();
  }

  // Close before navigating away (e.g. the CTA link to checkout) so the
  // dialog isn't left in its "open" state for the bfcache to restore when
  // the user hits Back — otherwise the dialog reappears without its backdrop.
  close() {
    if (this.element.tagName === "DIALOG") this.element.close();
  }

  #closeOpen() {
    document
      .querySelectorAll("dialog.unlock-modal[open]")
      .forEach((dialog) => dialog.close());
  }

  #backdropClose = (event) => {
    if (event.target === this.element) this.element.close();
  };
}

import { Controller } from "@hotwired/stimulus";

const DEBOUNCE_MS = 300;

// Drives the V2 filter bar: native selects + text/number inputs
// that navigate a Turbo Frame by updating URL search params.
export default class extends Controller {
  static values = {
    frame:         { type: String, default: "stats-content" },
    // Matches SeasonHelper.nfl_season server-side — the season a blank/
    // single-selected "seasons" param falls back to, so the reset button
    // can tell a default selection from a real filter.
    currentSeason: Number,
  };
  static targets = ["display", "resetWrapper"];

  connect() {
    this._timers = new Map();
  }

  disconnect() {
    this._timers.forEach(t => clearTimeout(t));
  }

  // Called on <select> change events.
  navigate(event) {
    const display = event.currentTarget.closest(".v2-filter")?.querySelector("[data-v2-filter-target='display']");
    if (display) {
      const v = event.currentTarget.value;
      display.textContent = v === "" || v.toLowerCase() === "all" ? "All" : v;
    }
    this._update(event.params.name, event.currentTarget.value);
  }

  reset() {
    this._timers.forEach(t => clearTimeout(t));
    this._timers.clear();

    // Reset all selects and inputs within this card.
    this.element.querySelectorAll("select").forEach(el => { el.selectedIndex = 0; });
    this.element.querySelectorAll("input[type='text'], input[type='number']").forEach(el => { el.value = ""; });

    // Reset display spans that mirror select values (skip seasons — handled separately).
    this.element.querySelectorAll(".v2-filter__display").forEach(el => {
      if (!el.closest("[data-controller~='coverage-seasons']")) el.textContent = "All";
    });

    // Reset the seasons controller to just the most recent available season.
    const seasonsEl = this.element.querySelector("[data-controller~='coverage-seasons']");
    if (seasonsEl) {
      const ctrl = this.application.getControllerForElementAndIdentifier(seasonsEl, "coverage-seasons");
      if (ctrl && ctrl.optionTargets.length > 0) {
        const latestYear = parseInt(ctrl.optionTargets[0].dataset.value, 10);
        ctrl.activeValue = [latestYear];
        ctrl._syncUI();
      }
    }

    const url = new URL(window.location.href);
    ["position", "team", "player_name", "qualifier", "seasons"].forEach(p => url.searchParams.delete(p));
    url.searchParams.delete("page");
    history.replaceState(history.state, "", url.toString());

    const frame = document.getElementById(this.frameValue);
    if (frame) frame.src = url.toString();
    this.syncResetVisibility();
  }

  // Called on text/number input events — debounced 300ms.
  search(event) {
    const name = event.params.name;
    const value = event.currentTarget.value;
    clearTimeout(this._timers.get(name));
    this._timers.set(name, setTimeout(() => this._update(name, value), DEBOUNCE_MS));
  }

  // Also called by coverage-seasons#_commit — its own selection lives
  // outside this controller, but the reset button's default check needs to
  // account for it too.
  syncResetVisibility() {
    if (!this.hasResetWrapperTarget) return;

    const p = new URLSearchParams(window.location.search);
    const isDefault = (p.get("position") || "WR") === "WR"
      && !p.get("team") && !p.get("player_name") && !p.get("qualifier")
      && this._isDefaultSeasons(p);
    this.resetWrapperTarget.classList.toggle("hidden", isDefault);
  }

  _isDefaultSeasons(params) {
    const raw = params.get("seasons");
    if (!raw) return true;
    const years = raw.split(",").map(Number);
    return years.length === 1 && years[0] === this.currentSeasonValue;
  }

  _update(name, value) {
    const url = new URL(window.location.href);
    const v = (value ?? "").trim();
    if (v !== "" && v.toLowerCase() !== "all") {
      url.searchParams.set(name, v);
    } else {
      url.searchParams.delete(name);
    }
    url.searchParams.delete("page");
    history.replaceState(history.state, "", url.toString());
    const frame = document.getElementById(this.frameValue);
    if (frame) frame.src = url.toString();
    this.syncResetVisibility();
  }
}

import { Controller } from "@hotwired/stimulus"
import { dispatchAnalytics } from "dispatch_analytics"

// Multi-select week pills for the Playoff Schedule Grid: toggling a pill
// merges the selected weeks into the current URL as a comma list
// (?weeks=14,15,16) and navigates via Turbo, so the server HTML never
// contains crawlable filter anchors (same rationale as position-pill-strip,
// which is single-select).
export default class extends Controller {
  static targets = ["pill"]
  static classes = ["active"]
  static values = {
    param: String,
    frame: String,
    min: { type: Number, default: 2 },
  }

  toggle(event) {
    const pill = event.currentTarget
    const wasActive = pill.classList.contains(this.activeClass)
    if (wasActive && this.selectedValues().length <= this.minValue) return

    pill.classList.toggle(this.activeClass)
    pill.setAttribute("aria-pressed", String(!wasActive))

    dispatchAnalytics("filter_change", {
      filter_name: this.paramValue,
      filter_value: this.selectedValues().join(","),
    })

    this.navigate()
  }

  selectedValues() {
    return this.pillTargets
      .filter((pill) => pill.classList.contains(this.activeClass))
      .map((pill) => pill.dataset.value)
  }

  navigate() {
    const url = new URL(window.location.href)
    url.searchParams.set(this.paramValue, this.selectedValues().join(","))
    url.searchParams.delete("page")

    const turbo = window.Turbo
    if (!turbo) {
      window.location.assign(url.toString())
      return
    }

    if (this.frameValue) {
      turbo.visit(url.toString(), { frame: this.frameValue })
    } else {
      turbo.visit(url.toString())
    }
  }
}

import { Controller } from "@hotwired/stimulus";
import {
  DEBOUNCE_MS, fetchFrameHtml, applyFrameSwap, beginFrameLoading, endFrameLoading,
} from "turbo_frame_refresh";

// Drives the Customize Weeks control on the NFL stats pages
// (Components::Filters::NFLWeekSplitsFilter).
//
// Forked from modify_weeks_controller.js, which now serves only the premium
// tools' always-open weeks card (Components::Stats::WeeksSection). This copy
// drops the always-open path and the card's persistent header summary, and
// keeps only what the stats pages use: the collapsible trigger, the week
// pills, and the All Games / Home / Away / Last N buttons.
//
// Module-level state survives controller teardown when the turbo frame is
// replaced (the debounced fetch this controller schedules on every filter
// change swaps the frame's HTML, tearing down and reconnecting this same
// instance), so it has to persist here rather than as an instance field.
let visitTimer = null;
let pendingWeeks = null;
let abortController = null;
let visitGeneration = 0;
let activeVenues = new Set();
// The within-game selection. Shared with the venue/week state above for the
// same reason.
let activePortion = "full";
let activeZone = "full";
let activeExcludes = new Set();

export default class extends Controller {
  static targets = ["panel", "pill", "presetBtn", "venueBtn",
                    "portionBtn", "zoneSelect", "excludeBox", "triggerSummary",
                    "seasonBtn"];
  static classes = ["open", "active", "hidden", "hasSelection"];
  static values = {
    turboFrame:     { type: String, default: "stats-content" },
    availableWeeks: { type: Array, default: [] },
    signupUrl:      { type: String,  default: "" },
    // Must match NFLWeekSplitsFilter::FREE_PRESETS, which decides which buttons
    // render a lock icon. "full" belongs here: All Games is the same full-season
    // view a locked user already sees, so it unlocks no gated data, and leaving
    // it out paywalled a button that renders unlocked. Specific weeks and the
    // venue buttons stay gated.
    freePresets:    { type: Array,   default: ["full", "l1", "l3"] },
  };

  connect() {
    // Reset-then-read: this state is module-level and survives a turbo frame
    // swap, so a pending week edit left over from the previous page has to be
    // cleared before this page's own URL is read below, not merged with it.
    pendingWeeks = null;

    const url        = new URL(window.location.href);
    const weeksParam = url.searchParams.get("weeks");
    const venuesParam = url.searchParams.get("venues");

    // Detect premium params smuggled via URL: show modal and reset to l3
    // "All Games" (full preset or no weeks param) and l1/l3 are free; venues and specific weeks are locked.
    if (this.signupUrlValue && (weeksParam || venuesParam)) {
      const weekNums = (weeksParam || "").split(",").map(Number).filter(Boolean).toSorted((a, b) => a - b);
      const available = this.availableWeeksValue.toSorted((a, b) => a - b);
      const l1 = available.slice(-1);
      const l3 = available.slice(-3);
      const isAllGames = weeksParam && weekNums.length === available.length && weekNums.every((w, i) => w === available[i]);
